window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["med:med-clinica-medica-med-clm-19"]={"block":"med:med-clinica-medica-med-clm-19","label":"MED · MED CLM 19","count":437,"questions":[{"id":"med-clinica-medica-med-clm-19-281143","number":"281143","sourceNumber":"281143","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Em relação aos exames laboratoriais em paciente pediátrico com história de\nsangramento é CORRETO afirmar que:","options":{"A":"Na insuficiência hepática, a contagem de plaquetas está diminuída, o tempo de atividade de\nprotrombina está alterado e o tempo de tromboplastina tecidual ativado está normal.","B":"Na deficiência de vitamina K, a contagem de plaquetas está diminuída, o tempo de atividade de\nprotrombina está alterado e o tempo de tromboplastina tecidual ativado está normal.","C":"Nas hemofilias A e B, a contagem de plaquetas está normal e o tempo de atividade de\nprotrombina e o tempo de tromboplastina tecidual ativado estão alterados.","D":"Na aplasia medular, a contagem de plaquetas está diminuída e o tempo de atividade de\nprotrombina e o tempo de tromboplastina tecidual ativado estão normais.","E":"Na coagulação intravascular disseminada, a contagem de plaquetas está diminuída, o tempo de\natividade de protrombina está normal e o tempo de tromboplastina tecidual ativado está alterado."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-281150","number":"281150","sourceNumber":"281150","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Menino de três anos de idade é admitido no Pronto-Atendimento com queixa de\nepistaxe espontânea há algumas horas, de volume\npequeno. A mãe do paciente relata história de\ninfecção viral do trato gastrointestinal (diarreia aguda) há 2 semanas, com resolução completa. Ao\nexame: bom estado geral, corado, hidratado. Ausculta cardíaca e pulmonar sem alterações. Baço,\nfígado e linfonodos não palpáveis. Equimoses e petéquias evidentes em membros inferiores, sem\noutras alterações. Hemograma evidenciando: hemoglobina 13,0 g/dL; VCM 80 fL; leucócitos\n9.700/mm3, com contagem diferencial normal; plaquetas 15.000/mm3 ; 1% de reticulócitos. O\ndiagnóstico mais provável é:","options":{"A":"doença de Gaucher.","B":"púrpura trombocitopênica trombótica.","C":"púrpura trombocitopênica idiopática.","D":"síndrome hemolítico-urêmica.","E":"leucemia aguda."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-247140","number":"247140","sourceNumber":"247140","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Qual das doenças relacionadas é caracterizada como causadora de trombofilia\nsecundária?","options":{"A":"Síndrome antifosfolípede.","B":"Deficiência de proteína C e S.","C":"Deficiência de antitrombina III.","D":"Resistência à proteína C ativada causada ela presença de molécula anormal do fator V Leiden.","E":"Mutação 20210 de protrombina."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-247157","number":"247157","sourceNumber":"247157","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Mulher de 42 anos deverá ser submetida a cirurgia eletiva de colecistectomia. Nega\nhistória pessoal e familiar de sangramento. Os exames pré-operatórios mostram: RNI = 1,02\n(normal até 1,2); TTPA = 2,59 (normal até 1,25); TTPA com adição de plasma normal = 1,05.\n\nAssinale o teste que permite prosseguir de forma correta a investigação.","options":{"A":"Dosagem de fator II da coagulação.","B":"Dosagem de fator XII da coagulação.","C":"Dosagem de fator XIII da coagulação.","D":"Pesquisa de inibidor da coagulação dependente de fosfolipede.","E":"Dosagem de fator V da coagulação."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-183158","number":"183158","sourceNumber":"183158","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sabe-se, hoje, que em cerca de 20% a 60% dos casos de TEV, uma mutação no fator\nV devido à substituição de aminoácidos\n(arginina por glutamina), leva a que esse fator, torne-se\nresistente a que proteína:","options":{"A":"Proteína S ativada.","B":"Proteína C ativada.","C":"Antitrombina,","D":"Plasminogênio.","E":"Heparina. Clínica Médica Página 5"},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-135927","number":"135927","sourceNumber":"135927","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Um lactante com 1 mês e 20 dias de vida é atendido na Unidade de Pronto\nAtendimento de seu bairro com história de\nvômitos alimentares em jato após as mamadas.\nEncontra-se abaixo do peso esperado para idade e desidratado. Após investigação, a ecografia\nabdominal firmou o diagnóstico de estenose hipertrófica de piloro. Quais os distúrbios acidobásicos\nque se espera encontrar?","options":{"A":"Alcalose respiratória;","B":"Alcalose metabólica;","C":"Acidose respiratória;","D":"Acidose metabólica."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-108625","number":"108625","sourceNumber":"108625","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente com quadro de hiponatremia, sem edemas, água corpórea total aumentada,\nsódio corpóreo total normal e sódio urinário >\n20. Qual a provável causa da condição acima?","options":{"A":"Excesso de diuréticos;","B":"Vômitos;","C":"Insuficiência Renal Aguda;","D":"SSIADH."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-84505","number":"84505","sourceNumber":"84505","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 65 anos admitido com história de ser portador de hipertensão arterial\nfazendo uso de hidroclorotiazida e losartana,\né admitido no pronto-socorro apresentando depressão\ndo segmento ST, achatamento das ondas T e ondas U proeminentes. Qual o distúrbio\nhidroeletrolítico mais provável:","options":{"A":"Hipocalcemia.","B":"Hiponatremia.","C":"Hipocalemia.","D":"Hipomagnesemia.","E":"Hipercalemia."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-84545","number":"84545","sourceNumber":"84545","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"O cálculo do Anion GAP pode ser útil em algumas condições clínicas, entre as quais\nintoxicações exógenas e acúmulo de lactato, cetonas e outros metabólitos. Quais os eletrólitos\nnecessários para esse cálculo e qual o valor normal do Anion Gap?","options":{"A":"Potássio, cloro, sódio. Valor normal: 3-6 meq/l;","B":"Sódio, cálcio, potássio. Valor normal: 0-2 meq/l;","C":"Sódio, cloro, bicarbonato. Valor normal: 8-12 meq/l;","D":"Cálcio, fósforo, proteínas. Valor normal: 28-32 meq/l;","E":"Cálcio, cloro, bicarbonato. Valor normal: 0-5 meq/l."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-84546","number":"84546","sourceNumber":"84546","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Considerando um paciente na enfermaria com os seguintes parâmetros gasométricos:\npH= 7,28; PaCO2: 35 mmhg; HCO3: 16. Podemos\nafirmar que, muito provavelmente, o paciente é\nportador de: Fórmula de WINTER - pCO2 = 1,5 x HCO3 + 8 (+/- 2). Valores referencia: pCO2-\n\n35-45 (mmHg), HCO3- 22-26 mEq/L","options":{"A":"Acidose mista.","B":"Acidose metabólica.","C":"Acidose metabólica em fase inicial de compensação respiratória.","D":"Acidose respiratória.","E":"Alcalose Metabolica."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-369524","number":"369524","sourceNumber":"369524","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Mulher, 32 anos de idade, procura atendimento na Unidade Básica de Saúde (UBS)\ndevido a equimoses espontâneas em\ndiferentes regiões do corpo, incluindo membros inferiores e\nsuperiores, com duração de, aproximadamente, 2 semanas. Não há relato de trauma recente. No\nexame físico observam-se petéquias disseminadas e contusões de diferentes estágios de evolução.\nA paciente nega história anterior de sangramentos anormais. Solicitados exames complementares\nque evidenciam Hb: 12,5g/dL, leucócitos 7500cels/ mm³, plaquetas: 18.000/mm³, Cr: 0,5mg/dL, Ur\n17mg/dL. Esfregaço de sangue periférico com presença de macroplaquetas e ausência de\nfragmentação eritrocitária. Considerando o caso, indique o diagnóstico mais provável, dentre os\napresentados a seguir:","options":{"A":"Púrpura de Henoch-Schönlein.","B":"Síndrome de Evans.","C":"Púrpura trombocitopênica idiopática.","D":"Púrpura trombótica trombocitopênica."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-314199","number":"314199","sourceNumber":"314199","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"O abciximab é um anticorpo monoclonal, sendo correto o item:","options":{"A":"Que atua como bloqueador competitivo e irreversível dos receptores de GP IIb/IIIa. Tem\n\nmeia-vida plasmática curta de 5 a 10min, e sua meia-vida biológica é de 6 a 12h após a injeção de\num bolus isolado.","B":"Que atua como bloqueador não competitivo e reversível dos receptores de GP IIb/IIIa. Tem\nmeia-vida plasmática curta de 5 a 10min, e sua meia-vida biológica é de 6 a 12h após a injeção de\num bolus isolado.","C":"Que atua como bloqueador não competitivo e irreversível dos receptores de GP IIb/IIIa. Tem\nmeia-vida plasmática curta de 5 a 10min, e sua meia-vida biológica é de 6 a 12h após a injeção de\num bolus isolado.","D":"Que não atua como bloqueador não competitivo e irreversível dos receptores de GP IIb/IIIa. Tem\nmeia-vida plasmática curta de 5 a 10min, e sua meia-vida biológica é de 6 a 12h após a injeção de\num bolus isolado."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-249190","number":"249190","sourceNumber":"249190","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Preferencialmente, recomenda-se que se usem novos anticoagulantes orais NOACs em\nvez da varfarina, devido à sua\nprevisibilidade de efeito. Sendo adequado que:","options":{"A":"NOAC deve ser escolhido de acordo com o conhecimento médico já estabelecido nesse\ncontexto e nas doses previamente estudadas.","B":"NOAC não deve ser escolhido de acordo com o conhecimento médico já estabelecido nesse\ncontexto e nas doses previamente estudadas.","C":"NOAC deve ser escolhido em desacordo com o conhecimento médico já estabelecido nesse\ncontexto e nas doses previamente estudadas.","D":"NOAC deve ser escolhido de acordo com o conhecimento médico já estabelecido nesse\ncontexto e nas doses empiricas."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-212175","number":"212175","sourceNumber":"212175","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Dadas as afirmativas sobre as doenças hematológicas e cirurgia: I. A laparoscopia é\ncontraindicada no tratamento das PTI. II. A resposta completa à esplenectomia no tratamento das\nPTI pode chegar a 80%. III. O tratamento de primeira linha das Púrpuras Trombocitopênicas\nImunológicas (PTI) é a esplenectomia. Verifica-se que está(ão) CORRETA(S):","options":{"A":"I, apenas.","B":"II, apenas.","C":"III, apenas.","D":"I e II, apenas.","E":"I, II e III."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-219889","number":"219889","sourceNumber":"219889","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Homem de 32 anos com diagnóstico de diabetes mellitus tipo I encontra-se internado\nem Unidade de Terapia Intensiva por quadro\nséptico secundário a abscesso perianal e apresenta\nsangramento em sítios múltiplos associado a trombocitopenia. Neste contexto, qual das alterações\nabaixo NÃO é esperada?","options":{"A":"Aumento do tempo de tromboplastina parcial ativada.","B":"Diminuição dos níveis séricos de fibrinogênio.","C":"Esquizócitos no sangue periférico.","D":"Produtos de degradação da fibrina diminuídos."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-181316","number":"181316","sourceNumber":"181316","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"As transfusões de hemocomponentes nunca foram tão seguras como na atualidade.\nEntretanto, como em qualquer procedimento\nmédico, em algumas situações podem ocorrer reações\nadversas. Qual a reação transfusional aguda imunológica mais comum?","options":{"A":"Anafilática.","B":"Hemolítica aguda.","C":"Não hemolítica febril.","D":"Contaminação bacteriana.","E":"TRALI (Transfusion Related Acute Lung Injury)."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-182821","number":"182821","sourceNumber":"182821","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Criopreciptido pode ser indicado nas seguintes situações, EXCETO","options":{"A":"coagulação vascular disseminada.","B":"pacientes com INR maior que 4.","C":"transfusão maciça.","D":"profilaxia para pacientes com hemofilia A."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-158804","number":"158804","sourceNumber":"158804","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Uma criança do sexo masculino de dez anos de idade com dor no quadrante inferior\ndireito, náusea, vômito e febre. Feita a\nhipótese de apendicite aguda, é indicado tratamento\ncirúrgico. Nesse instante, os pais informam que o filho é portador de hemofilia A. Nesse caso, o que\ndeve ser administrado ao paciente?","options":{"A":"Fator VII.","B":"Fator VIII.","C":"Vitamina k.","D":"Plasma fresco.","E":"Crioprecipitado."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-109968","number":"109968","sourceNumber":"109968","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Qual é a manifestação clínica MAIS comum da Hipocalcemia?","options":{"A":"Tetania.","B":"Parestesia.","C":"Coma.","D":"Insuficiência renal."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-109979","number":"109979","sourceNumber":"109979","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Qual das soluções abaixo apresenta concentrações de sódio e cloro mais próximas das\nobservadas no plasma?","options":{"A":"Plasma fresco congelado.","B":"Soro glicosado a 5%.","C":"Ringer lactato.","D":"Soro fisiológico a 0,9%."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-86786","number":"86786","sourceNumber":"86786","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Com relação à acidose metabólica é incorreto afirmar:","options":{"A":"Caracteriza-se pela redução plasmática do pH e bicarbonato;","B":"A PaCO2 geralmente está elevada devido à\ncompensação respiratória;","C":"Pode resultar de acúmulo de ácido;","D":"Pode resultar da perda de base;","E":"Pode apresentar anion gap normal ou aumentado."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-86793","number":"86793","sourceNumber":"86793","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"São efeitos da acidose grave:","options":{"A":"Redução da contratilidade miocárdica.","B":"Redução das atividades das aminas plasmáticas.","C":"Vasodilatação.","D":"Hipotensão arterial.","E":"Todas as alternativas anteriores."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-86796","number":"86796","sourceNumber":"86796","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"É causa comum de hiponatremia com volume extracelular aumentado:","options":{"A":"Diarreia;","B":"Uso de diuréticos;","C":"Síndrome perdedora de sal;","D":"Secreção inapropriada do hormônio antidiurético;","E":"Insuficiência cardíaca."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-86799","number":"86799","sourceNumber":"86799","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Em conformidade com o tratamento da hiponatremia é incorreto afirmar que:","options":{"A":"A correção rápida pode causar mielinólise\npontina central;","B":"Deve-se evitar velocidade de correção superior a 8-12 mEq/L ao dia;","C":"Deve-se evitar a correção de sódio para níveis superiores a 130 mEq/L nos primeiros dois dias;","D":"O tratamento básico para a síndrome da secreção inapropriada do hormônio antidiurético é a\nrestrição hídrica;","E":"A reposição hídrica está sempre indicada."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-86597","number":"86597","sourceNumber":"86597","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"500 ml de solução fisiológica a 0,9% apresenta:","options":{"A":"38,9 mEq de sódio.","B":"190 mEq de sódio.","C":"154 mEq de sódio.","D":"340 mEq de sódio.","E":"60 mEq de sódio."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-86844","number":"86844","sourceNumber":"86844","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"A concomitância de uso de diurético de alça e vômitos gera:","options":{"A":"Alcalose metabólica simples;","B":"Alcalose mista;","C":"Acidose mista;","D":"Acidose metabólica simples;","E":"Acidose respiratória e acidose metabólica."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-86885","number":"86885","sourceNumber":"86885","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Assinale a alternativa que responde CORRETAMENTE à pergunta abaixo. Escolar de\nsete anos de idade, em tratamento de enurese noturna com DDAVP intranasal há uma semana, é\ntrazido emergência por apresentar, subitamente, crise tonicoclônica generalizada com perda de\nconsciência. Qual o provável diagnóstico?","options":{"A":"Desidratação hipertônica;","B":"Hipocalcemia;","C":"Hipoglicemia;","D":"Hiponatremia;","E":"Hipomagnesemia."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-86867","number":"86867","sourceNumber":"86867","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Criança portadora de tumor de Wilms, nefrectomizado há seis meses e fora de\ntratamento há três meses, chega ao PS com\nquadro de vômitos incoercíveis há 5 horas e\ndistensão abdominal importante. Quando estava sendo atendida, começou a apresentar crise\nconvulsiva tônico-clônica, entrando em mal convulsivo e sendo encaminhada à UTI. O distúrbio\neletrolítico provável nesse caso é:","options":{"A":"Hipofosfatemia;","B":"Hiponatremia;","C":"Hipocalcemia;","D":"Hipomagnesemia;","E":"Hipocalemia."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-158396","number":"158396","sourceNumber":"158396","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Masculino, 74 anos, refere quadro de sangramentos cutâneos espontâneos há cerca de\n2 meses, chega ao PS com hematomas extensos\nem membros inferiores e superiores e hematúria\nsignificativa. Colheu exames que revelaram alteração de TTPA (Tempo de Tromboplastina Parcial\nAtivada) com relação R de 6,5 (normal até 1,20), não apresentava alterações em outros exames de\ncoagulação como TP (Tempo de Protrombina) e TT (Tempo de Trombina), e a contagem de\nplaquetas era normal. Ao exame, evidenciavam-se hematomas extensos em membro superior\ndireito. Qual a principal hipótese diagnóstica para o caso acima?","options":{"A":"Doença de von Willebrand.","B":"Síndrome de Weil.","C":"Síndrome antifosfolípide.","D":"Leucemia mieloide aguda.","E":"Hemofilia adquirida."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-158403","number":"158403","sourceNumber":"158403","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Masculino, 74 anos, refere quadro de sangramentos cutâneos espontâneos há cerca de\n2 meses, chega ao PS com hematomas extensos\nem membros inferiores e superiores e hematúria\nsignificativa. Colheu exames que revelaram alteração de TTPA (tempo de tromboplastina parcial\nativada) com relação R de 6,5 (normal até 1,20), não apresentava alterações em outros exames de\ncoagulação como TP (tempo de protrombina) e TT (tempo de trombina), e a contagem de plaquetas\nera normal. Ao exame, evidenciava-se hematomas extensos em membro superior direito. Quais\nopções terapêuticas para o controle de urgência do sangrento?","options":{"A":"DDAVP e concentrado de fator VIII.","B":"Concentrado de Plaquetas.","C":"Pulsoterapia com metilprednisolona EV.","D":"Plasmaferese.","E":"Hidratação + Ceftriaxona EV."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-327223","number":"327223","sourceNumber":"327223","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Mulher, 21 anos, em avaliação pré-operatória de otoplastia evidenciou-se tempo de\ntromboplastina parcial ativado (TTPa) prolongado. Refere epistaxes frequentes e equimoses\nespontâneas desde a infância, e sangramento uterino anormal (ciclos menstruais com duração de\nmais de 10 dias, com coágulos e necessidade de absorvente noturno contínuo). Mãe com sintomas\nmenstruais semelhantes. Nega outros familiares com história de sangramentos. Nega hemartroses.\nNega procedimentos cirúrgicos prévios. Exame físico sem alterações. Exames laboratoriais: Hb:\n11,7g/dL; VCM: 78fL; GB: 6.200/µL; plaquetas: 250.000/µL; TTPa: 53 segundos (VN < 44,6); TP\n(Tempo de protrombina): 13,5 segundos (VN < 17,3). Qual elemento do sistema hemostático da\npaciente mais provavelmente está envolvido?","options":{"A":"Fator de von Willebrand","B":"Plaquetas","C":"Fibrinogênio","D":"Fator VIII da coagulação"},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-256582","number":"256582","sourceNumber":"256582","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre as transfusões sanguíneas e suas reações adversas, são condutas apropriadas,\nEXCETO:","options":{"A":"As reações transfusionais imediatas são aquelas que ocorrem em até 48 horas da infusão do\nhemocomponente.","B":"Solicitar culturas de sangue do paciente e da unidade transfundida na suspeita de contaminação\nbacteriana e iniciar antibióticos de amplo espectro.","C":"Administrar epinefrina subcutânea na reação anafilática.","D":"Tratar a lesão pulmonar aguda relacionada à transfusão (TRALI) com medidas de suporte com\noxigênio, diuréticos e frequentemente com ventilação mecânica."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-151939","number":"151939","sourceNumber":"151939","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Quais são as manifestações hemorrágicas mais marcantes e peculiares da hemofilia?","options":{"A":"Hemartroses.","B":"Grandes equimoses.","C":"Hemorragia do SNC.","D":"Hematomas importantes."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-129813","number":"129813","sourceNumber":"129813","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"O exame que mais fidedignamente auxilia na avaliação da fase plaquetária da\ncoagulação sanguínea é:","options":{"A":"Tempo de sangramento.","B":"Plaquetometria.","C":"Tempo de retração do coágulo.","D":"Tempo de atividade de protrombina."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-107662","number":"107662","sourceNumber":"107662","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Nos casos de acidose metabólica temos os tampões fisiológicos: tampões bicarbonato\ne não bicarbonato. Qual elemento abaixo\nparticipa dos tampões Não bicarbonato:","options":{"A":"Lipideos;","B":"Fósforo;","C":"Sódio;","D":"Cálcio."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-81000","number":"81000","sourceNumber":"81000","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Nos casos de acidose metabólica temos os tampões fisiológicos: tampões bicarbonato\ne não bicarbonato. Qual elemento abaixo\nparticipa dos tampões não bicarbonato?","options":{"A":"Sódio","B":"Lipídeos","C":"Fósforo","D":"Carboidrato","E":"Cálcio"},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-81012","number":"81012","sourceNumber":"81012","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Lactente eutrófico, alimentado somente com leite materno, iniciou quadro de diarreia\nlíquida, há 03 dias, acompanhada de febre e\nvômitos. Evoluindo com taquipneia, diminuição de\ndiurese (oligúria), sonolência. Com sinais de desidratação grave. Após etapa de expansão (3x),\napresentou diurese em pequena quantidade. Colhido os exames observou-se: Na= 115, K=1,5;\nCa= 0,9; Mg+ 2; e Fósforo= 4mg/dl. Com relação aos distúrbios hidroeletrolíticos devemos corrigir:","options":{"A":"O quadro de Hiponatremia e Hipopotassemia e ambos devem ser corrigidos, pois são\nconsiderados graves e com risco de vida.","B":"Não há distúrbios eletrolíticos para corrigir.","C":"O quadro de Hipofosfatemia e Hipomagnesemia e ambos devem ser corrigidos, pois são\nconsiderados graves e com risco de vida.","D":"Não há necessidade de correção da Hiponatremia.","E":"Os distúrbios em questão não são de natureza aguda não precisam de correção."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-61528","number":"61528","sourceNumber":"61528","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Analise as seguintes definições relacionadas ao equilíbrio ácido-base. I. pH sanguíneo\n\n> 7,45; II. pH sanguíneo < 7,35; III. Distúrbio com tendência à alcalemia; IV. Distúrbio com\ntendência à acidemia. As definições se referem respectivamente, à:","options":{"A":"Acidemia, alcalemia, acidose, alcalose.","B":"Alcalemia, acidemia, alcalose, acidose.","C":"Alcalemia, acidemia, acidose, alcalose.","D":"Acidemia, alcalemia, alcalose, acidose.","E":"Alcalose, acidose, alcalemia, academia."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-34128","number":"34128","sourceNumber":"34128","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Qual alteração eletrolítica, leva ao quadro de agitação, letargia, taquicardia,\nhipotensão,\noligúria, rubor cutâneo?","options":{"A":"Hiperpotassemia.","B":"Hipernatremia.","C":"Hipofosfatemia.","D":"Hiponatremia.","E":"Hipocalcemia."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-26648","number":"26648","sourceNumber":"26648","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente internado por 30 dias, vítima de politraumatismo, em coma devido TCE,\nrecebendo nutrição nasoenteral, vem evoluindo\ncom diarreia e apresentando distensão abdominal.\nAchado eletrocardiográfico de onda T achatada, o aparecimento de onda U. O quadro descrito é\ncompatível com:","options":{"A":"Hiponatremia.","B":"Hipercalemia.","C":"Hipercalcemia.","D":"Hipocalemia.","E":"Hipovolemia."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-49403","number":"49403","sourceNumber":"49403","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Homem, 65 anos de idade, internado para tratamento de insuficiência cardíaca\ncongestiva, em uso de furosemida EV, digoxina\noral e betabloqueador, vem apresentando náuseas\ncom vômitos há dois dias. Realizou exames que mostram pH: 7,46, PaO2: 80 mmHg, HCO3: 32\nmEq/L, PCO2: 50 mmHg, BE: 5 saturação de O2: 91%, cloro: 90 mEq/L, K: 3,2 mEq/L. O\ntratamento desse paciente deve ser feito com:","options":{"A":"Administração de amônia oral e vitamina C.","B":"Solução fisiológica a 0,9% e administração de KCl.","C":"Administração de O2 e ventilação assistida.","D":"Solução de HCI e ventilação assistida.","E":"Administração de lactato de sódio."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-49270","number":"49270","sourceNumber":"49270","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente, quatro anos de idade, apresenta queixa de sangramento nasal em episódios\nagudos, sem febre ou dor. Fez uso de vacina tríplice viral há quatro semanas. Ao exame físico,\nnota-se bom estado geral, eutrófico, presença de petéquias em abdome e MMII. Ausculta\ncardiopulmonar normal. Abdome plano sem visceromegalias. Exames laboratoriais mostram\nhemograma com anemia, plaquetas = 50.000/mm³. Presença de macroplaquetas no sangue\nperiférico. Mielograma com o setor megacariocítico hiperplasiado. Sumário de urina com hemácias\n\n+. Em relação a esse diagnóstico, é INCORRETO afirmar que:","options":{"A":"É definido como trombocitopenia isolada com medula óssea normal na ausência de outras\ncausas.","B":"O uso de esteroides e imunossupressores e a esplenectomia podem ser indesejáveis pelas\ncomplicações associadas.","C":"A redução da vida das plaquetas na circulação resulta em aumento de megacariócitos na\nmedula óssea.","D":"O diagnóstico é feito pela clínica e pela exclusão de outras etiologias.","E":"É uma vasculite, frequente na infância, mas que só ocorre em crianças portadoras de doença\nimunológica primária."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-34947","number":"34947","sourceNumber":"34947","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Em relação à fisiologia renal, é correto afirmar, exceto:","options":{"A":"Apenas 0,1% da carga de NaCI filtrado pelo glomérulo é eliminada na urina.","B":"A amônia é o tampão urinário mais importante, pois é responsável pela eliminação da maior\nparte do H+ excretado pela urina.","C":"A enzima conversora da angiotensina (A) é uma carboxipeptidase, que converte A-I em A-lI e\nadicionalmente inativa a bradicinina, encontrando-se distribuída no organismo e mais\nabundantemente nos rins, no íleo, no duodeno e no útero.","D":"As células respondem a A-ll através de receptores altamente específicos. Das duas classes de\nreceptores da A-lI, os receptores AT2 são antagonizados pelo losartan, bloqueando o estímulo à\nvasoconstricção, à secreção de aldosterona, sede e reabsorção tubular de sódio.","E":"No diabetes, associado ou não com hipertensão arterial sistêmica, os níveis de renina\nencontram-se diminuídos."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-34991","number":"34991","sourceNumber":"34991","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre o íon potássio, é correto afirmar:","options":{"A":"É o ânion predominante no espaço intracelular.","B":"Salbutamol é eficaz para corrigir hipocalemia.","C":"Causas importantes de hipocalemia são a injúria traumática aguda e o período pós-operatório\nimediato.","D":"Pequenas alterações nos níveis de potássio intracelular determinam grandes repercussões nos\nsistemas cardiovascular e neuromuscular.","E":"Na hiperpotassemia, predominam queixas cardíacas e neurológicas."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-35002","number":"35002","sourceNumber":"35002","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente, sexo feminino, 25 anos de idade, com fissura anal posterior crônica, já tendo\nfeito uso de formadores de bolo fecal, nifedipina e nitrato tópicos anais, sem melhora. Realizou\nmanometria anorretal com acentuada hipertonia esfincteriana. São causas de acidose metabólica\ncom hiato aniônico normal, exceto:","options":{"A":"Perdas digestivas não gástricas;","B":"Acidose tubular renal;","C":"Nutrição parenteral total;","D":"Anastomoses ureterais;","E":"Acidose lática."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-27497","number":"27497","sourceNumber":"27497","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Mulher, 52 anos de idade, assintomática, em início de menopausa, apresentou em\nexames de rotina AST: 210U/dl, ALT:102U/dl\ngamaglutamiltransferase: 92U/l. Não faz reposição\nhormonal. Nega transfusões sanguíneas e tem apenas um parceiro sexual. O exame físico é\nnormal. Realizou exames adicionais que revelaram Hb: 13,2g/dl, Ht: 37%, leucograma: 5.700\nleucócitos/mm³ sem desvios, glicemia: 82mg/dl. AntiHCV positivo, AgHBs negativo, índice de\nsaturação de transferrina: 40%, ferritina sérica: 850mcg/dl. Anticorpos antimitocôndria, antimúsculo\nliso e anti-LKM negativos. Anticorpos anti-TPO positivos. Após uma semana de tratamento, o\nionograma e a hemogasimetria arterial da paciente apresentaram os seguintes achados, pH: 7,3,\nPC02: 31mmHg, HC03: 19mEq/l, PaO²: 83mmHg, BE: -12, sódio sérico: 137mEq/l, CI: 104mEq/l, K:\n6,0mEq/l. O distúrbio metabólico apresentado é:","options":{"A":"acidose mista respiratória e metabólica, descompensada.","B":"acidose respiratória crônica agudizada, descompensada.","C":"acidose respiratória com alcalose metabólica, compensadas.","D":"acidose metabólica descompensada.","E":"acidose metabólica com alcalose respiratória, descompensada."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-27498","number":"27498","sourceNumber":"27498","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Mulher, 52 anos de idade, assintomática, em início de menopausa, apresentou em\nexames de rotina AST: 210 U/dl, ALT: 102\nU/dl gamaglutamiltransferase: 92 U/l. Não faz reposição\nhormonal. Nega transfusões sanguíneas e tem apenas um parceiro sexual. O exame físico é\nnormal. Realizou exames adicionais que revelaram Hb: 13,2 g/dl, Ht: 37%, leucograma: 5.700\nleucócitos/mm³ sem desvios, glicemia: 82 mg/dl. AntiHCV positivo, AgHBs negativo, índice de\nsaturação de transferrina: 40%, ferritina sérica: 850 mcg/dl. Anticorpos antimitocôndria,\nantimúsculo\nliso e anti-LKM negativos. Anticorpos anti-TPO positivos. A paciente passou a apresentar onda T\napiculada no ECG. A medida mais imediata é:","options":{"A":"bicarbonato de sódio EV.","B":"nebulização com fenoterol.","C":"resina de troca iônica e manitol oral (sorcal).","D":"gluconato de cálcio EV.","E":"solução de glicose e insulina EV."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-343358","number":"343358","sourceNumber":"343358","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre as heparinas, fórmulas utilizadas no tratamento das doenças vasculares,\nassinale a correta.","options":{"A":"A dose de heparina não fraciona normalmente deve ser ajustada pela medida do TTPa (Tempo\nde Tromboplastina Parcial Ativada). No caso de\ndoses muito elevadas, como as administradas em\ncircuitos extracorpóreos no momento de cirurgia cardíaca, cirurgia vascular ou transplante hepático,\nestas são determinadas pelo TCA (tempo de coagulação ativado).","B":"O efeito anticoagulante da heparina de baixo peso molecular pode ser neutralizado rapidamente\npela protamina intravenosa, uma proteína catiônica\nque se liga fortemente à heparina.","C":"O pico da concentração de antifator Xa e antifator IIa plasmático é alcançado 3 a 4 h depois da\nadministração da heparina não fracionada.","D":"Diferente como na heparina não fracionada, os pacientes podem apresentar resistência às\nheparinas de baixo peso molecular pois também se ligam às células do endotélio e aos\nmacrófagos, com mudanças na sua farmacocinética."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-181181","number":"181181","sourceNumber":"181181","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"O potássio é o principal íon intracelular, e o sódio o principal íon extracelular. Com\nbase\nnessas informações, assinale a alternativa\nINCORRETA em relação à Hipocalemia:","options":{"A":"Paralisia flácida com comprometimento respiratório pode ocorrer quando potássio esta abaixo de\n2 mmol/L.","B":"Hipermagnesemia pode ser a causa de hipocalemia refratária.","C":"No eletrocardiograma pode ocorrer depressão de onda T e ondas U.","D":"Sintomas clínicos são fadiga, fraqueza e íleo."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-157666","number":"157666","sourceNumber":"157666","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre os hemocomponentes, marque a opção INCORRETA:","options":{"A":"O crioprecipitado contém a maior parte composta por fator VIIIC e parte do fibrinogênio do\nplasma original. Está indicado em diversas\npatologias, como hemofilia A, doença de von Willebrand\nou hipofibrinogenemia, entre outras.","B":"O plasma fresco congelado é indicado para pacientes com processos hemorrágicos por\ndeficiências múltiplas de fatores de coagulação,\nsecundárias à disfunção hepática, anticoagulação\noral (antagonistas da vitamina K), coagulação vascular disseminada, coagulopatias dilucionais,\npacientes com deficiência de antitrombina, proteína C e S, púrpura trombocitopênica trombótica,\nsíndrome hemolítico-urêmica e pacientes submetidos à circulação mecânica.","C":"O sangue total restabelece a capacidade de transporte de oxigênio e promove a expansão de\nvolume, sendo indicado para pacientes com sangramentos profusos, que desenvolvam choque\nhemorrágico. Uma unidade de sangue total acarretará em um incremento aproximado de 3 g/dl na\nconcentração de hemoglobina ou 3 a 4% do hematócrito.","D":"As transfusões de concentrados de plaquetas podem ter indicações de caráter terapêutico ou\nprofilático. Uma unidade de plaqueta acarretará no aumento de 5 a 12 mil/mm³/m². Sabe-se que\ncinquenta mil/mm³ acarretam hemostasia adequada, desde que o sistema de coagulação,\nfibrinolítico e endotélio estejam em condições satisfatórias."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-157682","number":"157682","sourceNumber":"157682","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Idosa com dificuldade de caminhar e de se alimentar foi trazida por familiares,\ndesidratada e muito prostrada. Utilizava\ncaptopril para controle de hipertensão, e já havia ocorrido\npreviamente aumento dos níveis de creatinina. Além de desidratação, foi suspeitado de\nhipercalemia. Diante de tal quadro clínico, assinale a alternativa que determina a gravidade\nimediata da hipercalemia.","options":{"A":"Alteração de repolarização ventricular, alterando também o complexo QRS.","B":"Redução de amplitudes de ondas T.","C":"Aumento da FC.","D":"BRE novo."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-139776","number":"139776","sourceNumber":"139776","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Qual das soluções abaixo apresenta concentrações de sódio e cloro mais próximas das\nobservadas no plasma?","options":{"A":"Plasma fresco congelado.","B":"Soro glicosado a 5%.","C":"Ringer lactato.","D":"Soro fisiológico a 0,9%."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-139748","number":"139748","sourceNumber":"139748","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Qual é o distúrbio hidroeletrolítico e ácido-básico MAIS comumente observado nos\ncasos de desidratação por vômitos\nincoercíveis?","options":{"A":"Acidose metabólica com hipocalemia.","B":"Alcalose metabólica e hipocloremia.","C":"Acidose metabólica e hipercloremia.","D":"Alcalose metabólica e hipercalemia."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-111927","number":"111927","sourceNumber":"111927","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Além do sistema tampão Bicarbonato ? Ácido Carbônico ? existem três outros sistemas\ntampões disponíveis no organismo e que estão nas alternativas abaixo. Assinale a alternativa que\nNÃO faz parte desse grupo.","options":{"A":"Hidrossulfetos ? Sulfatos.","B":"Hemoglobina reduzida ? Oxiemoglobina.","C":"Fosfato ácido ? Fosfato básico.","D":"Proteína ácida ? Proteína básica."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-321307","number":"321307","sourceNumber":"321307","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente, 32 anos, portador de anemia falciforme. Encontra-se no 3o dia de internação\nhospitalar, em enfermaria, por crise álgica, sob uso de morfina, cetoprofeno e dipirona, para\ncontrole do quadro. Está hemodinamicamente estável, com bom controle álgico, diurese presente,\nafebril, eupneico, sem suporte de oxigênio. Apresenta hemograma do dia com Hb 5,9g/dL Ht 17%,\nsendo indicada transfusão de concentrado de hemácias desleucocitado e fenotipado. Após 12\nminutos do início da administração do hemocomponente, pela enfermeira da unidade, o paciente\npassa a apresentar febre (T: 38,3oC), calafrios, dor no local do acesso periférico, dor em flancos e\nepistaxe. Você, como médico plantonista da unidade, é imediatamente chamado para prestar\nassistência ao paciente. Ao chegar, você solicita imediata interrupção da transfusão, prescreve\nsintomáticos, notifica a suspeita de reação transfusional e solicita coleta de amostras para análise\nda reação pelo serviço de hemoterapia. Além das ações citadas, qual a melhor conduta a ser\nrealizada?","options":{"A":"Devolver hemocomponente à agência transfusional, solicitar provas de hemólise, função renal,\ncoagulograma e hemoculturas do paciente e prescrever hidratação vigorosa.","B":"Coletar hemocultura do paciente, retornar a transfusão com o mesmo hemocomponente, após\nresolução dos sintomas, e administrá-lo em 4 horas.","C":"Coletar novo hemograma, devolver hemocomponente à agência transfusional e só prescrever\nhemocomponentes lavados para transfusões futuras.","D":"Descartar concentrado de hemácias, solicitar que enviem novo concentrado para transfusão\nimediata e administrá-lo em 4 horas."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-173019","number":"173019","sourceNumber":"173019","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente, feminina, 23 anos, comparece ao ambulatório de clínica médica com quadro\nde astenia, fadiga, artralgias leves difusas e\ndispneia aos moderados esforços, há duas semanas,\ncom piora progressiva. Relata também gengivorragia à escovação dentária, há uma semana. Ao\nexame físico, encontra-se com palidez cutâneo-mucosa moderada e petéquias em pernas e pés,\ncom equimoses esparsas em membros, sem outras alterações. Hemograma evidenciou Hb 6,4 g/l\n(VR: 11,5-16 g/dl), leucócitos 3.900/mm³ (VR: 4.000-11.000/mm³) e plaquetas de 13.000/mm³ (VR:\n150.000-450.000). Legenda: VR ? Valor de Referência. Qual a abordagem diagnóstica inicial?","options":{"A":"Mielograma com imunofenotipagem.","B":"Sorologia para dengue, Chikungunya e Zika.","C":"Biópsia de medula óssea, com avaliação de celularidade.","D":"Avaliação do sangue periférico, dos índices hematimétricos e reticulócitos."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-172973","number":"172973","sourceNumber":"172973","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente masculino de 62 anos estava internado com quadro de sepse em ventilação\nmecânica. Foi indicada transfusão de uma\nunidade de concentrado de hemácias, pois apresentava\nHb de 6,4 g/dl (Valor de referência: 12?16,5 g/dl). Os testes pré-transfusionais obrigatórios para\ntransfusão de concentrados de hemácias são tipagem ABO/RhD, Pesquisa de Anticorpos\nIrregulares (PAI) e prova de compatibilidade. Qual o objetivo da pesquisa de anticorpos\nirregulares?","options":{"A":"Avaliação de autoanticorpos.","B":"Avaliação de anticorpos anti-HLA.","C":"Avaliação de incompatibilidade ABO.","D":"Avaliação de aloanticorpos antieritrocitários."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-126948","number":"126948","sourceNumber":"126948","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Diversos pacientes internados em unidade de terapia intensiva desenvolvem distúrbios\ndo equilíbrio acidobásico. O correto diagnóstico\ndestes distúrbios é fundamental para a instituição\nde terapêuticas apropriadas. Paciente masculino, 65 anos, internado na UTI, em ventilação\nmecânica, no 1º pós-operatório de gastrectomia total. Permanece instável hemodinamicamente,\nmesmo após reposição volêmica. Na gasometria arterial: pH = 7,21; PaCO2 = 35 mmHg; HCO-3 =\n18 mEq/L; BE = -8 mEq/L; PaO2 = 170 mmHg (FIO2 40%); Na+ = 130 mEq/L; K+ = 4 mEq/L; Cl- =\n\n102 mEq/L. Hb 8,0 g/dl e SvO2 75%. Sobre esse caso, assinale a alternativa CORRETA.","options":{"A":"Trata-se de acidose mista e o tratamento com bicarbonato está recomendado.","B":"A hiper-hidratação com solução salina a 0,9% pode levar à piora da acidose metabólica.","C":"Trata-se de acidose metabólica hiperclorêmica e o tratamento deve se basear na correção da\ninstabilidade hemodinâmica com drogas vasoativas.","D":"Como o paciente permanece instável hemodinamicamente após reposição volêmica, a causa\nmais provável da acidose é anemia e a transfusão de concentrado de hemácias está indicada."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-81247","number":"81247","sourceNumber":"81247","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 47 anos foi admitido em serviço de emergência terciária com abdome\nagudo e sepse grave. Durante o tratamento\ncirúrgico, constatou-se diverticulite aguda com\nperitonite fecal. No pós-operatório, realizado na UTI, manteve-se em estado grave, com acidose\nmetabólica grave, anúria e níveis crescentes de creatinina. Em decorrência de Insuficiência Renal\nAguda (IRA), está em curso de hemodiálise. Considerando a situação descrita, qual alternativa\ncorresponde ao distúrbio hidroeletrolítico mais comumente relacionado à hemodiálise?","options":{"A":"Hipocalemia.","B":"Hipercalemia.","C":"Hiponatremia.","D":"Hipernatremia."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-81306","number":"81306","sourceNumber":"81306","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Homem de 16 anos, na segunda semana de pós-operatório de apendicectomia, sem\ncomplicações, comparece à consulta com quadro de equimoses disseminadas e edema na\npanturrilha esquerda há dois dias. Não tem antecedentes mórbidos relevantes. Doppler de\nmembros inferiores mostrou apenas hematoma na panturrilha afetada. Exames mostram dosagem\nde plaquetas normal, Tempo de Protrombina (TP) normal e Tempo de Tromboplastina Parcial\nAtivada (TTPa) alargado. Foi solicitado o teste da mistura que não corrigiu o TTPa. Qual o\ndiagnóstico mais provável?","options":{"A":"Hemofilia A.","B":"Intoxicação por cumarínico.","C":"Doença de von Willebrand.","D":"Anticorpo adquirido contra fator VIII."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-65786","number":"65786","sourceNumber":"65786","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Homem de 80 anos apresenta, há três dias, quadro de vômitos incoercíveis em\ninúmeros episódios ao dia. Não consegue se\nalimentar nem ingerir líquidos. Encontra-se apático,\ncom diurese bastante diminuída nas últimas 24 horas. O paciente foi hidratado com solução salina\nisotônica e suplementação com KCl a 10%. Qual o indicador de que o paciente foi adequadamente\nreanimado?","options":{"A":"pH urinário ácido.","B":"pH urinário alcalino.","C":"Potássio sérico > 4 mEq/L.","D":"Cloreto sérico > 100 mEq/L.","E":"pH do sangue arterial < 7,4."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-65752","number":"65752","sourceNumber":"65752","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 80 anos, com queixa de dor epigástrica há 6 meses, há cerca de 3 dias\ncomeçou a apresentar vômitos, inicialmente pós-prandiais e atualmente com conteúdo claro, não\nbilioso em vários episódios e sem melhora com tratamento medicamentoso. O exame de raio X de\nabdome apresenta imensa distensão gástrica com pobreza de imagens de gases no restante da\ncavidade abdominal. Considerando os distúrbios hidroeletrolíticos e acidobásicos mais frequentes\nnessa situação, qual das seguintes propostas de reposição hidroeletrolítica é mais aplicável?","options":{"A":"Ringer Simples seguida de NaCl 19,1%.","B":"Ringer Lactato seguido de salina isotônica.","C":"Salina hipotônica seguida de Ringer Lactato.","D":"Salina isotônica seguida de solução com KCl.","E":"Salina hipertônica seguida de Ringer Lactato."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-51267","number":"51267","sourceNumber":"51267","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"No pós-operatório de uma cirurgia abdominal, um homem de 42 anos, 65 kg, sem\ncomorbidades associadas à patologia cirúrgica, foi inadvertidamente hiperidratado com solução\nfisiológica de NaCl a 0,9%. Considerando-se que esse paciente apresenta função renal normal,\nqual substância o seu organismo secreta para manter a homeostase da água extracelular?","options":{"A":"Aldosterona.","B":"Vasopressina.","C":"Noradrenalina.","D":"Peptídios natriuréticos."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-51218","number":"51218","sourceNumber":"51218","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Um paciente de 65 anos encontra-se internado por sepse grave em UTI. Além de\nantibióticos, foram prescritos enoxaparina subcutânea e ranitidina IV para profilaxia de trombose\nvenosa profunda e de úlcera de estresse, respectivamente. No 9ª dia de admissão, foram\nobservadas lesões necróticas na pele do abdome. A contagem de plaquetas em hemograma de\ncontrole é de 40.000/mm³ (na admissão era de 80.000/mm³). O restante do hemograma é normal,\ncompatível com a resolução clínica do seu quadro infeccioso. Não são observados sangramentos\nespontâneos. Que conduta é a mais recomendada dentre as descritas abaixo?","options":{"A":"Substituição da enoxaparina por heparina não fracionada.","B":"Substituição da enoxaparina por warfarin.","C":"Suspensão da enoxaparina.","D":"Suspensão da ranitidina."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-45395","number":"45395","sourceNumber":"45395","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"São alterações eletrocardiográficas que podem ser encontradas em pacientes com\nhipercalemia:","options":{"A":"Onda T alta, apiculada, estreita e simétrica.","B":"Onda T alta de base larga e assimétrica.","C":"Onda P aumentada e complexo QRS estreito.","D":"Inversão de onda T.","E":"Onda P alta, apiculada, estreita e simétrica."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-36977","number":"36977","sourceNumber":"36977","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"A hidratação adequada e a reposição de eletrólitos no pós-operatório são fundamentais\npara a recuperação do paciente. Sobre a\ncomposição de água e eletrólitos no organismo, qual a\nopção correta?","options":{"A":"Sódio, cloro e bicarbonato perfazem 90% das partículas osmoticamente ativas do líquido\nextracelular.","B":"O magnésio é o principal íon positivo osmoticamente ativo do meio intracelular.","C":"A porcentagem de água corporal total aumenta com a idade.","D":"O trato gastrointestinal é a principal via de controle do sódio corporal."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-32541","number":"32541","sourceNumber":"32541","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Na maioria dos adultos, a água é responsável por 45 a 60% do peso corporal total.\nConsidere a notação seguinte: ACT = água corporal total; AIC = água intracelular; AEC = água\nextracelular. Diante do exposto, é correto afirmar:","options":{"A":"AEC > AIC.","B":"AIC = ACT + AEC .","C":"AEC responde por 20% do peso corporal.","D":"ACT das mulheres > ACT dos homens.","E":"As membranas celulares são seletivamente permeáveis à água."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-32546","number":"32546","sourceNumber":"32546","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre a bioquímica e fisiologia da regulação acidobásica, é correto afirmar que:","options":{"A":"A alcalemia é a perturbação grave mais comum no equilíbrio acidobásico.","B":"A flutuação tolerável de H+ é bem mais aceita pelo organismo que as flutuações dos níveis\nséricos de Na+, K+ e Cl-.","C":"As proteínas são importantes tampões na AEC (Água Extracelular).","D":"O principal tampão na AEC (Água Extracelular) e na AIC (Água Intracelular) é o bicarbonato.","E":"A concentração de H+ na AEC e AIC é maior em relação aos outros solutos (Na+, K+, CI-\ne HCO3-)."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-32549","number":"32549","sourceNumber":"32549","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre os distúrbios acidobásicos, podemos afirmar corretamente que:","options":{"A":"As células renais captam o lactato e um próton e os convertem de volta em glicose, em um\nprocesso enzimático denominado gliconeogênese.","B":"Fístula duodenal ou diarreia podem fazer perder bicarbonato o suficiente para induzir acidemia.","C":"O nível de gás sanguíneo arterial de um paciente em cetoacidose diabética mostra alto pH e\nconcentração de bicarbonato deprimida.","D":"A cetoacidose diabética geralmente cursa com hipercalemia associada.","E":"Nos pacientes alcoólicos que desenvolvem uma síndrome de cetoacidose o\nmecanismo fisiopatológico é a deficiência de insulina."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-37000","number":"37000","sourceNumber":"37000","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 30 anos é avaliado por sonolência. Refere que há 2 semanas vem usando\nfurosemida por conta própria (para emagrecer ? sic) e há alguns dias apresenta astenia crescente.\nO exame físico evidencia PA = 90 x 40 mmHg, pulso = 105 ppm, sem outras alterações. Os exames\nlaboratoriais mostram: Gasometria arterial - pH = 7,57 ; PaCO2 = 49 mmHg ; HCO3 = 45 mmol/L ;\nPaO2 = 96 mmHg ; SaO2 = 96% ; Creatinina sérica = 1,5 mg/dl; Sódio sérico = 140 mmol/L; Cloro\nsérico = 90 mmol/L; Cloro urinário = 10 mmol/L. Os demais exames resultam sem alterações\nsignificativas. Qual a conduta mais apropriada?","options":{"A":"Iniciar droga vasoativa","B":"Iniciar infusão de solução salina isotônica.","C":"Iniciar infusão de HCl.","D":"Iniciar infusão de NaCl a 3%."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-30913","number":"30913","sourceNumber":"30913","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 45 anos alcoolista, no quarto dia de internação hospitalar com diagnóstico\nde pancreatite aguda, apresenta-se apático,\nsonolento, pele fria, com pressão arterial de 85 x 40\nmmHg, frequência cardíaca de 145 bpm, diurese de 20 ml na última hora. Exames laboratoriais:\ngasometria arterial pH = 7,15; PaO2 = 55 mmHg; PaCO2 = 28 mmHg; bicarbonato = 15 mEq/L;\nexcesso de base = -9; SatO2 = 93%; Na+ = 145 mEq/L ; K+ = 6,1 mEq/L; Cl- = 118 mEq/L. Qual a\nmelhor hipótese diagnóstica?","options":{"A":"Alcalose hiperclorêmica.","B":"Acidose metabólica.","C":"Acidose metabólica com ânion-gap diminuído.","D":"Alcalose respiratória.","E":"Acidose metabólica e hipoxemia."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-24298","number":"24298","sourceNumber":"24298","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"A água é o principal componente da massa corporal e tem múltiplos compartimentos no\nser humano. Sobre essa distribuição, assinale a alternativa FALSA:","options":{"A":"A água corporal total constitui entre 40 e 60% do peso na maioria dos adultos.","B":"A obesidade diminui a proporção de água corporal total.","C":"O compartimento intracelular é o maior e é estimado ter 55% da água corporal total.","D":"A mulher tem uma maior proporção de água corporal quando comparada com o homem."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-24299","number":"24299","sourceNumber":"24299","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Hipercalemia de início rápido causa arritmias cardíacas que podem ser fatais. A\nprincipal causa desse distúrbio é:","options":{"A":"Pós-operatório de grandes procedimentos com rabdomiólise","B":"Cetoacidose diabética","C":"Disfunção ou falência renal","D":"Grandes queimados"},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-27705","number":"27705","sourceNumber":"27705","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Considerando que o tratamento da hiponatremia aguda é consideravelmente diferente\ndo tratamento da hiponatremia crônica, responda: a\npartir de quanto tempo a hiponatremia é\nconsiderada crônica?","options":{"A":"24h","B":"48h","C":"72h","D":"1 semana","E":"2 semanas"},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-24323","number":"24323","sourceNumber":"24323","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Karla, 12 anos, com quadro de insuficiência renal aguda, realizou um eletrocardiograma\nque evidenciou uma diminuição do intervalo QT,\nassociada a uma onda T alta e apiculada, sinal de\nrepolarização ventricular precoce. Posteriormente, ocorreu achatamento da onda P, alargamento de\nQRS, até o desaparecimento da onda P. Com essa patologia, o provável distúrbio que gerou as\nalterações eletrocardiográficas foi:","options":{"A":"Hipercalemia","B":"Hipocalemia","C":"Hipomagnesemia","D":"Hiperglicemia"},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-25402","number":"25402","sourceNumber":"25402","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Os pacientes que menos toleram hiponatremia e que devem ser tratados mesmo\nnos casos leves são aqueles que apresentam as\nseguintes patologias:","options":{"A":"Trauma cranioencefálico","B":"Intoxicação aguda pela água (ex. RTU próstata)","C":"Cirrose hepática com ascite refratária","D":"Síndrome inapropriada do hormônio antidiurético","E":"Insuficiência Renal Crônica"},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-25364","number":"25364","sourceNumber":"25364","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Mulher de 59 anos, obesa (IMC 33), vem em uso de várias medicações para\nemagrecer, dentre elas Sibutramina,\nFluoxetina e Espironolactona, orientada por uma ?amiga?.\nComparece ao ambulatório com quadro de letargia, voz arrastada e quedas frequentes. Traz alguns\nexames de laboratório que revelaram Na = 112 mEq/L / TSH = 3,54 mU/L / K = 5,1 mEq/L. O\nexame físico mostrou leve ataxia de marcha com reflexos tendinosos, tônus e força muscular\nnormais. Não havia edema ou desidratação e os sinais vitais eram normais. Marque a afirmação\ncorreta quanto ao caso:","options":{"A":"Trata-se de caso compatível com síndrome de Serotonina onde a hiponatremia se acompanha\nde tônus muscular e reflexos normais.","B":"É um caso típico de hipotireoidismo por falência hipofisária secundária à associação de\nFluoxetina e Sibutramina.","C":"Se a osmolalidade sérica efetiva for menor que 275 mOsm/Kg de água e o ácido úrico sérico for\nmenor que 4 mg/dl o melhor diagnóstico é Secreção Inapropriada de ADH (SIADH).","D":"Mesmo que o cortisol basal seja normal o melhor diagnóstico é Insuficiência Adrenal causada\npela Espironolactona.","E":"O quadro é compatível com Diabetes Insipidus, que se confirma com melhora da hiponatremia\napós uso de DDAVP."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-9019","number":"9019","sourceNumber":"9019","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Dependendo da rapidez da queda da concentração plasmática do sódio, hiponatremia\npode causar convulsões e coma. Hiponatremia é\nclassificada como severa quando:","options":{"A":"Sódio sérico menor que 130 mEq/L","B":"Sódio sérico menor que 120 mEq/L","C":"Sódio sérico menor que 135 mEq/L","D":"Sódio sérico menor que 125 mEq/L"},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-8826","number":"8826","sourceNumber":"8826","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Qual das alternativas é causa de acidose metabólica com anion gap normal?","options":{"A":"Cetose.","B":"Intoxicação por salicilatos.","C":"Uremia.","D":"Sepse.","E":"Fístula entérica."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-6960","number":"6960","sourceNumber":"6960","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Em relação à insuficiência Renal Aguda NÃO podemos afirmar:","options":{"A":"Insuficiência renal aguda com história sugestiva de isquemia (Necrose Tubular Aguda) não tem\nindicação de biópsia renal.","B":"A insuficiência renal aguda por isquemia se caracteriza por uma fase de iniciação, manutenção,\npoliúria e recuperação.","C":"Acidose metabólica refratária a tratamento e edema agudo de pulmão são indicações de\nhemodiálise de urgência.","D":"O paciente com insuficiência renal aguda por necrose tubular aguda recupera a função renal em\nmédia em 15 dias.","E":"Os aminoglicosídeos quando não corrigidos para a função renal podem ser causa de\ninsuficiência renal aguda e esta se caracteriza por ser oligúrica."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-322158","number":"322158","sourceNumber":"322158","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"São considerados anticoagulantes, por bloqueio do fator Xa, EXCETO","options":{"A":"rivaroxabana.","B":"edoxabana.","C":"enoxaparina.","D":"dabigatrana.","E":"apixabana."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-305283","number":"305283","sourceNumber":"305283","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Um paciente em tratamento oncológico quimioterápico, que terá programação de\ntratamento cirúrgico em breve, apresenta\nastenia importante, porém nega vômitos ou\nsangramentos. Foram realizados exames laboratoriais. Qual das alternativas a seguir representa\nindicação de transfusão de ambos os componentes - hemácias e plaquetas - para esse paciente?","options":{"A":"Hemoglobina = 9,1g/dL e plaquetas = 21000/mm³.","B":"Hemoglobina = 6,2g/dL e plaquetas = 18000/mm³.","C":"Hemoglobina = 6,8g/dL e plaquetas = 7000/mm³.","D":"Hemoglobina = 10,1g/dL e plaquetas = 11000/mm³.","E":"Hemoglobina = 7,5g/dL e plaquetas = 11000/mm³."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-305297","number":"305297","sourceNumber":"305297","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre os Anticoagulantes Orais Diretos (DOAC), assinale a opção que NÃO age\natravés do fator Xa.","options":{"A":"Dabigatrana.","B":"Apixabana.","C":"Edoxabana.","D":"Rivaroxabana.","E":"Enoxaparina."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-305302","number":"305302","sourceNumber":"305302","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre a injúria pulmonar aguda relacionada à transfusão (TRALI), é correto afirmar que","options":{"A":"só ocorre nas transfusões de concentrado de hemáceas.","B":"o uso de corticoides sistêmicos está indicado.","C":"nos casos em que a ventilação mecânica seja necessária, volume corrente >8mL/Kg e pressão\nmédia de via aérea acima de 30cm de H20 estão indicados.","D":"o início dos sintomas em até 06 (seis) horas da transfusão é um dos critérios diagnósticos.","E":"o uso de diurético de alça está indicado."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-152106","number":"152106","sourceNumber":"152106","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Considere as três situações seguintes: Paciente 1 - O. S., 34 anos de idade, queixa-se\nde dispneia e desconforto respiratório leve, FR\n= 19 irpm, Sat O2 = 98% e PA de 130 x 80 mmHg;\nPaciente 2 - B. M. S., 65 anos de idade, trabalhador rural, vai à consulta para esclarecer dúvidas a\nrespeito de uma mancha escura na face, perda ponderal e massa palpável no abdome; Paciente 3 -\nAdolescente deu entrada na emergência, após acidente motociclístico, com sangramento ativo de\ndifícil controle em MSE, FC = 99 bpm, PA de 110 x 70 mmHg, consciente e manifestando sede.\n\nCom relação aos casos clínicos apresentados, julgue o item a seguir. A presença de fibrinogênio e\nde fator de von Willebrand (vWF) é\nimportante para o sucesso da aderência plaquetária e de\nhemostasia no caso do Paciente 3.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-105570","number":"105570","sourceNumber":"105570","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Um paciente portador de insuficiência renal crônica, em fase pré-dialítica, apresentou,\nem exame bioquímico de rotina para seguimento,\nureia de 98 mg/dl; creatinina de 3 mg/dl e\npotássio de 6,3 mEq/L. É hipertenso, controlado com medicamentos, e apresentou-se taquicárdico,\nrespectivamente com PA: 145 x 95 mmHg e FC: 110 bpm. Referiu mal-estar geral, mas sem sinais\nou sintomas específicos de alguma morbidade. O exame físico não revelou outras alterações. Com\nbase nesse caso hipotético, a conduta deve ser complementar à avaliação, com realização\nprioritária de:","options":{"A":"Ecocardiograma.","B":"Tomografia computadorizada renal.","C":"Angiorressonância renal.","D":"Eletrocardiograma.","E":"RX de tórax."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-105560","number":"105560","sourceNumber":"105560","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"A concentração de eletrólitos, nos compartimentos corporais, é fundamental para\nhomeostase. Com base nessa informação,\nassinale a alternativa que apresenta o cátion em maior\nconcentração no plasma de uma pessoa normal.","options":{"A":"potássio.","B":"cálcio.","C":"magnésio.","D":"cloro.","E":"sódio."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-52605","number":"52605","sourceNumber":"52605","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"O exame de gasometria arterial, a despeito de ser invasivo, é de realização\nrelativamente simples; seu resultado é\nrapidamente obtido e possibilita a tomada de decisão em\nsituações de urgência e emergência médica. A tabela (VER IMAGEM), em que: pH = potencial\nhidrogeniônico, pO2 = pressão parcial de oxigênio (mmHg), pCO2 = pressão parcial de gás\ncabônico (mmHg), HCO3 - = nível de bicarbonato (mEq/L) e BE = excesso de bases (mEq/L),\nilustra os resultados dos exames dos pacientes hipotéticos A, B e C. Considerando que todas as\namostras foram colhidas de pacientes que respiram espontaneamente ? em ar ambiente e ao nível\ndo mar -, julgue o item a seguir. Os resultados do paciente B são compatíveis com acidose\nrespiratória, sem alterações metabólicas.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-19/52605.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-52610","number":"52610","sourceNumber":"52610","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"O exame de gasometria arterial, a despeito de ser invasivo, é de realização\nrelativamente simples; seu resultado é\nrapidamente obtido e possibilita a tomada de decisão em\nsituações de urgência e emergência médica. A tabela (VER IMAGEM), em que: pH = potencial\nhidrogeniônico, pO2 = pressão parcial de oxigênio (mmHg), pCO2 = pressão parcial de gás\ncabônico (mmHg), HCO3 - = nível de bicarbonato (mEq/L) e BE = excesso de bases (mEq/L),\nilustra os resultados dos exames dos pacientes hipotéticos A, B e C. Considerando que todas as\namostras foram colhidas de pacientes que respiram espontaneamente ? em ar ambiente e ao nível\ndo mar -, julgue o item a seguir. Os achados do paciente C são indicativos de acidose metabólica\ncompensada por alcalose respiratória.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-19/52610.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-45740","number":"45740","sourceNumber":"45740","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Um jogador de futebol, 28 anos de idade, foi operado em um hospital geral por\nvideolaparoscopia, em virtude de uma colecistite crônica. Sua gasometria na sala de recuperação\nanestésica era: pH 7,31; saturação de 95%; pO2 de 85 mmHg; pCO2 de 39 mmHg; BE de - 6,5.\nQuanto ao distúrbio acidobase dessa gasometria, assinale a alternativa correta:","options":{"A":"A gasometria está normal (ausência de distúrbio metabólito ou respiratório).","B":"Trata-se de alcalose respiratória.","C":"Trata-se de acidose metabólica.","D":"Trata-se de alcalose metabólica.","E":"Trata-se de acidose respiratória."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-32152","number":"32152","sourceNumber":"32152","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"As manifestações clínicas mais comuns na IRA consistem em retenção de escórias\nnitrogenadas, oligúria, distúrbios\neletrolíticos e acidobásicos. Considerando um paciente que não\nrequeira emergência para a medida a ser tomada, assinale a alternativa que apresenta a prescrição\nmais eficaz para controlar a hiperpotassemia, comum na IRA, trazendo esse eletrólito de volta a\nníveis normais, de forma duradoura, com poucos efeitos colaterais e em curto espaço de tempo.","options":{"A":"Restrição dietética de potássio.","B":"Suspensão e/ou impedimento do uso de sais dietéticos.","C":"Dosagens altas de diurético de alça, em bolus.","D":"Injeção subcutânea de insulina, em baixas doses ao longo de 24 horas.","E":"Administração, por via oral ou por enema de retenção, de resina de permuta iônica com\npotássio."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-307113","number":"307113","sourceNumber":"307113","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"A causa mais comum de trombocitopenia na infância é Alternativas:","options":{"A":"anemia aplástica.","B":"síndrome de Wiskott-Aldrich.","C":"disfunção plaquetária por uso de medicamentos.","D":"trombocitopenia neonatal.","E":"púrpura trombocitopênica ou imunológica."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-263419","number":"263419","sourceNumber":"263419","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Um pré-escolar com 3 anos de idade, previamente hígido, é atendido no\n\npronto-socorro. A mãe relata que seu filho apresentou manchas no corpo há 2 dias. Além disso,\nrefere que a criança esteve resfriada no mês\nanterior e que melhorou após 5 dias. Durante o exame\nfísico, estava afebril, alerta, com múltiplas petéquias em membros e tronco, pequenos hematomas\nem joelhos, ausência de visceromegalias ou linfonodomegalia. O exame de esfregaço de sangue\nperiférico mostra plaquetas de 57.000/mm³ (valor de referência: 150.000 a 450.000/mm³), com\nmacroplaquetas; células vermelhas e brancas com morfologia e quantidade normais. Nesse caso, o\ndiagnóstico provável e a conduta adequada são, respectivamente:","options":{"A":"Leucemia; aspiração e biópsia de medula óssea.","B":"Púrpura trombocitopênica idiopática; seguimento clínico.","C":"Púrpura trombocitopênica idiopática; corticoide em altas doses.","D":"Leucemia; exames de citometria de fluxo e imuno-histoquímicos."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-175131","number":"175131","sourceNumber":"175131","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"São considerados estados de Hipercoagulabilidade, EXCETO:","options":{"A":"Mutação do Fator V de Leiden","B":"Anticorpo anticardiolipina.","C":"Deficiência de Fator VIII.","D":"Deficiência de Proteína S."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-175132","number":"175132","sourceNumber":"175132","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"As coagulopatias estão invariavelmente presentes em pacientes com doença hepática\naguda ou crônica avançada. Sobre isso, é INCORRETO afirmar:","options":{"A":"Plaquetopenia é encontrada em cerca de 30 a 64% dos cirróticos.","B":"Os fatores dependentes de vitamina K precisam ser carboxidados no fígado, e podem estar\ncomprometidos na disfunção hepática.","C":"Sangramentos em pacientes com plaquetas maiores que 50.000/mm³ são raros.","D":"O volume de plasma a ser transfundido costuma ser de 50 ml/kg, o que reduz o prolongamento\ndo tempo de protrombina para menos de 3\nsegundos."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-104757","number":"104757","sourceNumber":"104757","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Exame gasimétrico que mostra um HCO3 elevado e um pH de 6,8 indica:","options":{"A":"alcalose respiratória.","B":"alcalose respiratória compensada.","C":"acidose respiratória compensada.","D":"acidose respiratória.","E":"ânion-gap normal."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-111291","number":"111291","sourceNumber":"111291","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Um paciente séptico em ventilação espontânea encontra-se no momento com\n\na seguinte gasometria: pH = 7,27; PCO2= 35 mmHg; HCO3? = 10 mEq/L. O (s) distúrbio (s)\napresentado (s) nesse exame é (são):","options":{"A":"Acidose metabólica, somente.","B":"Alcalose respiratória, somente.","C":"Alcalose metabólica e acidose respiratória.","D":"Acidoses metabólica e respiratória.","E":"Acidose metabólica e alcalose respiratória."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-111307","number":"111307","sourceNumber":"111307","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Detectou-se em um paciente a presença, no eletrocardiograma, de onda T apiculada e\nQRS alargado. Tal alteração é decorrente de efeito colateral de um medicamento que o paciente\nvem usando nas últimas. Dentre as abaixo, a droga em questão mais provável é:","options":{"A":"Insulina.","B":"Captopril.","C":"Furosemida.","D":"Anfotericina B.","E":"Fenoterol."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-104748","number":"104748","sourceNumber":"104748","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"O equilíbrio ácido-base é fundamental no pós-operatório, porém, nessa fase, diversos\ndistúrbios podem acometer os pacientes. Acerca dessas alterações, assinale a alternativa correta.","options":{"A":"No compartimento extracelular, o principal tampão é o íon bicarbonato.","B":"O valor do hiato aniônico é calculado pela soma das concentrações plasmáticas dos íons cloreto\ne bicarbonato e de proteínas.","C":"A acidemia grave é considerada sempre que os valores de pH estiverem abaixo de 7,35.","D":"O tratamento da acidose metabólica deve ser feito com a infusão de substâncias ácidas que\nprovocarão o efeito rebote.","E":"A hiperpotassemia tende a ocorrer com maior frenquência nos casos de alcalose metabólica."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-111360","number":"111360","sourceNumber":"111360","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 28 anos, portador de úlcera duodenal estenosante, com vômitos\n\npós-alimentares não biliosos tardios, apresenta-se desidratado e com alterações do equilíbrio\nhidroeletrolítico e acidobásico. Estas alterações caracterizam-se por:","options":{"A":"Alcalose metabólica hipoclorêmica e hipocalêmica.","B":"Acidose respiratória hiponatrêmica e hiperpotassêmica.","C":"Acidose metabólica e acidose respiratória.","D":"Alcalose metabólica hipernatrêmica e hipercalêmica.","E":"Acidose respiratória hiperclorêmica e hipopotassêmica."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-31037","number":"31037","sourceNumber":"31037","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Considerando que, durante a investigação clínica de um paciente de 48 anos de idade\ncom acidose metabólica hiperclorêmica com hiato aniônico (ânion-gap) plasmático dentro da\nnormalidade, tenha-se obtido o diagnóstico de acidose tubular renal distal tipo 1, julgue o item a\nseguir. Nesse caso, o hiato aniônico (ânion-gap) urinário deve apresentar valor nulo ou positivo.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-351615","number":"351615","sourceNumber":"351615","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre o tratamento da anemia em pacientes instáveis, assinale a alternativa\nCORRETA:","options":{"A":"A análise da necessidade de transfusão de hemoderivados em pacientes com instabilidade\nhemodinâmica só deve ser feita após a avaliação da fonte de sangramento e a interrupção da\nhemorragia.","B":"A infusão de volume superior a 1,5L de cristaloides em paciente hemodinamicamente instável\ntem sido associada à redução da mortalidade.","C":"Os pacientes com sangramento ou trauma, estáveis, que não demandam transfusão maciça,\npodem se beneficiar de uma estratégia mais restritiva, mantendo um limiar de hemoglobina de\n7g/dL.","D":"A relação entre a realização de transfusão de concentrados de hemácias frescos versus os\ncongelados e estocados por até 42 dias, apresenta uma diferença significativa no que se refere à\nmortalidade."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-346841","number":"346841","sourceNumber":"346841","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Homem de 21 anos apresenta múltiplas sufusões pelo corpo de início há 3 dias. Nega\ntraumas, outras manifestações clínicas, comorbidades conhecidas, uso de medicamentos e de\ndrogas lícitas ou ilícitas. Não possui história familiar significativa. Ao exame físico, PA:\n110X70mmHg, FC: 68bpm, Tax: 36,5°C. Apresenta sufusões nos membros superiores, inferiores e\ntronco. Sem outras anormalidades quaisquer (incluindo linfonodomegalias ou visceromegalias\nabdominais). Exames de laboratório: Hemoglobina: 15,3g/dL (VR 12-16g/dL); Leucócitos:\n5.840/mm³ (4000-11.000/mm³); Neutrófilos: 2.580/mm³ (1500-7000/mm³); Linfócitos: 1.250/mm³\n(1.000-4.000/mm³); Plaquetas: 9.000/mm³ (150.000 - 450.000/mm³); Hematoscopia do sangue\nperiférico: presença de macroplaquetas, sem outras anormalidades; Creatinina: 0,7mg/dL;\nBilirrubina total: 0,4mg/dL (<1,2mg/dL); PCR: 1,2mg/L (<5mg/L); TSH: 1,560mUI/L (0,5-5,0mUI/L);\nRNI 1,1; PTTa 25/25; Exame de urina sem alterações. Assinale a alternativa que apresenta um\nexame diagnóstico CORRETAMENTE indicado para seguir a propedêutica desse caso.","options":{"A":"Fibrinogênio.","B":"Mielograma.","C":"Anticorpos anti-HIV.","D":"TC de pescoço, tórax e abdome total."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-346858","number":"346858","sourceNumber":"346858","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Em pediatria, são causas de anemia com plaquetopenia, EXCETO:","options":{"A":"Leishmaniose visceral.","B":"Leucemia linfocítica aguda.","C":"Deficiência de folatos e vitamina B12.","D":"Púrpura trombocitopênica autoimune (P.T.I) e púrpura de Henoch- Schonlein."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-291915","number":"291915","sourceNumber":"291915","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Com relação às formas de reversão das coagulopatias relacionadas à anticoagulação\noral, assinale a alternativa CORRETA:","options":{"A":"A ingestão de carvão ativado por via oral é eficiente para a redução da absorção até quatro\nhoras da administração de inibidores diretos\nda trombina.","B":"Os pacientes que utilizaram rivaroxabana devem ser submetidos a diálise nos casos mais\ngraves.","C":"O andexanet alfa deve ser administrado em pacientes que utilizaram inibidores do fator Xa\n(apixaban, rivaroxabana).","D":"O uso de Kcentra 50UI/Kg é indicado para pacientes que utilizaram inibidores da trombina."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-306710","number":"306710","sourceNumber":"306710","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"P.T.C., 32 anos, chega ao PS queixando-se de cansaço, dispneia e palidez cutânea,\nalém de manchas roxas pelo corpo. Foi\nrealizado hemograma cujo resultado demonstra contagem\nde hemácias = 3,32 milhões/mm³, hemoglobina = 6,4 g/dL, hematócrito = 25,6%, volume\ncorpuscular médio = 130fL, RDW 14,6%, Leucócitos = 1.500/mm³, plaquetas = 43.000/mm³. Com\nbase neste caso, assinale a alternativa correta.","options":{"A":"Caso o paciente apresente sangramentos ou febre haverá indicação de transfusão de plaquetas,\ndevendo-se transfundir 01 unidade de plaquetas para cada 15 Kg de peso corpóreo do paciente.","B":"A terapia transfusional liberal com o objetivo de manter níveis normais de hemoglobina\napresenta melhores resultados que a terapia\ntransfusional restritiva, com objetivo de manter\nhemoglobina maior que 7,0g/dL em pacientes não coronariopatas.","C":"A paciente apresenta quadro de pancitopenia, com volume corpuscular médio aumentado,\nquadro muito comum em episódios carenciais, em\nque a deficiência de ácido fólico, relacionada à\nnão ingestão de carne vermelha é a principal causa.","D":"Neste caso há indicação de terapia transfusional com concentrado de hemácias para que seja\nmantenha nível de hemoglobina acima de 7,0g/dL, devendo-se coletar exames de avaliação do\nperfil de ferro, reticulócitos, dosagem de vitamina B12 e ácido fólico anteriormente à transfusão."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-287854","number":"287854","sourceNumber":"287854","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Em relação aos distúrbios da coagulação, assinalar a alternativa CORRETA:","options":{"A":"TTPa avalia integridade da via extrínseca da coagulação.","B":"Diagnóstico de hemofilia deve ser fortemente suspeitado quando o TTPa for diminuído.","C":"Doença de von Willebrand é a coagulopatia hereditária mais comum.","D":"Pacientes com plaquetopenia, em geral, apresentam hematomas musculares ou sangramentos\nintra-abdominais, enquanto pacientes com deficiência de fatores de coagulação, em geral,\napresentam sangramento em pele e mucosas.","E":"TP avalia integridade da via intrínseca da coagulação."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-283924","number":"283924","sourceNumber":"283924","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Uma criança de 5 anos é atendida no ambulatório por gengivorragia após escovação de\ndentes, episódios que se repetiam há 3 dias. Havia apresentado tosse, coriza hialina, diarreia e\nfebrícula na semana passada. Ao exame físico, a criança está em bom estado geral,\n\nobservando-se a presença de petéquias em pescoço e pálpebras e hematomas em ambos os\nmembros inferiores. Seus principais exames\ncomplementares mostram ecografia abdominal normal,\nhemoglobina de 11g/dl, leucócitos de 8.300/mm³ sem formas jovens e plaquetas de 21.000/mm³. A\nhipótese diagnóstica mais provável é:","options":{"A":"Síndrome hematofagocítica.","B":"Leucemia linfocítica aguda.","C":"Leucemia mielocítica aguda.","D":"Púrpura de Henoch-Schönlein.","E":"Púrpura trombocitopênica imune."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-227075","number":"227075","sourceNumber":"227075","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Homem de 18 anos se queixa de manchas roxas nos 4 membros há 3 semanas.\nDesconhece doenças prévias, nega uso de\nmedicamentos ou uso de quaisquer drogas ilícitas. Sem\noutras queixas. O exame físico revela áreas de sufusão na pele dos membros superiores e\ninferiores, indolores e planas. Sem outras anormalidades. Exame de laboratório: hemoglobina 15,1\ng/dl, VCM 88 fl, HCM 28 pg, CHCM 34 g/dl, leucócitos 7.800/mm³, neutrófilos 4.560/mm³, linfócitos\n1.240/mm³, plaquetas 4.000/mm³. Considerando o caso descrito, assinale a alternativa que\napresente um teste que NÃO está indicado na propedêutica inicial do paciente:","options":{"A":"Hematoscopia do sangue periférico.","B":"Mielograma.","C":"Sorologia para HIV.","D":"Sorologias para hepatites virais."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-212962","number":"212962","sourceNumber":"212962","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Em qual das seguintes situações está correta a indicação da transfusão de\nhemoderivados?","options":{"A":"Transfusão de concentrado de plaquetas em quando contagem plaquetária < 50.000/µL, mesmo\nna ausência de fatores de risco.","B":"Transfusão de concentrado de plaquetas nos casos de dengue com contagem plaquetária <\n10.000/µL, independente da existência ou não de sangramentos.","C":"Transfusão de concentrado de plaquetas nos casos de cirurgia neurológica com contagem\nplaquetária < 100.000/µL.","D":"Transfusão de concentrado de hemácias nos casos de pré-operatório de cirurgia abdominal de\ngrande porte com Hb < 11,0 g/dl.","E":"Transfusão de crioprecipitado nos casos de sangramento ativo com INR > 2,0."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-215096","number":"215096","sourceNumber":"215096","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sr. RGP, vítima de acidente automobilístico grave, foi submetido a laparotomia\nexploradora que evidenciou grave lesão\nhepática, e volumoso hemoperitôneo, sendo necessária a\nexérese de 50% do lobo esquerdo do fígado. Exames: Hb 6,8 g/dl; Htco. 18,3%; plaquetas =\n22.000; TAP 40% (N = 70% a 120%) e PTTa 66?? (N = 29?? +/- 9??). Quais hemocomponentes\nvocê utilizaria para tratar o Sr. RGP, sabendo que ele é ?A? positivo?","options":{"A":"Sangue total A positivo, pois o paciente necessita repor hemácias, plaquetas e fatores da\ncoagulação.","B":"Concentrado de hemácias A positivo, plaquetas e crioprecipitado, pois houve grave lesão\nhepática.","C":"Sangue total A positivo, infundidos rapidamente, para não perdermos a ação dos fatores de\ncoagulação termo-lábeis.","D":"Concentrado de hemácias A positivo, plaquetas por aférese e plasma rico em plaquetas, pois a\nlesão mais grave é a plaquetopenia.","E":"Concentrado de hemácias A positivo, plaquetas e plasma fresco congelado."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-202773","number":"202773","sourceNumber":"202773","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Um paciente portador de púrpura trombocitopênica idiopática que é submetido à\nesplenectomia, deve ser submetido à imunização contra:","options":{"A":"Streptococcus pneumoniae, Haemophilus influenzae, Mycobacterium bovis.","B":"Streptococcus pneumoniae, Neisseria meningitidis, Mycobacterium bovis.","C":"Haemophilus influenzae, Neisseria meningitidis, Mycobacterium bovis.","D":"Streptococcus pneumoniae, vírus da hepatite B, Neisseria meningitidis.","E":"Streptococcus pneumoniae, Haemophilus influenzae, Neisseria meningitidis."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-162588","number":"162588","sourceNumber":"162588","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente feminina de 18 anos de idade consulta para pré-operatório de mamoplastia\nredutora. Refere história de sangramento intenso\napós extração dentária. Exames pré-operatórios\ndemonstraram hemograma normal, TTPA 52s (VR: < 35s), INR 1,02 (VR: 1,0 ? 1,3). Qual o\ndiagnóstico mais provável?","options":{"A":"Afibrinogenemia congênita.","B":"Hemofilia A.","C":"Doença de Von Willebrand.","D":"Deficiência de Fator XIII.","E":"Deficiência de Fator V."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-127219","number":"127219","sourceNumber":"127219","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"São medicamentos que podem levar à hiperpotassemia, EXCETO:","options":{"A":"Valsartana.","B":"Heparina.","C":"Trimetoprima.","D":"Espironolactona.","E":"Fenoterol."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-131615","number":"131615","sourceNumber":"131615","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Se 1 litro de solução de NaCl a 0.9% é administrado por via endovenosa, quanto será\ndistribuído para o espaço intersticial?","options":{"A":"100 cc","B":"250 cc","C":"350 cc","D":"500 cc","E":"750 cc"},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-126891","number":"126891","sourceNumber":"126891","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Em relação aos distúrbios do equilíbrio acidobásico, analise as afirmativas abaixo e\nassinale V para as Verdadeiras e F para as Falsas. ( ) Os principais órgãos envolvidos na\nmanutenção do equilíbrio acidobásico são os rins e os pulmões. ( ) Independentemente da situação\nclínica, os estados de acidose são sempre acompanhados de pH < 7,35. ( ) A cetoacidose diabética\né uma acidose metabólica com ânion-gap aumentado. ( ) O tratamento com infusão intravenosa de\nbicarbonato de sódio deve sempre ser realizado nos casos de acidose metabólica. Assinale a\nalternativa que apresenta a sequência CORRETA:","options":{"A":"V, F, V, F.","B":"V, F, F, F.","C":"V, V, V, F.","D":"F, F, V, F."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-131625","number":"131625","sourceNumber":"131625","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Qual é o maior compartimento líquido do corpo?","options":{"A":"Plasma","B":"Fluido espinhal central","C":"Fluido intersticial","D":"Fluido intracelular","E":"nenhuma das anteriores"},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-88841","number":"88841","sourceNumber":"88841","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Em relação à solução de cloreto de sódio a 0,9%,","options":{"A":"1 litro contém 90 gramas de sódio.","B":"na solução, existe, 131mmol/L Na.","C":"na solução, encontram-se 154 mmol/L Na.","D":"tem um ph de 7,5.","E":"quando administrada em excesso, causa acidose hipoclorêmica."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-77347","number":"77347","sourceNumber":"77347","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Num paciente em pós-operatório de gastrectomia total, você é orientado a garantir um\nsuporte calórico de 400 kcal em 24 horas, pois o mesmo permanecerá em dieta zero. Dispondo,\npara isso, de ampolas de 10 ml de SG 50% (glicose anidra) para serem distribuídas na hidratação\ncom soro fisiológico que o paciente receberá. No dia seguinte, você identifica nos exames um nível\nde potássio de 2,1 mg/dl, sintomático, e com alteração eletrocardiográfica. Neste caso:","options":{"A":"É necessária reposição rápida de potássio, com velocidade superior a 40 mEq/h.","B":"Caso a reposição seja feita em veia periférica, deve-se usar idealmente soluções com\nconcentração inferior a 40 mEq/L.","C":"O cálculo da reposição deverá ser feito de maneira muito precisa, utilizando-se das fórmulas\ndisponíveis, validadas e confiáveis.","D":"Em hipótese alguma repor magnésio junto, ou antes, da correção do potássio sob risco de\nagravamento da hipocalemia.","E":"Devido à alteração eletrocardiográfica identificada, deve-se administrar imediatamente gluconato\nde cálcio para estabilização da membrana\ncelular e prevenção de arritmias graves."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-43336","number":"43336","sourceNumber":"43336","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Acerca da hipercalemia, marque a alternativa INCORRETA:","options":{"A":"As alterações eletrocardiográficas se devem ao fato da hipercalemia despolarizar a membrana\nda célula, retardar a condução ventricular e\ndiminuir a duração do potencial de ação.","B":"Eletrocardiogramas normais podem ser vistos mesmo em pacientes com hipercalemia grave.","C":"Os efeitos eletrofisiológicos da hipercalemia são diretamente relacionados ao nível de potássio\nsérico e inversamente relacionados à velocidade de instalação da hipercalemia.","D":"As metas terapêuticas na hipercalemia são: 1) estabilizar a membrana celular, 2) redistribuir o\npotássio extracelular para dentro das células e 3) aumentar a eliminação de potássio do corpo.","E":"Contribuem para a redistribuição do potássio as seguintes medidas terapêuticas: solução\nglicoinsulínica, salbutamol e o uso do bicarbonato em algumas situações."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-43297","number":"43297","sourceNumber":"43297","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Pré-escolar evoluiu no pós-operatório de um glioma óptico com: poliúria, polidipsia e\nhipernatremia por aproximadamente 24 horas. No dia seguinte, apresentou melhora da polidipsia e\npoliúria, porém com hiponatremia e osmolalidade urinária \"maior que\" 100 mOsm/kg por 5 dias.\n\nDepois, com quadro de desidratação, polidipsia, poliúria, hipernatremia, osmolidade do soro \"maior\nque\" 300 mOsm/kg e osmolidade urinária\n\"menor que\" 300 mOsm/kg. De acordo com as alterações\napresentadas por essa criança, podemos afirmar:","options":{"A":"Trata-se de um quadro clássico de estresse cirúrgico somado ao grande volume de fluidos\nadministrados e a perda de sangue durante a cirurgia. Comum em cirurgias complexas.","B":"Deve-se suspeitar da resposta trifásica após cirurgia, onde há uma fase inicial de Diabetes\nInsipidus transitória, seguida por uma fase de Síndrome de Secreção Imprópria do Hormônio\nAntidiurético e depois, por Diabetes Insipidus permanente.","C":"Deve-se suspeitar de Diabete Insípido Central devido ao glioma óptico, porém esse quadro terá\numa duração de aproximadamente 1 mês, sendo que o tratamento cirúrgico é eficaz.","D":"Deve-se suspeitar de uma Síndrome de Secreção Inapropriada de Hormônio Antidiurético, onde\nessa evolução é clássica no pós-operatório de\nglioma óptico."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-363983","number":"363983","sourceNumber":"363983","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"A doença de von Willebrand subtipo 2A se caracteriza por","options":{"A":"aumento da ligação do fator de von Willebrand às plaquetas, levando à plaquetopenia.","B":"redução da ligação do fator de von Willebrand às plaquetas e ao colágeno, com redução dos\nníveis séricos de fator de von Willebrand.","C":"perda da função de ligação do fator de von Willebrand às plaquetas, com uma redução dos\nmultímeros de alto peso molecular mais efetivos.","D":"redução da ligação do fator de von Willebrand ao fator VIII da coagulação, com redução dos\nníveis séricos de fator de von Willebrand e do fator VIII."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-354823","number":"354823","sourceNumber":"354823","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Leia o relato do caso clínico a seguir. Paciente cirrótico Child-Pugh C, 53 anos de\nidade, apresenta quadro clínico e radiológico\ncompatível com apendicite aguda. A equipe cirúrgica\nindicou apendicectomia. Os resultados dos exames laboratoriais atuais são: Hb: 12,6 g/dL; Ht:\n38,9%, LT: 4200; plaq: 78.000 cel/mm³; tempo de protrombina: RNI: 1,69; tempo de tromboplastina\nparcial ativado: relação P/N: 1,31. De acordo com o caso relatado, qual é a conduta transfusional a\nser adotada?","options":{"A":"Transfusão de 1 UI de plaquetaférese pré-procedimento cirúrgico.","B":"Transfusão de 10 mL/Kg de plasma fresco congelado pré-procedimento.","C":"Transfusão de 2 UI de plaquetaférese pré-procedimento cirúrgico.","D":"Transfusão de 25 mL/Kg de plasma fresco congelado pré-procedimento."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-354797","number":"354797","sourceNumber":"354797","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Leia o relato do caso clínico a seguir. Paciente, 19 anos de idade, sexo masculino,\napresenta confusão mental e cefaleia há 4 dias,\nalém de petéquias em todo o corpo. Os resultados\ndos exames laboratoriais são: Hb: 5,5g/dL; Plaquetas: 29.000/mm³; Esquizócitos em lâmina de\nsangue periférico; Desidrogenase lática (DHL): 2.400 UI/dL (VR: até 246 UI/dL); Teste antiglobina\ndireto: negativo. De acordo com o caso relatado qual é a principal suspeita diagnóstica?","options":{"A":"Anemia hemolítica auto-imune.","B":"Microangiopatia trombótica.","C":"Púrpura trombocitopênica imune.","D":"Aplasia de medula óssea."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-342630","number":"342630","sourceNumber":"342630","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Um homem de 49 anos apresenta insuficiência renal aguda e diminuição do nível de\nconsciência. Exames laboratoriais revelam leucocitose discreta com neutrofilia e trombocitopenia\nsevera (<10.000/mm?). A avaliação do sangue periférico, por sua vez, mostra anemia\nmicroangiopática. Os testes de coagulação são normais. O diagnóstico mais provável é:","options":{"A":"anemia hemolítica autoimune","B":"púrpura trombocitopênica trombótica","C":"coagulação intravascul lar disseminada","D":"síndrome do anticorpo antifosfolípide"},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-315769","number":"315769","sourceNumber":"315769","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Quando a TFGe chegar em 15mL/ min/1,73m2, devemos evitar o uso de enoxaparina.\nEstá correto que:","options":{"A":"Uma alternativa nessa condição é a Heparina Não Fracionada HNF, pois tem metabolismo\nexclusivamente renal.","B":"Uma alternativa nessa condição não é a Heparina Não Fracionada HNF, pois tem metabolismo\nexclusivamente hepático.","C":"Uma alternativa nessa condição é a Heparina Não Fracionada HNF, pois tem metabolismo\nexclusivamente hepático.","D":"Uma alternativa nessa condição é a Heparina Não Fracionada HNF, pois tem metabolismo não\nexclusivamente hepático."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-315774","number":"315774","sourceNumber":"315774","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Entre os anticoagulantes injetáveis, a HNF foi a primeira sintetizada. Sendo correto o\nitem:","options":{"A":"A heparina é um polissacarídeo não sulfatado com uma faixa de peso molecular de 3.000 a\n30.000Da (média, 15.000Da).","B":"A heparina é um amido sulfatado com uma faixa de peso molecular de 3.000 a 30.000Da\n(média, 15.000Da).","C":"A heparina é um polissacarídeo sulfatado com uma faixa de peso molecular de 3.000 a\n30.000Da (média, 15.000Da).","D":"A heparina é um ácido sulfatado com uma faixa de peso molecular de 3.000 a 30.000Da (média,\n15.000Da)."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-294263","number":"294263","sourceNumber":"294263","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Qual dos anticoagulantes diretos a seguir tem maior depuração renal?","options":{"A":"Dabigatrana.","B":"Rivaroxabana.","C":"Edoxabana.","D":"Apixabana."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-311913","number":"311913","sourceNumber":"311913","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Na avaliação de um paciente com um possível estado de hipercoagulabilidade,","options":{"A":"se o paciente apresentar necrose cutânea após iniciar uso de varfarina, deve-se pesquisar\ndeficiência de proteína C ou proteína S.","B":"níveis séricos diminuídos de proteína C, proteína S e antitrombina em pacientes com trombose\naguda apontam para distúrbio hereditário da\ncoagulação.","C":"a ocorrência de trombose arterial, após os 40 anos, em pacientes com história familiar para\ntrombose, indica a presença de estados de hipercoagulabilidade hereditários.","D":"a trombose de veia hepática (síndrome de Budd-Chiari) ou a trombose de veia porta podem\nindicar neoplasia maligna oculta ou endocardite não bacteriana."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-317945","number":"317945","sourceNumber":"317945","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Qual das seguintes proteínas inibe a hemostasia?","options":{"A":"Trombina.","B":"Fator tecidual.","C":"Fibrina.","D":"Proteína C."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-294272","number":"294272","sourceNumber":"294272","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Diante de paciente jovem do sexo feminino com quadro de anemia hemolítica\nmicroangiopática, trombocitopenia, manifestação neurológica e aumento de escórias renais, a\nmelhor hipótese diagnóstica é de:","options":{"A":"Púrpura trombocitopênica imune.","B":"Púrpura trombocitopênica trombótica.","C":"Púrpura de Gardner-Diamond.","D":"Púrpura de Henoch-Schönlein."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-311914","number":"311914","sourceNumber":"311914","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre os anticoagulantes de ação direta (DOAC), afirma-se:","options":{"A":"a apixabana tem tempo de meia-vida entre 9 a 14 horas e, apesar da posologia de duas\ntomadas diárias, apresenta baixa taxa de sangramentos em relação à varfarina.","B":"a rivaroxabana foi o primeiro DOAC a ser aprovado e, por possuir tempo de meia-vida de quase\n24h, permite o uso em dose única diária.","C":"a dabigatrana é um inibidor direto do fator X ativado que apresenta metabolização hepática e\neliminação predominantemente intestinal.","D":"a edoxabana é um pró-fármaco cujo metabólito ativo inibe diretamente a trombina, sendo seu\nuso restrito em renais crônicos por ter\neliminação predominantemente renal."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-302866","number":"302866","sourceNumber":"302866","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Menino de três anos é admitido no pronto atendimento com queixa de epistaxe\nespontânea há algumas horas, de volume\npequeno. A mãe do paciente relata história de infecção\nviral do trato gastrointestinal (diarreia aguda) há 2 semanas, com resolução completa. Ao exame:\nbom estado geral, corado, hidratado. Ausculta cardíaca e pulmonar sem alterações. Baço, fígado e\nlinfonodos não palpáveis. Equimoses e petéquias evidentes em membros inferiores, sem outras\nalterações. Hemograma evidenciando: hemoglobina 13,0 g/dl; VCM 80 fL; leucócitos 9.700/mm3,\ncom contagem diferencial normal; plaquetas 15.000/mm3; 1% de reticulócitos. O diagnóstico mais\nprovável é:","options":{"A":"Leucemia aguda.","B":"Síndrome hemolítico-urêmica.","C":"Púrpura trombocitopênica trombótica.","D":"Púrpura trombocitopênica idiopática.","E":"Doença de Gaucher."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-313216","number":"313216","sourceNumber":"313216","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"O uso da vitamina K profilática no recém-nascido reduz a incidência de que patologia?","options":{"A":"icterícia neonatal","B":"doença hemorrágica do recém-nascido","C":"fenilcetonúria","D":"sepse neonatal"},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-300981","number":"300981","sourceNumber":"300981","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"O uso de heparina não fracionada no ambiente hospitalar é uma rotina do clínico e faz\nparte do arsenal no manejo de profilaxia de tromboembolismo venoso, quanto das medidas para\nanticoagulação plena. O exame laboratorial para controle de anticoagulação desta droga é:","options":{"A":"Tempo de Protrombina (TAP).","B":"Tempo de Tromboplastina Parcial Ativada (TTPA).","C":"Dosagem de fator VIII.","D":"Tempo de Sangramento (TS)."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-281982","number":"281982","sourceNumber":"281982","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Os quadros clínicos compatíveis com sangramentos relacionados a defeitos na\nhemostasia primária são:","options":{"A":"Hemartroses e sangramento em trato gastrointestinal (TGI).","B":"Petéquias e sangramento mucocutâneo.","C":"Hematomas musculares e sangramento em sistema nervoso central.","D":"Hemartroses e hematúria."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-257726","number":"257726","sourceNumber":"257726","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Mulher de 72 anos é admitida na unidade de emergência após acidente automotivo. A\nhistória médica pregressa inclui insuficiência renal leve, fibrilação atrial, hipertensão e\ndiabetes. Ela\nestá atualmente tomando lisinopril, varfarina e metformina. Os valores dos resultados dos testes\nlaboratoriais incluem: contagem de leucócitos 12.000/µL com diferencial normal, hemoglobina 7,4\ng/dL, plaquetas 256.000/µL e INR 4,86. A esplenectomia emergencial é realizada após laceração\nesplênica. A paciente recebeu sete unidades de glóbulos vermelhos de doadores ABO compatíveis\ne seis unidades de plasma fresco congelado. Sua evolução no pós-operatório imediato é normal e\nela está recebendo fluidos intravenosos contínuos. Oito horas depois, a enfermeira relata dispneia\ne taquicardia progressivas. Ela não tem febre ou expectoração. O exame revela uma saturação de\noxigênio de 90% pela oximetria de pulso, frequência cardíaca de 106 BPM, pressão arterial de\n160/90 mmHg, distensão venosa jugular, 2+ edema bilateral de membros inferiores, sem\nsensibilidade na panturrilha e fígado palpável. A radiografia de tórax demonstra pequeno derrame\npleural bilateral e infiltrados hilares. Qual é a próxima etapa mais apropriada no manejo desse\npaciente?","options":{"A":"Antibióticos de amplo espectro.","B":"Anticoagulação empírica e angiotomografia computadorizada.","C":"Furosemida.","D":"Esteróides."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-232205","number":"232205","sourceNumber":"232205","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"O distúrbio hipercoagulável genético mais comum associado a alto risco de\ntromboembolia venosa é:","options":{"A":"deficiência de proteína C.","B":"deficiência de proteína S.","C":"deficiência de antitrombina.","D":"deficiência do fator V de Leiden."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-231938","number":"231938","sourceNumber":"231938","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Uma jovem de 23 anos, hígida, procura a Emergência de devido a \"alergia\" na perna.\nVocê avaliou e viu que apresentava petéquias\nem MMII, com o restante do exame físico normal. A\npaciente nega qualquer tipo de sangramento. Você solicitou um hemograma, e veio o seguinte\nresultado: Hb 12,8g/dL; leucócitos = 6.200/mm³ (diferencial normal); e plaquetas = 26.000/mm³\n(com revisão microscópica). A conduta terapêutica correta mais adequada é:","options":{"A":"transfundir plaquetas","B":"repetir contagem plaquetária no citrato","C":"realizar aspirado de medula óssea","D":"iniciar corticoide","E":"indicar plasmaférese"},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-229541","number":"229541","sourceNumber":"229541","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Qual o PRINCIPAL exame para controle laboratorial no uso de heparina não\nfracionada?","options":{"A":"Tempo de protrombina.","B":"Tempo de tromboplastina parcial ativada.","C":"Hemograma.","D":"Tempo de sangramento."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-232290","number":"232290","sourceNumber":"232290","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Na criança, a trombocitopenia imune primária:","options":{"A":"É geralmente um distúrbio agudo, autolimitado e imunomediado.","B":"É caracterizada por trombocitopenia (plaquetas menores de 40000/mm³) isolada ou secundária.","C":"Ocorre em 80-85% dos casos na forma persistente.","D":"Ocorre na forma recém-diagnosticada quando a remissão se dá em menos de seis meses."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-214935","number":"214935","sourceNumber":"214935","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Qual evento está relacionado à deficiência da fase primária da coagulação, que é uma\ndas causas de sangramento genital na\npuberdade:","options":{"A":"diminuição de fibrinogênio","B":"doença de von Willebrand","C":"aumento de antitrombina III","D":"alterações intrínsecas no fator IV"},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-202726","number":"202726","sourceNumber":"202726","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Leia o caso clínico a seguir. Um homem de 68 anos foi internado em unidade de terapia\nintensiva por insuficiência respiratória aguda 72 horas após hemicolectomia. A pressão era de\n100/60 mmHg, a frequencia cardíaca de 120 batimentos por minuto (regular), a frequência\nrespiratória de 28 respirações por minuto e temperatura de 38,1 °C. A análise da gasometria\narterial mostrou PaO? de 63 mmHg e saturação de oxigênio de 84%, com oxigênio suplementar de\n5 L/min. A análise laboratorial mostrou concentração de hemoglobina de 11,0 g/dL, 84% de\nneutrófilos com desvio à esquerda notável, alguns esquizócitos no esfregaço de sangue periférico,\ncreatinina de 2,4 mg/dL e concentração de bilirrubina total de 1,2 mg/dL. O paciente foi intubado e\nventilado, obtendo uma saturação de oxigênio de 98% e estabilizado hemodinamicamente com\ncristaloides e administração intravenosa de vasopressor. Ele foi tratado com antibióticos de amplo\nespectro e contínua profilaxia com heparina subcutânea. Testes de coagulação de rotina\nmostraram uma contagem de plaquetas de 98.000 (152.000 no dia anterior), um tempo de\nprotrombina (TP) de 17 segundos (normal, <12 segundos), o que equivale a uma razão\nnormalizada internacional (INR) de 1,4, tempo de tromboplastina parcial ativada de 43 segundos\n(normal, <28 segundos), concentração de D-dímero de 7,5 µg/mL (normal, <0,5 µg/mL) e\nconcentração de fibrinogênio de 3,5 g/L (normal, 1,3 g/l). O diagnóstico do paciente é:","options":{"A":"púrpura trombocitopênica trombótica.","B":"coagulação intravascular disseminada.","C":"tromboembolismo pulmonar.","D":"trombocitopenia induzida por heparina."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-201734","number":"201734","sourceNumber":"201734","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Na deficiência do fator XII, há:","options":{"A":"Hemorragias cutâneo-mucosas espontâneas.","B":"Associação com cistos hepáticos.","C":"Micro-hemorragias cerebrais.","D":"Prolongamento do TTPa, sem consequências clínicas."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-216476","number":"216476","sourceNumber":"216476","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Marque a alternativa correta:","options":{"A":"A hemofilia é uma doença hemorrágica recessiva ligada ao Y.","B":"A hemofilia B representa 80% dos casos de hemofilia.","C":"A hemofilia se caracteriza clinicamente por eventos recorrentes de tromboembolismo venoso e\narterial.","D":"Os homens apresentam manifestações clínicas da doença, enquanto as mulheres são\nportadoras de um gene mutante e em geral são assintomáticas."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-178754","number":"178754","sourceNumber":"178754","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente do sexo feminino, 19 anos, portadora de leucemia mieloide aguda em\ntratamento quimioterápico. Apresenta-se no\npronto-atendimento com anemia importante (Hb: 6.2) e\ninforma dois episódios de reação febril não hemolítica. Qual a melhor escolha para a transfusão de\nconcentrado de hemácias nessa paciente?","options":{"A":"Irradiado.","B":"Deleucotizado.","C":"Fenotipado.","D":"Lavado com solução salina.","E":"Convencional."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-187695","number":"187695","sourceNumber":"187695","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Não é causa de prolongamento do tempo de Protrombina:","options":{"A":"Hipofibrinogenemia.","B":"Doença de Von Willebrand.","C":"Deficiência do fator VII.","D":"Coagulacação intra-vascular disseminada."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-187715","number":"187715","sourceNumber":"187715","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Para reverter a anticoagulação causada pelo uso da heparina, utilizam-se:","options":{"A":"Infusão de antitrombina III e plasma fresco.","B":"Vitamina K e plasma fresco.","C":"Plasma fresco e sulfato de protamina.","D":"Ácido épsilon aminocapróico e sulfato de protamina."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-186502","number":"186502","sourceNumber":"186502","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Entre as anormalidades abaixo, qual NÃO é sugestiva de púrpura trombocitopênica\ntrombótica:","options":{"A":"Aumento dos níveis de lactato-desidrogenase.","B":"Aumento da bilirrubina indireta.","C":"Altas concentrações de haptoglobina.","D":"Plaquetopenia."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-178794","number":"178794","sourceNumber":"178794","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Uma criança de 5 anos com quadro de epistaxe, gengivorragia e equimoses em\nmembros inferiores há 3 dias, precedido por\nquadro de resfriado comum, apresenta exame físico\nsem linfonodos palpáveis ou hepatoesplenomegalia. Apresenta ao hemograma plaquetopenia\nisolada de 6.000 plaquetas. Qual é a terapêutica de primeira opção para o quadro?","options":{"A":"Imunoglobulina humana intravenosa.","B":"Ácido tranexâmico.","C":"Ácido aminocaproico.","D":"Transfusão de plaquetas.","E":"Mielograma."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-183269","number":"183269","sourceNumber":"183269","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre a transfusão de concentrado de hemácias para perdas sanguíneas agudas, é\nINCORRETO afirmar:","options":{"A":"Com hemoglobina menor que 6 g/gL a transfusão geralmente é necessária.","B":"Hemoglobinas entre 6 e 10 g/dL a transfusão é ditada por circunstâncias clínicas.","C":"Perdas sanguíneas rápidas estimadas em 30% exigem transfusão rápida.","D":"Hemoglobinas maiores que 10 g/dL raramente requerem transfusão."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-156970","number":"156970","sourceNumber":"156970","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Qual evento está relacionado à deficiência da fase primária da coagulação, que é uma\ndas causas de sangramento genital na\npuberdade?","options":{"A":"Diminuição de fibrinogênio.","B":"Doença de von Willebrand.","C":"Aumento de antitrombina III.","D":"Alterações intrínsecas no fator IV."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-150224","number":"150224","sourceNumber":"150224","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 60 anos, do sexo masculino, em tratamento para leucemia mieloide aguda,\nsubtipo M2. Pesa 64 quilos. Chega no dia 18 de indução da remissão para avaliação ambulatorial.\nEncontra-se assintomático, apresentando hemograma do dia com hemoglobina de 8,0 g/dL,\nleucócitos totais de 400/ul e contagem plaquetária de 15.000/uL. Nesse caso, qual é a conduta\nindicada?","options":{"A":"Transfusão de duas unidades de concentrado de hemácias.","B":"Observação.","C":"Transfusão de duas unidades de concentrado de hemácias e aplicação de Granulokine\nsubcutânea até recuperação de série branca.","D":"Transfusão de uma aférese de plaquetas ou seis unidades de concentrado de plaquetas."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-150760","number":"150760","sourceNumber":"150760","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Com relação às reações transfusionais:","options":{"A":"As reações ditas leves são desconsideradas pelo NOTIVISA (Sistema de Notificação em\nVigilância Sanitária).","B":"Os sintomas mais comuns na reação febril não hemolítica são tremores, calafrios e febre.","C":"A investigação e notificação da reação transfusional é de responsabilidade exclusiva do banco\nde sangue que distribuiu a unidade\ntransfundida.","D":"O acúmulo de citocinas em concentrados de hemácias é causa de reações do tipo\nincompatibilidade ABO."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-136556","number":"136556","sourceNumber":"136556","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Por que a solução fisiológica a 0,9% NÃO é de fato fisiológica?","options":{"A":"Devido à concentração de sódio e cloro ser maior que a concentração sérica do plasma.","B":"Devido à concentração de cálcio ser maior que a concentração sérica do plasma.","C":"Devido à concentração de potássio ser maior que o potássio plasmático.","D":"Devido à concentração de sódio e potássio ser maior que a concentração plasmática."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-137031","number":"137031","sourceNumber":"137031","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Criança com dez anos de idade encaminhada ao pronto-atendimento médico com\nquadro de cianose, tiragens subcostais e\nintercostais, taquidispneia. Solicitada gasometria que\nmostrou os seguintes valores: PH 7,30 HCO3 26; PCO2 50; PO2 90; Sat O2 97; BE - 3. Qual a\nprovável patologia dessa criança?","options":{"A":"Obstrução respiratória.","B":"Hiperaldosteronismo primário.","C":"Intoxicação Salicílica.","D":"Cetoacidose diabética."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-103633","number":"103633","sourceNumber":"103633","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Entende-se hipovolemia por um volume de sangue menor do que o normal, e que pode\nocorrer:","options":{"A":"Por perda de sangue total, plasma, água e sal, e dissecação.","B":"Somente por perda de sangue total.","C":"Às vezes por perda de sangue, água e sal.","D":"Duas acima estão certas."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-101174","number":"101174","sourceNumber":"101174","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente com doença renal crônica, anúrica, em hemodiálise há cinco anos, procura a\nemergência com queixas de fraqueza muscular generalizada e incapacidade para deambulação. A\navaliação laboratorial evidencia: creatinina = 5,0 mg/dl; ureia = 120 mg/dl; potássio = 7,5 mEq/L;\npH\n\n= 7,34; bicarbonato = 22. O eletrocardiograma apresenta ondas T apiculadas e achatamento da\nonda P. A conduta para reduzir mais\nrapidamente a concentração plasmática de potássio, nesse\npaciente, é a:","options":{"A":"Administração intravenosa de gluconato de cálcio.","B":"Administração intravenosa de diurético de alça.","C":"Administração por nebulização de agonista beta-2 adrenérgico.","D":"Administração oral e por enema retal de resina de troca."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-101234","number":"101234","sourceNumber":"101234","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Uma gestante com 40 semanas de idade gestacional e portadora de diabetes mellitus\ntipo 1 foi admitida para realizar uma\ncesariana devido ao pós-datismo. Na ocasião, apresentava\nhemoglobina glicosilada de 10% e diminuição dos movimentos fetais. Durante a cesariana, foi\nobservado que o líquido aminiótico era meconial +++/4+. O recém-nascido chorou logo que nasceu\ne, ao ser recebido, apesar do choro forte e da frequência cardíaca de 120 bpm, encontrava-se com\ncianose central. Após estabilização, o recém-nascido necessitou ser mantido em ventilação\nmecânica invasiva e, apesar da fração de oxigênio ofertada de 100%, ainda mantinha cianose\ncentral e saturava 60%. Foram realizadas radiografia de tórax e gasometria arterial, cujos\nresultados são apresentados a seguir (VER IMAGEM). Gasometria arterial: pH = 7,30; PCO2 = 42;\nPO2 = 40; bicarbonato = 15; BE = -10; Sat = 57%. Os resultados da gasometria arterial são\nindicativos de:","options":{"A":"acidose metabólica e hipóxia.","B":"acidose mista e hipóxia.","C":"acidose respiratória e hipóxia.","D":"gasometria venosa, devendo ser realizada nova coleta para a confirmação."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-19/101234.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-83657","number":"83657","sourceNumber":"83657","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Um homem de 72 anos, em pós-operatório de cirurgia de grande porte, apresenta\nletargia progressiva e convulsão. Qual distúrbio\nprovavelmente é responsável por esse quadro?","options":{"A":"Hipopotassemia.","B":"Hipomagnesemia.","C":"Hipoglicemia.","D":"Hipocalcemia.","E":"Hiponatremia."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-63273","number":"63273","sourceNumber":"63273","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Mauricio, 1 ano, lactente, apresenta distúrbio hidroeletrolítico classificado como\nhipernatremia hipovolêmica (desidratação grave;\nsódio sérico = 168 mEq/L). Após 24 horas de\ncorreção, o sódio sérico encontra-se em 146 mEq/L, os sinais clínicos de desidratação não mais\nexistem e reestabeleceu-se a diurese. Súbito, a criança apresenta convulsões. A provável causa do\nquadro convulsivo é?","options":{"A":"Hiperglicemia.","B":"Hipoglicemia.","C":"Meningoencefalite intercorrente.","D":"Edema cerebral.","E":"Hipocalcemia."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-51004","number":"51004","sourceNumber":"51004","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Maurício, 28 anos, é trazido inconsciente ao Pronto-Socorro pelo SAMU, que o\nresgatou de um banco de praça. O\nprofissional do SAMU entregou ao médico do Pronto-Socorro\numa seringa vazia encontrada nos pertences de Maurício. Ao exame, o paciente apresenta pupilas\nmióticas puntiformes bilateralmente. Os pulmões são limpos. O paciente não apresenta sudorese,\ndiarreia ou aumento dos ruídos hidroaéreos. A frequência respiratória é de 8 movimentos\nrespiratórios por minuto. A equipe do Pronto-Socorro informa ao médico plantonista que Maurício\ntambém é médico e sofre de dependência química. O que se observará mais provavelmente na\ngasometria?","options":{"A":"acidose metabólica.","B":"alcalose metabólica.","C":"pH arterial normal.","D":"acidose respiratória.","E":"alcalose respiratória."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-48827","number":"48827","sourceNumber":"48827","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Você está atendendo a uma criança cujo distúrbio hidreletrolítico foi classificado como\nhipernatremia hipovolêmica (desidratação do 2º grau, Na+ sérico = 168 mEq/L). Com 24h de\ncorreção, o Na+ sérico encontra-se em 146 mEq/L, os sinais clínicos de desidratação não mais\nexistem e restabeleceu-se a diurese. Subitamente, a criança apresenta convulsões. É mais\nprovável que estas sejam devido, inicialmente, à:","options":{"A":"Meningoencefalite intercorrente.","B":"Hemorragia intracraniana.","C":"Hipocalcemia.","D":"Hiperglicemia.","E":"Edema cerebral."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-33995","number":"33995","sourceNumber":"33995","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Uma vítima de acidente automobilístico é submetida a tratamento operatório por lesões\nabdominais e recebe dez unidades de concentrados de hemácias nas primeiras horas de\ninternação hospitalar. As complicações que podem resultar desta hemotransfusão maciça são as\nseguintes:","options":{"A":"hipotermia, alcalose metabólica, hipocalcemia, hipercalemia.","B":"hipertermia, acidose metabólica, hipercalemia, hipercalcemia.","C":"hipertermia, acidose respiratória, hipocalcemia, hipocalemia.","D":"hipotermia, alcalose respiratória, hipercalemia, hipercalcemia."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-27163","number":"27163","sourceNumber":"27163","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente, AMC, 65 anos, chega ao PS com quadro comatoso. Após avaliação da\nneurologia são solicitados exames\nlaboratoriais e de imagem. Rapidamente o laboratório comunica\nque o sódio plasmático é de 110. O plantonista, então, infunde solução hipertônica em grandes\nvolumes e elevado fluxo. A complicação mais grave, dentre as opções abaixo, de uma correção\nrápida da hiponatremia deste paciente, é:","options":{"A":"Edema cerebral.","B":"Infarto agudo do miocárdio.","C":"Síndrome de desmielinização osmótica.","D":"Edema agudo de pulmão.","E":"Hipertensão maligna."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-27166","number":"27166","sourceNumber":"27166","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente, LIS, 70 anos, apresenta desidratação aguda decorrente de vômitos\nincoercíveis. É solicitado exame gasométrico\npelo plantonista, observando-se distúrbio ácido-básico\ne eletrolítico. Qual das opções abaixo deve-se esperar no laudo da gasometria o seguinte\nresultado:","options":{"A":"Alcalose metabólica e hipocloremia","B":"Acidose metabólica e hiponatremia","C":"Acidose metabólica e hiperpotassemia","D":"Acidose respiratória e hipernatremia","E":"Alcalose respiratória e hipopotassemia"},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-23038","number":"23038","sourceNumber":"23038","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Uma adolescente de 14 anos, do sexo feminino, procura atendimento médico,\nacompanhada de sua mãe, devido à perda de peso\nexcessiva. A mãe relata que a adolescente\npermanecia longos períodos no banheiro para induzir vômitos. A adolescente confirma a história e\nrefere uso de laxante. Ciclo menstrual irregular com amenorreia há quatro meses. Exame físico:\npeso: 35 Kg (< p3), Estatura: 168 cm (p 90), IMC: 12,41 Kg/m2 (<p3), PA 100/70 mmHg, FC: 70\nbpm. Considerando a provável hipótese diagnóstica, o principal sinal de gravidade é a:","options":{"A":"hiponatremia.","B":"alcalose hiperclorêmica.","C":"acidose hipoclorêmica.","D":"hipopotassemia."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-18989","number":"18989","sourceNumber":"18989","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente M. Z. S., 55 anos, sexo masculino, procurou atendimento médico com queixa\nde desconforto abdominal, fadiga, perda de peso,\nsudorese e febrícula intermitente, com início há\naproximadamente seis meses e piora marcante nos últimos 20 dias. Ao exame clínico, foram\nobservadas palidez cutâneo-mucosa, discreta hepatomegalia e volumosa esplenomegalia. O\nhemograma evidenciou anemia moderada (9,0g/dl), normocítica e normocrômica, leucocitose\n(110.000/µl) com desvio à esquerda até mioloblasto, basofilia e eosinofilia, além de trombocitose\n(750.000/µl). O cariótipo mostrou translocação t(9:22). Qual o diagnóstico para esse paciente?","options":{"A":"Leucemia mielomonocítica crônica.","B":"Trombocitemia essencial.","C":"Mielofibrose com reação leucoeritroblástica.","D":"Leucemia mieloide crônica."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-250215","number":"250215","sourceNumber":"250215","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"O crioprecipitado contém todos os fatores de coagulação, EXCETO:","options":{"A":"Fator XIII.","B":"Fator de Von Willebrand.","C":"Fator IX.","D":"Fator VIII."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-176220","number":"176220","sourceNumber":"176220","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre a trombocitopenia induzida por heparina (TIH) é correto afirmar, EXCETO:","options":{"A":"Afeta em torno de 3% dos pacientes expostos à heparina não-fracionada e uma porcentagem\nmenor de pacientes expostos à heparina de\nbaixo peso molecular.","B":"Na apresentação típica, o quadro ocorre após um mínimo de 5 dias de exposição à heparina e\nocorre um declínio maior ou igual a 50% da contagem basal de plaquetas.","C":"Embora os casos sejam geralmente assintomáticos, tromboses arteriais e/ou venosas podem\nser detectadas na maioria dos pacientes até cerca\nde 30 dias após o diagnóstico.","D":"Quando se suspeita de TIH tipo II, deve-se imediatamente suspender a administração de\nheparina e substituí-la por um anticoagulante alternativo. Uma dessas alternativas atualmente\nestudadas é o Fondaparinux.","E":"A transfusão de plaquetas está indicada na maioria das vezes e deve ser iniciada de forma\nprofilática e\n\nprecoce, mesmo sem sangramento aparente e com plaquetas ainda acima de 50.000/mm3, pois\ngeralmente ocorre uma nova queda muito rápida nos dias subsequentes ao início do quadro."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-155297","number":"155297","sourceNumber":"155297","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente sexo feminino, 35 anos de idade, com diagnóstico de hepatopatia crônica\nconsequente à Síndrome de Budd-Chiari. Na\ninvestigação etiológica, a paciente pode ser portadora\nde uma das seguintes doenças subjacentes, EXCETO:","options":{"A":"Hemoglobinúria paroxística noturna.","B":"Deficiência de homocisteína.","C":"Policitemia vera.","D":"Mutação do fator V de Leiden.","E":"Neoplasia."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-105676","number":"105676","sourceNumber":"105676","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Analisando a seguinte gasometria arterial de um paciente em ventilação espontânea\nem ar ambiente, qual a causa menos provável da\n(s) alteração (ões) apresentada (s)? pH 7.47.\nPaCO2 43 mmHg. PaO2 90 mmHg. HCO3- 31 mEq/L.","options":{"A":"Uso de sonda nasogástrica em sifonagem com resíduo de 800 ml em 24h.","B":"Uso de diurético de alça sem indução de hipovolemia.","C":"Contração volumétrica após sudorese excessiva.","D":"Insuficiência adrenal primária crônica.","E":"Transfusão maciça."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-105716","number":"105716","sourceNumber":"105716","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente masculino, 57 anos, trazido ao pronto-socorro por rebaixamento do nível de\nconsciência. Familiares informam que há alguns dias ele tem apresentado náuseas, constipação e\nfraqueza muscular. Nas últimas 48h, evoluiu com confusão, estupor e coma. Referem ainda que ele\nperdeu muito peso nos últimos meses, teve episódio de hemoptise há 20 dias e é tabagista 30\nmaços/ano. Ao exame físico, o paciente está com Glasgow 6. Exames complementares mostram:\nECG com intervalo QT reduzido e uma grave alteração de um eletrólito. Após suporte de vida\ninicial, qual o melhor tratamento, para a alteração aguda mais provável deste paciente?","options":{"A":"Reposição venosa de potássio, preferencialmente não ultrapassando a velocidade de 20 mEq/h\ne a concentração de 40 mEq/L em veia\nperiférica.","B":"Hidratação vigorosa com salina isotônica 0,9%, podendo acrescentar furosemida após repleção\nvolêmica e diurese abundante.","C":"Infusão de solução salina hipertônica 3%, podendo acrescentar furosemida simultaneamente.","D":"Infusão de soro ao meio 0,45%, podendo acrescentar água potável por SNE.","E":"Reposição de gluconato de cálcio."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-105643","number":"105643","sourceNumber":"105643","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Mulher de 50 kg, com cefaleia e confusão mental, é trazida ao PS por familiares. Na\navaliação inicial, chama atenção um sódio sérico de 119 mEq/L. Há 5 dias, tinha recebido exames\nde rotina, com natremia normal. Calculando-se a reposição de sódio pela fórmula convencional, e\nrespeitando o limite máximo recomendado de subida do sódio para prevenção de síndrome de\ndesmielinização osmótica, a quantidade máxima de solução salina a 3% a ser ofertada para esta\npaciente nas próximas 24h, é:","options":{"A":"686 ml.","B":"1.254 ml.","C":"392 ml.","D":"490 ml.","E":"196 ml."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-80891","number":"80891","sourceNumber":"80891","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente 42 anos, hipertensa e diabética, faz uso de hidroclorotiazida, captopril e\nmetformina. Admitida com quadro de vômitos,\ndiarreia com muco e febre há 4 dias. Ao exame\nfísico, apresenta regular estado geral, desidratada, PA = 100 x 60 mmHg, FC = 100 bpm, FR = 28\nipm; abdome doloroso sem sinais de irritação peritoneal. Exames laboratoriais: Creatinina = 2,3\nmg/dl; Ureia = 132 mmol/ml; Potássio = 2,6 mmol/ml; Sódio = 130 mmol/ml; pH = 7,49; Bicarbonato\n(HCO3) = 26 mEq/L; PaCO2 = 46 mmHg, PO2 = 70 mmHg e SatO2 = 91%. As possíveis causas da\nhipocalemia são:","options":{"A":"Diarreia, diurético tiazídico e alcalose metabólica.","B":"Hipoxemia e insuficiência renal.","C":"Metformina, hiponatremia e perda de suco gástrico causado pelos vômitos.","D":"Hipoxemia, diurético tiazídico e captopril.","E":"Diarreia, metformina e uremia."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-80949","number":"80949","sourceNumber":"80949","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre distúrbios acidobásicos, é INCORRETO afirmar que:","options":{"A":"As acidoses metabólicas com Ânion-Gap (AG) normal têm entre as suas principais causas:\ndiarreia, acidose tubular renal tipo I, II e IV, intoxicação por metanol e paraldeído.","B":"Nosso organismo dispõe de múltiplas linhas de defesa contra sobrecargas ácidas, como o\ntamponamento extracelular pelo bicarbonato, o tamponamento respiratório.","C":"Pela excreção aumentada de CO2 e o tamponamento ósseo e intracelular, assim como o\naumento na excreção renal de hidrogênio.","D":"A acidose metabólica é um distúrbio do equilíbrio acidobásico muito frequente em pacientes\ngravemente enfermos internados em unidades de terapia intensiva, sendo que o principal tipo de\nacidose metabólica encontrada nestes pacientes é a acidose lática secundária ao choque\ncirculatório.","E":"Riscos do tratamento com bicarbonato: hipernatremia, hiperosmolaridade, sobrecarga de\nvolume, hipercapnia e acidose intracelular, maior afinidade da Hb pelo O2, estímulo a enzimas\nglicolíticas, queda no cálcio ionizado e alcalose de rebote."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-80855","number":"80855","sourceNumber":"80855","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Assinale a alternativa que apresenta o diagnóstico compatível com o seguinte quadro:\nhiponatremia com sódio corporal normal, hematócrito normal, sódio urinário > 20 mEq/L e\nosmolaridade urinária hipertônica.","options":{"A":"Síndrome da secreção inapropriada de hormônio antidiurético.","B":"Síndrome perdedora de sal.","C":"Cirrose.","D":"Insuficiência cardíaca.","E":"Tubulopatia."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-62571","number":"62571","sourceNumber":"62571","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paralisia flácida, hiporreflexia, hipercapnia, tetania e rabdomiólise podem ocorrer em\ncasos de:","options":{"A":"Hipercalemia;","B":"Hipercalcemia;","C":"Hipocalcemia;","D":"Hipofosfatemia;","E":"Hipocalemia."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-62595","number":"62595","sourceNumber":"62595","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Mulher, 29 anos, iniciou quadro de confusão mental e equimoses há 3 dias, com\ndiminuição do volume urinário. Ao exame,\napresenta-se em regular estado geral; sonolenta;\npressão arterial = 120 x 80 mmHg; pulso = 80 bpm; frequência respiratória = 18 irpm. Equimoses\nem MMSS e MMII. Hemoglobina = 6,5 g/dl; VCM = 100 fl; reticulócitos = 28%; 12.000\nleucócitos/mm³; 80 bastões/mm³ (6,7%); 9.000 neutrófilos/mm³; 1.800 linfócitos/mm³; 65.000\nplaquetas/mm³. Esfregaço de sangue demonstra fragmentação das hemácias e policromasia. Qual\né a conduta terapêutica indicada?","options":{"A":"Plasmaférese.","B":"Esplenectomia.","C":"Ciclosporina.","D":"Transfusão de plaquetas.","E":"Pulsoterapia com ciclofosfamida."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-35778","number":"35778","sourceNumber":"35778","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Desidratação caracterizada por sede intensa, mucosas muito secas, oligúria acentuada,\nfebre, crise convulsiva, opistótono,\nhiper-reflexia:","options":{"A":"Hipotônica.","B":"Hipertônica.","C":"Isonatônica.","D":"Hiponatrêmica.","E":"Isonatrêmica."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-281461","number":"281461","sourceNumber":"281461","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"A chance de adquirir HIV em uma transfusão de fator VIII nos EUA é zero, pela\nseguinte justificativa:","options":{"A":"Todos os doadores do fator VIII são rastreados.","B":"O fator VIII é submetida ao processo de \"\"purging\"\" a laser antes da liberação.","C":"O fator VIII é produzido sinteticamente.","D":"O fator VII é produzido sob demanda.","E":"O fator VIII é importado nos EUA."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-184835","number":"184835","sourceNumber":"184835","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente, 30 anos do sexo feminino, com história há 1semana de febre diária, Tax 38,5\na 39,0°C.mal estar, cefaleia, confusão mental e\nhemiparesia a direita. Petéquias nos membros\ninferiores. Foi internada para investigação. No tercceiro dia de internação o quadro se agravou com\nepisódios de convulsão, oligúria, sedimento urinário com hematúria/proteinúria, ureia de 110 mg/dl,\ncreatinina de 1,9mg/dl, anemia: Hb 7,0 g/dl e Htc 25%, plaquetas 60.000 cel/mm³, aumento de\nbilirrubina indireta; Coombs direto negativo. Foi solicitado avaliação da hematologia, que observou\na presença de hemácias descritas como \"esquizócitos no sangue periférico\"da paciente. Qual a\nhipótese diagnóstica mais provável para a situação clínica acima apresentada?","options":{"A":"Dengue hemorrágica","B":"Síndrome hemolítica urêmica","C":"Síndrome hemofagocítica","D":"Síndrome antifosfolipides","E":"Púrpura trombocitopênica trombótica"},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-160427","number":"160427","sourceNumber":"160427","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Define-se por reação transfusional qualquer intercorrência originada como\nconsequência da transfusão de\nhemocomponentes, durante ou após sua administração. Esses\neventos adversos podem variar de anafilaxia leve a quadros de hepatite grave, sepse e morte. A\nliteratura indica que a prevalência de reações transfusionais em crianças é elevada, e os fatores\nintervenientes são o tipo de hemocomponente, a faixa etária, comorbidade do peciente e\npolitransfusão, sendo que os dois primeiros associam-se, também, com tipo de reação ocorrida. O\nperfil das reações transfusionais costuma ser de eventos:","options":{"A":"De etiologia desconhecida; devido a sangue total.","B":"Alérgicos; devido a sangue total.","C":"De etiologia desconhecida; devido a concentrado de plaquetas.","D":"Alérgicos; devido a concentrado de plaquetas.","E":"Graves; devido a concentrado de hemácias."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-103893","number":"103893","sourceNumber":"103893","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Hipercalemia aguda está associada a qual das seguintes alterações\neletrocardiográficas?","options":{"A":"Prolongamento do segmento ST.","B":"Diminuição do intervalo PR.","C":"Alargamento do QRS.","D":"Onda U proeminente.","E":"Achatamento da onda T."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-89236","number":"89236","sourceNumber":"89236","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Constitui causa de acidose metabólica com Anion gap normal:","options":{"A":"Acidose lática","B":"Cetoacidose diabética","C":"Uremia","D":"Intoxicação por salicilato","E":"Diarreia"},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-87490","number":"87490","sourceNumber":"87490","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente do sexo feminino, 64 anos, hipertensa e coronariopata, abriu quadro de dor\nabdominal moderada há 3 dias. Hoje pela manhã notou pronunciada piora da dor abdominal, iniciou\nsubitamente uma dor descrita como insuportável em primeiro pododáctilo esquerdo e começou a\napresentar vômitos recorrentes, cefaléia e confusão mental. Acompanhante comenta ainda não ter\nobservado exteriorização de diurese pela paciente hoje. Informa que há 11 dias foi submetida a\numa cineangiocoronariografia (caracterização femoral esquerda), com colocação de stent\n\nnão-farmacológico em 1/3 proximal da A. descendente anterior, e vinha evoluindo sem precordialgia\ndesde então. Faz uso de AAS 100mg/d,\nClopidogrel 75mg/d (este último recém-iniciado após o\nprocedimento descrito), Losartana 100mg/d, Atenolol 50mg/d e Atorvastatina 80mg/d. Exame físico\nrevela uma paciente corada, com edema bipalpebral e de MMII, acianótica, com FR de 24irpm, sem\nesforço. A PA é de 170 x100mmHg, FC de 68 bpm. Observam-se ainda pulmões limpos, e ausculta\ncardíaca com B4, sem sopros. Pulsos pediosos palpáveis. Perfusão capilar periférica lentificada em\nprimeiro pododáctilo esquerdo. Laboratório de entrada: Hb: 13,6; 13.800 leucócitos, sendo 74%\nPMN e 10% de eosinófilos, sem desvio à esquerda; 162.000 plaquetas; Na: 135meq/L; K: 6,6meq/L\nCreatinina: 3,1MG/dl; U: 96mg/dl; Gli:120mg/dl; amilase elevada. Troponina I normal; CK total\n(300U/L); CK-MB normal; EAS com cilindros granulosos e piúria. ECG: sobrecarga volumétrica do\nVE, apenas. RX tórax: hilos pulmonares ingurgitados, área cardíaca normal. Pergunta-se: Referente\nà hipercalemia, no caso em questão, a primeira medida a ser tomada é:","options":{"A":"Glicoinsulinoterapia IV;","B":"Gluconato de cálcio IV;","C":"Furosemida IV;","D":"Hemodiálise;","E":"Resina de troca VO."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-87535","number":"87535","sourceNumber":"87535","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Em relação aos distúrbios eletrolíticos. É correto afirmar?","options":{"A":"Secreção inapropriada de HAD e hipotireoidismo são causas de hiponatremia com sódio\ncorpóreo total normal;","B":"Hiponatremia é definida como concentração sérica de sódio menor que 135 mEq/l;","C":"A hipercalemia com níveis séricos acima de 8 mEq/l deve ser tratada apenas com a suspensão\nde toda administração de potássio;","D":"Em crianças, o hipoparatireoidismo primário é uma das principais causas de hipercalcemia;","E":"A hipermagnesemia ocorre comumente em paciente com função renal normal."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-87549","number":"87549","sourceNumber":"87549","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Lactente de 6 meses de idade, nascido pré-termo e evoluindo com broncodisplasia\npulmonar é admitido no pronto-socorro\npediátrico com quadro de pneumonia. Não é dependente de\noxigênio. Faz uso prolongado de hidroclorotiazida e espironolactona. Na avaliação laboratorial,\napresenta seguinte gasometria arterial: pH 7,34; PO2 54 mmHg; PCO2 85 mmHg; (HCO3) 44\nmEq/L; Base excess 14; SATO2 90%. Qual o distúrbio ácido básico?","options":{"A":"Acidose respiratória crônica com alcalose metabólica;","B":"Acidose respiratória aguda descompensada;","C":"Acidose respiratória crônica compensada;","D":"Alcalose metabólica descompensada;","E":"Acidose metabólica aguda com alcalose respiratória."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-65565","number":"65565","sourceNumber":"65565","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Na resposta endocrinometabólica ao trauma cirúrgico, o principal estímulo à secreção\ndo ADH é:","options":{"A":"Analgesia inadequada;","B":"Hemorragia;","C":"Osmolaridade plasmática;","D":"Redução da aldosterona;","E":"Aumento da angiotensina."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-65566","number":"65566","sourceNumber":"65566","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Qual o valor esperado de PaCO2 num paciente com ACIDOSE METABÓLICA que\napresenta HCO3 de 10 mEq/L?","options":{"A":"Entre 15 - 20;","B":"Entre 20 - 25;","C":"Entre 25 - 30;","D":"Maior que 30;","E":"Menor que 15."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-52223","number":"52223","sourceNumber":"52223","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Qual tratamento para correção do distúrbio acidobásico em um paciente que apresenta\nfístula digestiva de alto débito decorrente de\numa anastomose pancreatojejunal?","options":{"A":"Solução isotônica de cloreto de sódio.","B":"Solução de bicarbonato.","C":"Solução hipertônica de glicose a 50%.","D":"Solução hipertônica de cloreto de sódio.","E":"Reposição vigorosa de cloreto de potássio."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-308310","number":"308310","sourceNumber":"308310","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Mulher de 26 anos deu entrada no pronto atendimento, relatando manchas roxas há 3\ndias de aparecimento espontâneo. Ao exame físico: petéquias e equimoses em membros inferiores.\nNega uso de medicações. Foram realizados exames laboratoriais iniciais: hemoglobina: 12,2 g/dl;\nmorfologia de série eritrocitária: sem alterações; leucócitos 5.600/mm³ (diferencial normal);\nplaquetas: 4.000/mm³. Não há comorbidades e o restante da investigação laboratorial foi normal.\n\nQual o diagnóstico e a conduta?","options":{"A":"Trombocitopenia primária imune; prednisona.","B":"Púrpura trombocitopênica trombótica; transfusão de plaquetas.","C":"Trombocitopenia primária imune; transfusão de plaquetas.","D":"Púrpura trombocitopênica trombótica; plasmaférese."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-244784","number":"244784","sourceNumber":"244784","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Uma jovem de 20 anos cehga ao pronto-socorro para avaliação de um rash nos\nmembros inferiores. Na semana anterior,\napresentou epstaxe, com duração de 2 horas. No dia\nanterior, teve um 2º episódio de epistaxe e notou hematomas esparsos. Ao exame físico, foram\nencontrados equimoses e petéquias nos membros, VCN =89fL, leucócitos normais e plaquetas =\n17.000/mL. Qual é o tratamento inicial indicado para o caso?","options":{"A":"Transfusão de plaquetas imediata","B":"Imunoglobulina intravenosa","C":"Observação e seguimento no dia seguinte","D":"Prednisona","E":"Anti-histamínicos"},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-221326","number":"221326","sourceNumber":"221326","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Nas alternativas a seguir, assinale a que NÃO representa uma abordagem correta\nfrente a uma criança com plaquetopenia.","options":{"A":"Assim que diagnosticada a PTI, deve-se iniciar transfusão de plaquetas a cada 4 horas.","B":"História clínica, exame físico e exame de hemograma interpretado corretamente permitem\nrealizar o diagnóstico diferencial das plaquetopenias da infância na maior parte dos casos.","C":"A Púrpura Trombocitopênica Idiopática (PTI) recentemente diagnosticada é, geralmente,\nprecedida por infecções virais.","D":"Exames complementares, tais como dosagem de anticorpo contra plaquetas, podem auxiliar na\nconfirmação diagnóstica em alguns casos, mas podem ser falsamente negativos em uma parcela\ndos pacientes pediátricos."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-136963","number":"136963","sourceNumber":"136963","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente desidratada grave, com 13 kg de peso, apresenta a seguinte gasometria: pH =\n7,34, pCO? = 28, pO? = 90, HCO? = 20, BE = - 2. Qual deve ser a composição do soro a ser\nprescrito?","options":{"A":"260 mL de bicarbonato de sódio a 8,4% na 1ª hora da fase de expansão.","B":"260 mL de soro fisiológico a 0,9% como fase de expansão.","C":"130 mL de soro glicosado 5%+130 mL de bicarbonato de sódio a 8,4% na 1ª hora da fase de\nexpansão.","D":"200 mL de soro glicosado 5%+60 mL de soro fisiológico 0,9% na 1ª hora da fase de expansão."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-85034","number":"85034","sourceNumber":"85034","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre equilíbrio ácido-básico, enumere a coluna da direita de acordo com a da\nesquerda. 1 - Acidose metabólica; 2 -\nAlcalose metabólica; 3 - Acidose respiratória; 4 - Alcalose\nrespiratória; ( ) pH < 7,35; pCO2 > 45 mmHg. ( ) pH > 7,45; Bicarbonato > 26 mEq/L. ( ) pH > 7,45;\npCO2 < 35 mmHg. ( ) pH < 7,35; Bicarbonato < 22 mEq/L. Marque a sequência correta.","options":{"A":"1, 4, 2, 3.","B":"3, 2, 1, 4.","C":"3, 2, 4, 1.","D":"4, 1, 3, 2."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-75383","number":"75383","sourceNumber":"75383","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Das hemopatias, qual NÃO apresenta manifestações articulares em sua evolução\nclínica?","options":{"A":"Mieloma múltiplo.","B":"Leucose.","C":"Púrpura trombocitopênica idiopática.","D":"Linfoadenopatia angioimunoblástica."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-330638","number":"330638","sourceNumber":"330638","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Fondaparinux é pentassacarídeo sintético, que:","options":{"A":"se liga seletivamente à trombina leva à inibição do fator Xa. Devido à sua discreta interação com\ncomponentes do plasma, não possui ação anticoagulante previsível e pouca variabilidade\nindividual.","B":"se liga seletivamente à trombina leva à inibição do fator Xa. Devido à sua discreta interação com\ncomponentes do plasma, possui ação anticoagulante imprevisível e pouca variabilidade individual.","C":"se liga não seletivamente à trombina leva à inibição do fator Xa. Devido à sua discreta interação\ncom componentes do plasma, possui ação\nanticoagulante previsível e pouca variabilidade\nindividual.","D":"se liga seletivamente à trombina leva à inibição do fator Xa. Devido à sua discreta interação com\ncomponentes do plasma, possui ação anticoagulante previsível e pouca variabilidade individual."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-332992","number":"332992","sourceNumber":"332992","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 30 anos, previamente hígida, nota aparecimento de petéquias em\nmembros inferiores nas últimas 2 semanas, sem\nqualquer outra queixa. O exame físico é normal e\no hemograma mostra apenas plaquetopenia, com 30 mil plaquetas/mm3, sem alterações na série\nvermelha ou nos leucócitos. Sobre esse quadro clínico, é correto afirmar:","options":{"A":"Diante do alto risco de sangramento grave, a paciente tem indicação de internamento para\ntransfusão de concentrado de plaquetas.","B":"A principal hipótese diagnóstica é de púrpura trombocitopênica imune (PTI), sendo corroborada\npor achado de esplenomegalia e biópsia de medula\nóssea mostrando baixa contagem de\nmegacariócitos.","C":"Frente à hipótese diagnóstica é de púrpura trombocitopênica imune (PTI), está indicada a\npesquisa de infecção pelo HIV, por ser potencial causa de plaquetopenia.","D":"Está indicada a internação hospitalar para transfusão de concentrado de hemácias e\nesplenectomia no mesmo internamento, já que,\nnessa condição, a destruição das plaquetas ocorre\nno baço."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-221291","number":"221291","sourceNumber":"221291","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Ticagrelor é um novo fármaco antagonista reversível do receptor não tienopiridínico\nP2Y12, sendo adequado o seguinte ao seu\n\nrespeito:","options":{"A":"Necessita de processo de conversão metabólica para um componente ativo","B":"Não necessita de processo de conversão metabólica para um componente inativo.","C":"Não necessita de processo de conversão metabólica para um componente ativo.","D":"Não necessita de processo de desconversão metabólica para um componente ativo."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-221318","number":"221318","sourceNumber":"221318","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Nas alternativas abaixo, assinale a que NÃO representa uma abordagem correta frente\na uma criança com plaquetopenia.","options":{"A":"Assim que diagnosticado a PTI, deve-se iniciar transfusão de plaquetas a cada 4 horas.","B":"História clínica, exame físico e exame de hemograma interpretado corretamente permitem\nrealizar o diagnóstico diferencial das\n\nplaquetopenias da infância na maior parte dos casos.","C":"A púrpura trombocitopênica idiopática (PTI) recentemente diagnosticada é, geralmente,\nprecedida por infecções virais.","D":"Exames complementares, tais como dosagem de anticorpo contra plaquetas podem auxiliar na\nconfirmação diagnóstica em\n\nalguns casos, mas podem ser falsamente negativos em uma parcela dos pacientes pediátricos."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-216865","number":"216865","sourceNumber":"216865","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"A hemorragia digestiva é rara em crianças, mas é um tema de grande importância por\nse tratar muitas vezes de uma emergência além\nde causar uma apreensão à família. As causas são\ndiversas e a sistematização com a epidemiologia por idade, facilita na investigação diagnóstica.\n\nUma das causas mais comuns de hemorragia digestiva baixa na faixa etária entre 0 a 30 dias é:","options":{"A":"Síndrome hemolítico-urêmica.","B":"Doença inflamatória intestinal.","C":"Coagulopatia por deficiência vitamínica.","D":"Divertículo de Meckel."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-183410","number":"183410","sourceNumber":"183410","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Quanto à terapia transfusional, assinale a alternativa CORRETA.","options":{"A":"É considerado um sangramento excessivo quando a perda ultrapassar 50 ml/hora em 4 horas.","B":"Uma unidade de sangue total contém 1.000 ml de sangue com anticoagulante.","C":"O plasma fresco descongelado é utilizado como expansor volumétrico.","D":"A administração de 250 ml de concentrado de hemácias causa aumento de 1 g/dl de\nhemoglobina.","E":"A transfusão plaquetária está indicada na trombocitopenia induzida por heparina."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-156296","number":"156296","sourceNumber":"156296","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 4 anos, sexo masculino, com diagnóstico de Púrpura Trombocitopênica\nImunológica (PTI) há 5 meses. Realizado\nmielograma, ao diagnóstico, sem alterações. No\nmomento, a criança está bem, sem sangramentos, porém com contagem plaquetária de 22000 e\nséries eritrocitária e leucocitária normais. Quais classificação e tratamento devem ser determinados\npara esse paciente?","options":{"A":"PTI aguda. Tratamento conservador com observação criteriosa e sem uso de medicamentos\npara aumentar o número de plaquetas.","B":"PTI aguda. Tratamento com imunoglobulina.","C":"PTI persistente. Tratamento com imunoglobulina.","D":"PTI persistente. Tratamento conservador com observação criteriosa e sem uso de\nmedicamentos para aumentar o número de plaquetas.","E":"PTI crônica. Tratamento conservador com observação criteriosa e sem uso de medicamentos\npara aumentar o número de plaquetas"},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-156305","number":"156305","sourceNumber":"156305","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Considerando que PTI é um diagnóstico de exclusão para trombocitopenia, qual dos\nitens a seguir não é considerado causa plaquetopenia?","options":{"A":"Infecção por Helicobacter pylori.","B":"Infecção por Epstein-Barr.","C":"Síndrome do anticorpo antifosfolípide.","D":"Deficiência de tiamina.","E":"Hiperesplenismo."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-140357","number":"140357","sourceNumber":"140357","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Em relação a coagulação sanguínea, marque a alternativa CORRETA:","options":{"A":"Todos os fatores de coagulação são produzidos pelo fígado","B":"Todos os fatores de coagulação são dependentes de vitamina k para serem sintetizados","C":"A terapia com cumarínicos pode ser avaliada dosando-se o tempo de protrombina, que deve\nestar entre 1-2","D":"A heparina utilizada em soluções de lavagem de cateter é suficiente para causar\ntrombocitopenia","E":"Nenhuma das anteriores"},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-132270","number":"132270","sourceNumber":"132270","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"É causa de hiponatremia normovolêmica:","options":{"A":"Uremia.","B":"Síndrome da secreção inapropriada do ADH.","C":"Pancreatite.","D":"Insuficiência Cardíaca."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-111776","number":"111776","sourceNumber":"111776","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Homem, 55 anos de idade, peso corporal = 70 kg. Antecedente de Acidente Vascular\nCerebral (AVC) fronto-temporo-parietal à direita, trazido ao pronto-atendimento por seu filho com\nrelato de sonolência insidiosa há 2 semanas. Sem outras queixas. Ao exame físico: hemiparesia\nfascio-braquio-crural sem piora do déficit motor, sem outras alterações. Exames Laboratoriais: Na\nsérico = 118 mEq/L, Creatinina = 1,9 mg/dl; Ureia = 194 mg/dl; demais exames laboratoriais\nnormais. Considerando o caso acima e a margem de segurança para o não desenvolvimento de\ncomplicações, assinale a alternativa que contém a variação máxima de correção sódio sérico em\nmEq em 24 horas:","options":{"A":"12-14 mEq/L.","B":"14-16 mEq/L.","C":"4-6 mEq/L.","D":"10-12 mEq/L.","E":"6-8 mEq/L."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-107725","number":"107725","sourceNumber":"107725","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente AP, 50 anos, SIDA, internado com quadro de leishmaniose visceral, em\ntratamento com Anfotericina B, com quadro de hipocalemia refratária à reposição endovenosa.\nEncontra-se clinicamente estável, afebril, sem náuseas, vômitos ou diarreia. Qual das condutas a\nseguir deverá ser instituída imediatamente, visto que o paciente apresenta os seguintes exames:\nCreatinina 0,5 mg/dl; Ureia: 23 mg/dl; Sódio 142 mEq/dl; potássio: 3,0 mEq/dl; Hb:10; Ht:31.","options":{"A":"Troca do esquema anti-retroviral.","B":"Dosagem de magnésio.","C":"Suspensão da anfotericina.","D":"Acesso central e aumentar a concentração de potássio na reposição.","E":"Diurético de alça."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-107788","number":"107788","sourceNumber":"107788","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"G.T., 67 anos, sexo masculino, previamente HAS, interna com quadro de pielonefrite,\nevoluindo com choque séptico, com necessidade de IOT e doses altas de drogas vasoativas.\n\nGasometria arterial com os seguintes parâmetros: pH: 7,25; HCO3: 12; PaO2:70; PaCO2: 32;\nBE-10, em FiO2 de 0,4. Qual dos seguintes distúrbios acidobásicos é encontrado?","options":{"A":"Acidose metabólica com alcalose respiratória.","B":"Acidose metabólica pura.","C":"Acidose metabólica com acidose respiratória.","D":"Alcalose metabólica com acidose respiratória.","E":"Alcalose respiratória com acidose metabólica."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-106968","number":"106968","sourceNumber":"106968","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Alterações graves do equilíbrio eletrolítico são potencialmente ameaçadoras da vida,\nsendo muito comum o encontro, nessa situação, de alterações da concentração do potássio,\ndosado a nível sérico.Todas as alternativas abaixo são adequadas, EXCETO uma. Assinale-a.","options":{"A":"O principal determinante da gravidade é a velocidade da variação do potássio sérico.","B":"A maioria do potássio corporal é intracelular.","C":"Beta-2-agonista, diminui hipercalemia.","D":"A variação do pH para a acidêmia aumenta o potássio corporal."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-106810","number":"106810","sourceNumber":"106810","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre a interpretação de gasometria arterial, assinale a opção CORRETA:","options":{"A":"pCO2 reduzida e pO2 elevada = hiperventilação = alcalose metabólica.","B":"pCO2 elevada e pO2 reduzida = hipoventilação = alcalose respiratória.","C":"pCO2 elevada e pO2 reduzida = hipoventilação = acidose respiratória.","D":"HCO3 reduzido e BE < -3,5 = alcalose metabólica.","E":"HCO3 elevado e BE > +3,5 = acidose metabólica."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-83533","number":"83533","sourceNumber":"83533","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"JSX, 73 ANOS, HAS prévia, deu entrada na emergência do Hospital com quadro de\nedema de membros inferiores, astenia,\nanorexia nos últimos 3 meses, evoluindo com tontura,\ndispneia, sensação de morte iminente há alguns minutos. Ao exame físico inicial, paciente\nencontra-se pálido ++/4+, desorientado, bradicárdico ( FC: 50 bpm), MV diminuído em bases,\ntaquidispneia (FR:35 irpm), abdômen inocente e membros inferiores com edema ++/4+. Solicitados\nexames iniciais: Hb: 6,2; Ht 19; VCM: 89,2; HCM: 29,1; CHCM: 32,63, Leucócitos: 6100 (sem\ndesvio), Plaqueta 139.000; creatinina 8,2mg/dl; Ureia: 264mg/dl; Sódio: 138mEq/l; Potássio:\n8,5mEq/l; Glicemia: 82mg/dl HCO3: 11,2; ECG: ( VER IMAGEM) Qual a medida inicial a ser\ntomada:","options":{"A":"Hemodiálise de urgência.","B":"Administração de gluconato de cálcio.","C":"Solução polarizante ( glicose hipertônica + insulina regular).","D":"Trombolítico.","E":"Marcapasso provisório."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-19/83533.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-60180","number":"60180","sourceNumber":"60180","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"As alcaloses, respiratórias ou metabólicas, na presença de acidúria paradoxal, só são\ncorrigidas quando, além do tratamento da depleção de espaço extracelular, corrigi-se também, e\nprincipalmente a:","options":{"A":"Hipopotassemia.","B":"Hiperpotassemia.","C":"Hipercloremia.","D":"Hipernatremia","E":"Hiponatremia."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-45957","number":"45957","sourceNumber":"45957","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Acidose respiratória consiste na elevação da PaCO2. Em relação a esta situação\npodemos afirmar:","options":{"A":"É uma condição complicada no seu manejo clínico especialmente por ser sempre assintomática\ne pode ser decorrente de hiperventilação nos\npacientes submetidos à ventilação mecânica.","B":"Pode causar sonolência e dentre suas causas prováveis podem ser citadas: DPOC, depressão\ndo centro respiratório e doenças\nneuromusculares.","C":"Não leva a nenhuma manifestação clínica, apesar de poder estar relacionadas a várias causas\nimportantes, como DPOC, depressão do centro respiratório e doenças neuromusculares.","D":"Sua principal manifestação clínica é o esforço respiratório e sua causa é sempre relacionada à\nDPOC.","E":"Pode causar sonolência e dentre suas principais causas prováveis podem ser citadas: hipoxemia\ne ventilação mecânica excessiva."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-45958","number":"45958","sourceNumber":"45958","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Alcalose respiratória consiste na redução da PaCO2. Em relação a esta situação\npodemos afirmar:","options":{"A":"É uma condição que se caracteriza por se mostrar sempre assintomática e pode ser decorrente\nde hiperventilação nos pacientes submetidos à\nventilação mecânica.","B":"Pode causar tetania, vertigem, síncope, irritabilidade e ansiedade, podendo estar relacionada a\ncausas como: DPOC e Síndrome de Guillain-Barré.","C":"Pode causar tetania, vertigem, síncope, irritabilidade e ansiedade, podendo estar relacionada a\ncausas como: hipoxemia, distúrbios de ansiedade e falência hepática.","D":"Sua principal manifestação clínica é sonolência e sua causa é sempre relacionada à DPOC.","E":"Pode causar sonolência e dentre suas principais causas prováveis podem ser citadas: lesão\nmedular e a Síndrome do Desconforto Respiratório Agudo."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-45451","number":"45451","sourceNumber":"45451","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Assinale a alternativa correta.","options":{"A":"Hiponatremia se refere a Déficit do Espaço Extracelular.","B":"Hipernatremia reflete um distúrbio da água.","C":"Concentrações séricas de potássio não interferem na osmolaridade plasmática.","D":"Concentrações séricas de ureia e glicemia não interferem na osmolaridade plasmática.","E":"Nenhuma das anteriores."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-34548","number":"34548","sourceNumber":"34548","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente admitido na sala de emergência de Hospital Regional com taquidispneia. O\nresidente da Clínica Médica que estava no plantão, colhe uma gasometria arterial: pH 7,35; PCO2\n40; PO2 65; SO2 92% e HCO3 21. A interpretação é:","options":{"A":"Alcalose metabólica não compensada.","B":"Acidose respiratória não compensada.","C":"Acidose respiratória compensada.","D":"Acidose mista.","E":"Alcalose metabólica compensada."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-255908","number":"255908","sourceNumber":"255908","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Mulher de 67 anos vai ao pronto atendimento queixando-se de tosse seca e dispneia há\n7 dias, que evoluiu com piora progressiva e\nocorre mesmo em repouso no momento. Nega febre,\ndor torácica, ortopneia ou sintomas de aéreas superiores. É portadora de câncer de mama e está\nrealizando quimioterapia. Ao exame físico, apresente PA = 120/80 mmHg, FC = 89 bpm, FR = 26\nirpm, SpO2 em ar ambiente 80%. Encontra-se alerta e orientada. O exame respiratório revela\ntaquipneia e esforço respiratório; a ausculta não apresenta anormalidades. O exame cardiovasular\nrevela ictus cordis no 4° espaço intercostal esquerdo e linha hemiclavicular, ritmo cardíaco\nregular,\nsem anormalidades; pulso venoso jugular interno direito visualizado a 2 cm do esterno, sem refluxo\nhepatojugular. Restante do exame físico sem anormalidades. Exames de laboratório: Hb = 12,9\ng/dl; LG = 5.600/mm³; NS = 3.450/mm³; Plq = 210.000/mm³; LDH = 1.200 U/L; PCR = 80 mg/L;\nCreat. = 1,2 mg/dl. TC tórax: infiltrado em vidro fosco e espessamento septal intralobular e\ninterlobular, constituindo padrão de pavimentação em mosaico, difusamente encontrado em ambos\nos campos pulmonares de distribuição peri-hilar predominante. Três dias após o início do\ntratamento empírico mais adequado, a paciente queixou-se de fraqueza generalizada e parestesia\nnas mãos e nos pés. O eletrocardiograma pode ser visto a seguir. Assinale a alternativa que\napresenta a causa MAIS PROVÁVEL para o quadro clínico apresentado pela paciente nesse\nmomento.","options":{"A":"Cardiotoxicidade por quimioterápicos","B":"Hipercalcemia","C":"Hiperpotassemia","D":"Neuropatia por quimioterápicos"},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-19/255908.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-255926","number":"255926","sourceNumber":"255926","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 53 anos, sexo feminino foi submetida a enterectomia devido à presença de\nbridas. No pós operatório imediato evoluiu com distensão abdominal e vômitos de repetição. Foi\nsolicitada gasometria arterial que apresentou: pH= 7,55; PaCO?= 43 mmHg; Bicarbonato=\n28mEq/L; BE= +5,0. A partir da gasometria do paciente, é CORRETO afirmar que o distúrbio\n\nácido-base encontrado é:","options":{"A":"Alcalose metabólica","B":"Alcalose metabólica e acidose respiratória","C":"Alcalose mista","D":"Alcalose respiratória"},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-203275","number":"203275","sourceNumber":"203275","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Homem de 44 anos foi admitido em CTI com choque séptico que teve como foco lesão\ntraumática infectada extensa em membro inferior direito. Algumas horas após a admissão, foram\nobservadas petéquias, equimoses, sangramento no sítio de inserção de cateter venoso central e\ngengivorragia. O plantonista solicitou hemograma e coagulograma para avaliação inicial. À\nhematoscopia, foram observados numerosos esquizócitos. Dentre as opções a seguir, qual é o\ndiagnóstico MAIS PROVÁVEL e como devem estar o Tempo de Protrombina (TP), o Tempo Parcial\nde Tromboplastina ativado (PTTa) e contagem de plaquetas?","options":{"A":"Coagulação intravascular disseminada, TP e PTTa prolongados e trombocitopenia.","B":"Deficiência prévia de fator de coagulação e infecção aguda, TP e PTTa prolongados e\ntrombocitose.","C":"Púrpura trombocitopênica trombótica, TP normal, PTTa prolongado e trombocitopenia.","D":"Uso prévio de warfarin e infecção aguda, TP prolongado, PTTa normal e trombocitopenia."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-174750","number":"174750","sourceNumber":"174750","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"A propósito das intoxicações exógenas, assinale a alternativa ERRADA:","options":{"A":"A hipertermia, eventualmente fatal, pode ser observada na intoxicação por anfetaminas, em\nespecial na intoxicação pela 3,4-metilenodioximetanfetamina (ecstasy).","B":"A meta-hemoglobinemia, passível de ser causada por drogas como a dapsona e o nitrobenzeno,\npode ser tratada com o azul de metileno, que\nfavorece a conversão da meta-hemoglobina em\nhemoglobina, na medida em que aumenta a atividade da meta-hemoglobina redutase.","C":"A n-acetilcisteína está indicada na intoxicação pelo paracetamol, sendo mais efetiva quando\nadministrada até 8 a 10 horas após a ingestão do analgésico.","D":"A vitamina K reverte a ação dos anticoagulantes, em especial dos novos agentes disponíveis por\nvia oral como a dabigatrana, a rivaroxabana e a apixabana."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-174772","number":"174772","sourceNumber":"174772","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Mulher de 34 anos passou a apresentar nas últimas seis semanas equimoses\nespontâneas principalmente nas pernas. Informa\ntambém sangramento excessivo na última\nmenstruação e episódio de epistaxe volumosa há cinco dias. Diz que está se sentindo bem e\ncontinua trabalhando normalmente. Sem passado mórbido de importância. Não há história familiar\nde doença hemorrágica. Não é tabagista e ingere bebida alcoólica apenas socialmente. Nega uso\natual e recente de qualquer medicamento. Ao exame, observam-se múltiplas equimoses nas suas\npernas e, em menor número, no abdome e braços. Há sangramento espontâneo nas gengivas. O\nexame de fundo de olho não evidencia hemorragias. Os dados vitais e o restante do exame físico\nestão dentro dos limites da normalidade. Hemoglobina = 12,9 g/dl (hematoscopia sem achados\ndignos de nota); leucócitos totais = 5.300/mm³ (contagem diferencial dentro da normalidade);\nplaquetas = 5.000/mm³; e RNI; PTT; função renal; íons; glicemia e bioquímica hepática dentro dos\nlimites da normalidade. Fator Antinuclear (FAN); anti-HIV e anti-HCV (vírus da hepatite C)\nnegativos. Considerando-se o diagnóstico mais provável, é possível afirmar que a plaquetopenia\napresentada pela paciente é resultante de:","options":{"A":"Consumo excessivo de plaquetas.","B":"Destruição de plaquetas por autoanticorpos e possível inibição da produção/liberação dessas\ncélulas pelos megacariócitos.","C":"Redução da produção de plaquetas devido à deficiência de ácido fólico e/ou vitamina B12.","D":"Redução da produção de plaquetas devido à infiltração da medula óssea por neoplasia."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-174785","number":"174785","sourceNumber":"174785","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"J.K.L, 67 anos, sexo feminino, balconista, está em uso de dose terapêutica de\nenoxaparina por trombose venosa profunda\napós artroplastia de joelho. Após 6º dia de uso da\nreferida medicação, a contagem de plaquetas é de 66.000/mm³ (contagem de plaquetas antes da\nanticoagulação era de 212.000/mm³). Não está em uso de outros medicamentos e apresenta-se\nassintomática. Diante deste contexto, assinale a alternativa ERRADA:","options":{"A":"Deve-se evitar o uso de fondaparinux (inibidor indireto de fator Xa).","B":"Esta condição resulta da formação de anticorpos contra complexo heparina/fator-4-plaquetário.","C":"Inibidores diretos da trombina constituem-se em opção terapêutica.","D":"Trombose (arterial ou venosa) é uma complicação frequente."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-149962","number":"149962","sourceNumber":"149962","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre a utilização de hemocomponentes em pacientes cirúrgicos, assinale a alternativa\nCORRETA:","options":{"A":"A utilização de hemocomponentes leucodepletados está indicada para prevenção de reação\ntransfusional febril não hemolítica em pacientes com mais de duas reações prévias.","B":"As transfusões de plasma e/ou crioprecipitados devem ser feitas com filtros, devido à alta\nconcentração de leucócitos íntegros.","C":"O uso de concentrado de hemácias deve ser feito com parcimônia devido ao risco de sobrecarga\nvolumétrica.","D":"Plasma fresco congelado tem como uma de suas principais indicações promover expansão\nvolumétrica."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-149933","number":"149933","sourceNumber":"149933","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Em relação a paciente submetido a profilaxia para trombose venosa profunda por\ntempo prolongado com heparina não fracionada, assinale a alternativa ERRADA:","options":{"A":"Esta droga é clareada principalmente pelos receptores situados no endotélio, macrófagos e rins","B":"Pode apresentar trombocitopenia autoimune","C":"Seu mecanismo de ação se faz por inativação de vários fatores da cascata de coagulação,\nsendo os mais sensíveis a trombina e o fator\nXa","D":"Sua maior afinidade por proteínas plasmáticas lhe confere maior biodisponibilidade e maior\nmeia-vida plasmática"},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-112062","number":"112062","sourceNumber":"112062","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Em relação à composição dos diversos líquidos e secreções do corpo humano, assinale\na afirmativa CORRETA:","options":{"A":"A bile e o suco pancreático são os que contém as maiores concentrações de potássio","B":"A maior concentração de sódio é encontrada na saliva","C":"Suco pancreático e bile têm altas concentrações de sódio","D":"Uma das concentrações mais baixas de cloro é encontrada na urina"},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-112039","number":"112039","sourceNumber":"112039","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 68 anos, foi submetido à Ressecção Transuretral da Próstata (RTU) para\ntratamento de hipertrofia benigna. No pós-operatório imediato apresenta crises convulsivas. Este\nquadro deve ser consequência de:","options":{"A":"Hipernatremia.","B":"Hiperpotassemia.","C":"Hiponatremia.","D":"Hipopotassemia."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-112040","number":"112040","sourceNumber":"112040","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Em relação a hiperpotassemia, assinale a alternativa ERRADA:","options":{"A":"É um dos distúrbios eletrolíticos mais comuns no pós-operatório","B":"Favorece o aparecimento de intoxicação digitálica em paciente em uso de tal medicação","C":"Pode ser decorrente de acidose metabólica","D":"Pode ser decorrente de insuficiência renal aguda, mas não da crônica"},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-60303","number":"60303","sourceNumber":"60303","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"G.H.R., 55 anos, sexo masculino, gráfico, tabagista crônico, foi atendido no serviço de\npronto-socorro com quadro de tosse importante, inapetência e prostração. Radiografia de tórax\nevidenciou massa tumoral localizada na base do pulmão direito. Exames laboratoriais de sangue\nvenoso revelaram Na+ = 110 mEq/L, K+ = 3,5 mEq/L e glicemia = 100 mg/dl. Em relação a este\ncaso, está ERRADO afirmar:","options":{"A":"A água corporal total deve estar aumentada.","B":"A dosagem de Na+ urinário deve estar > 40 mEq/L.","C":"A osmolaridade urinária deve estar entre 200 mmol/L e 800 mmol/L.","D":"O Hormônio Antidiurético (ADH) e o peptídeo natriurético atrial devem estar aumentados."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-60314","number":"60314","sourceNumber":"60314","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"C.B.T., 33 anos, sexo masculino, cambista, procurou atendimento médico de urgência\ncom desidratação devida a vômitos incoercíveis. A\nendoscopia digestiva alta evidenciou estenose\npilórica. Exames laboratoriais de sangue venoso revelaram Na+ = 129 mEq/L, K+ = 2,8 mEq/L, Cl-\n\n= 88 mEq/L. Em relação ao tratamento deste paciente, está ERRADO afirmar:","options":{"A":"Deve-se administrar solução de bicarbonato de sódio, por via endovenosa.","B":"Deve-se passar sonda nasogástrica.","C":"Não é necessário reposição imediata de Na+ e K+.","D":"Deve-se administrar solução salina 0,9%, por via endovenosa."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-60247","number":"60247","sourceNumber":"60247","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"AFZ, 49 anos, sexo masculino, pintor, com 75 kg, está sendo submetido a uma cirurgia\nde grande porte. No pré-operatório, foi\nadministrada reposição hídrica baseada principalmente em\nsoro glicosado a 5%. Numa avaliação multiparâmetros, o anestesista constatou Na+ = 127 mEq/L.\nO paciente mantém pressão arterial estável, e não há nenhuma evidência de sangramento\naumentado no ato cirúrgico. Das condutas abaixo, qual é a MAIS adequada para este caso?","options":{"A":"Acrescentar 20 ampolas de NaCl a 10% à soroterapia do peroperatório, mais 10 ampolas para\nadministração nas próximas 24 horas.","B":"Acrescentar 20 ampolas de NaCl a 10% à soroterapia nas próximas 24 horas, incluindo a\nreposição hídrica do peroperatório.","C":"Acrescentar 4 ampolas de NaCl a 10% para reposição durante o ato cirúrgico, reavaliar a\nnecessidade por novos exames complementares, e continuar a reposição lenta no pós-operatório\nimediato.","D":"Não administrar sódio em sua soroterapia."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-60347","number":"60347","sourceNumber":"60347","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Homem de 32 anos, usuário de cocaína, encontra-se internado na enfermaria de clínica\nmédica com quadro séptico, em uso de cefepima. Foi isolado Klebsiella sp. em 3 amostras de\nhemocultura e o plantonista é acionado pela enfermagem para avaliar achado de gangrena em\nartelhos de ambos os pés. Havia também sinais de necrose hemorrágica na pele dos antebraços e\ndas mãos. Diante do quadro, é CORRETO afirmar que:","options":{"A":"A fibrinólise secundária gera diminuição dos produtos de degradação da fibrina e aumento do\nd-dímero.","B":"O consumo e o aumento de função dos fatores de coagulação são responsáveis pelo\nalargamento da atividade de protrombina e do tempo de tromboplastina parcial ativado.","C":"O depósito de fibrina intravascular causa fragmentação das hemácias e gera aparecimento de\nesquizócitos no sangue periférico.","D":"Os produtos de degradação da fibrina são potentes agentes trombofílicos e se associam à\ntrombose microvascular."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-52338","number":"52338","sourceNumber":"52338","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Um homem de 65 anos queixa-se de cansaço e adinamia. Ao exame físico, observa-se\nhipotrofia das papilas linguais, leve\nicterícia e discreta esplenomegalia. O hemograma revela\nacentuada anemia macrocítica (hematócrito = 15%), leucopenia (3.300/mm³, com presença de\nneutrófilos hipersegmentados) e discreta plaquetopenia (105.000/mm³). Observa-se, também,\nelevação da desidrogenase láctica. O paciente é tratado com vitamina B12 parenteral. Pergunta-se:\nQual o distúrbio eletrolítico que se poderia esperar nos primeiros dias de tratamento?","options":{"A":"Hipocalemia.","B":"Hiponatremia.","C":"Hipercalemia.","D":"Hipocalcemia."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-52417","number":"52417","sourceNumber":"52417","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Criança do sexo masculino, com 2 anos de idade, apresenta hemartrose volumosa em\njoelho esquerdo secundária à queda da própria altura. O único dado relevante na história perinatal\né relato de hemorragia no coto umbilical. Exames laboratoriais: tempo de tromboplastina parcial\nativada (PTTa) prolongado. Tempo de protrombina, tempo de sangria e contagem de plaquetas\nnormais. Em relação ao caso clínico, o diagnóstico mais provável é:","options":{"A":"Deficiência congênita de fator VII.","B":"Deficiência de vitamina K.","C":"Doença de von Willebrand.","D":"Hemofilia."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-52386","number":"52386","sourceNumber":"52386","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Assinale a alternativa CORRETA. Uma criança com insuficiência renal aguda está com\no potássio sérico = 7,2 mEq/L. As alterações\nao ECG que podem ser observadas são:","options":{"A":"Baixa voltagem do QRS, onda P aumentada, onda T alta e pontiaguda, diminuição do intervalo\nR.","B":"Intervalo PR aumentado, onda P aumentada, onda T diminuída.","C":"Onda T alta e pontiaguda, alargamento do QRS e do espaço QT, aumento do intervalo R,\ndiminuição ou desaparecimento total da onda P.","D":"Presença de onda U, baixa voltagem do QRS, onda T pontiaguda e alta, onda P aumentada,\ndiminuição do intervalo R."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-53338","number":"53338","sourceNumber":"53338","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 70 anos, diabético tipo 2, ex-tabagista, foi submetido à pancreatectomia\ncorpo-caudal e esplenectomia para\ntratamento de neoplasia localizada no corpo do pâncreas. No\npós-operatório, a gasometria arterial revelou: pH = 7,37; pO2 = 90 mmHg; pCO2 = 50 mmHg;\nHCO3 = 30 mEq/L; EB = + 5,0. Qual o distúrbio acidobásico mais provável?","options":{"A":"Alcalose metabólica totalmente compensada.","B":"Acidose respiratória crônica totalmente compensada.","C":"Acidose respiratória parcialmente compensada.","D":"Acidose respiratória aguda totalmente compensada."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-53342","number":"53342","sourceNumber":"53342","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente cirrótico, diabético, foi submetido à esofagectomia e à gastrectomia parcial\ncom anastomose esofagogástrica na região cervical,\npara tratamento de neoplasia no terço médio\ndo esôfago. No pós-operatório, evoluiu com hiponatremia. Este distúrbio pode ser explicado pelas\nopções abaixo, EXCETO:","options":{"A":"Sangramento excessivo no transoperatório.","B":"Síndrome da secreção inapropriada do hormônio antidiurético.","C":"Sindrome hiperglicêmica hiperosmolar do diabético.","D":"Comprometimento da excreção renal de água livre decorrente de doença subjacente."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-45032","number":"45032","sourceNumber":"45032","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 23 anos de idade, com quadro de glomerulonefrite pós-estreptocócica e\ninsuficiência renal, apresenta níveis séricos de sódio: 145 mEq/L, potássio: 7,6 mEq/L, creatinina:\n3,4 mg/dl e eletrocardiograma mostrando ausência de onda P, ritmo idioventricular a 60 bpm, com\nQRS de 0,13seg. Qual a conduta prioritária nesse caso?","options":{"A":"Furosemida IV, 40 mg/dia.","B":"Gluconato de cálcio 10% IV diluído em 10-30 ml de bicarbonato de sódio 8,4%, 100 ml/30min.","C":"Gluconato de cálcio 10% IV (10-30 ml/30min).","D":"Insulina regular 10 UI em soro glicosado 10%, 250 ml IV/30min."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-31495","number":"31495","sourceNumber":"31495","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Homem de 32 anos, com cirrose hepática escore Child-Pugh ?C?, está em uso de\nespironolactona (100 mg/dia), furosemida (40 mg/dia) e propranolol (40 mg/dia) há cerca de 30\ndias. É admitido em serviço de urgência com náuseas, vômitos e sonolência. Há dois dias, foi\nsubmetido à paracentese com retirada de oito litros de líquido ascítico. Bioquímica sérica à\nadmissão: sódio = 116 mEq/L, cloreto = 88 mEq/L, potássio = 3,1 mEq/L e creatinina = 1,8 mg/dl.\nQual é o mecanismo mais provável da hiponatremia?","options":{"A":"Déficit de produção da aldosterona pela suprarrenal.","B":"Eliminação excessiva de sódio pelos rins.","C":"Expansão do volume intravascular.","D":"Retenção de água livre pelos túbulos renais."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-22921","number":"22921","sourceNumber":"22921","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente do sexo feminino, 62 anos, 70 Kg, diabética em uso de insulina é submetida à\nretossigmoidectomia no tratamento de tumor da junção retossigmoidiana. Evolui no 6º dia\n\npós-operatório com infecção do trato urinário e descompensação metabólica. Ao exame físico,\nobserva-se febre, taquicardia e hiperventilação (paciente apresentava movimentos respiratórios\nrápidos e profundos). Gasometria arterial realizada após 24 horas revela: pH = 7,19; HCO3 = 12\nmEq/L; pCO2 = 26 mmHg; BE = -8. Em relação a esse caso podemos afirmar, EXCETO:","options":{"A":"Além da gasometria, estão indicados: leucograma, glicemia em jejum, dosagem de eletrólitos\nséricos e provas de função renal","B":"Espera-se que a lacuna de ânions esteja aumentada nesse caso","C":"Esse valor de pCO2 pode, a princípio, decorrer de mecanismo compensatório (hiperventilação)\nou ser proveniente de distúrbio respiratório\nassociado","D":"A terapêutica de escolha inicial, nesse caso, é a administração endovenosa aproximadamente\n170 mEq de bicabornato de sódio"},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-355408","number":"355408","sourceNumber":"355408","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente do sexo feminino, 30 anos, consulta seu médico com um histórico de\nepistaxes frequentes desde a infância, bem como\nmenstruações prolongadas e com alto fluxo.\nSangramentos excessivos após exodontias. Ela relata que outros membros de sua família também\ntêm o mesmo histórico de sangramentos excessivos. Os exames de laboratório revelam um tempo\nde protrombina (TAP) e um Tempo de Tromboplastina Parcial Ativada (TTPA), dentro da faixa da\nnormalidade, porém uma plaquetopenia leve é vista em exame, com plaquetometria em torno de\n\n100.000. Qual é o diagnóstico mais provável para esta paciente?","options":{"A":"Hemofilia A.","B":"Trombocitose essencial.","C":"Doença de von Willebrand.","D":"Púrpura trombocitopênica idiopática (PTI)."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-369748","number":"369748","sourceNumber":"369748","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente usuário de AAS e clopidogrel para insuficiência coronariana apresenta\nsangramento importante. Dentre as opções abaixo qual poderia ser usada para melhorar a\ncoagulação do paciente tendo em vista as medicações que utiliza?","options":{"A":"Complexo protrombínico","B":"Administração de plaquetas","C":"Fitomenadiona","D":"Plasma fresco congelado"},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-355378","number":"355378","sourceNumber":"355378","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Criança de 7 anos, previamente hígida, retorna de viagem durante o feriado para o sítio\nda família com petéquias em tronco e equimoses em membros inferiores iniciadas há 4 dias\nacompanhada de epistaxe nasal. Não há relato de trauma, apresenta bom estado geral, sem febre\nou outros sintomas associados. Realizado hemograma no PS: Hb: 13,0 g/dl, Ht: 37,5%, leucócitos\nglobais: 12500/mm³, segmentados: 42%, linfócitos: 48%, monócitos 10%, plaquetas 15,000/mm³.\n\nSobre o tratamento do caso em questão, pode-se afirmar que:","options":{"A":"os pais devem ser orientados sobre a melhora espontânea do quadro, não sendo necessária\npermanência no hospital.","B":"é recomendada internação em enfermaria hospitalar e parecer da cirurgia para realização de\nesplenectomia.","C":"é recomendada internação em UTI para realização de transfusão de plaquetas pelo risco de\nsangramento.","D":"é recomendada internação em enfermaria hospitalar e avaliação do hematologista para início de\ncorticoterapia."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-340709","number":"340709","sourceNumber":"340709","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"A varfarina pode ser utilizada no paciente com câncer:","options":{"A":"Na disponibilidade de outras medicações ou em situações específicas de contraindicação aos\noutros anticoagulantes, como na insuficiência renal crônica dialítica.","B":"Na indisponibilidade de outras medicações, mas não em situações específicas de\ncontraindicação aos outros anticoagulantes, como na insuficiência renal crônica dialítica.","C":"Na indisponibilidade de outras medicações ou em situações específicas de contraindicação aos\noutros anticoagulantes, como na insuficiência renal crônica dialítica.","D":"Na indisponibilidade de outras medicações ou em situações específicas de indicação aos outros\nanticoagulantes, como na insuficiência renal crônica dialítica."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-330307","number":"330307","sourceNumber":"330307","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Homem de 21 anos apresenta múltiplas sufusões pelo corpo de início há 3 dias. Nega\ntraumas, outras manifestações clínicas, comorbidades conhecidas, uso de medicamentos e de\ndrogas lícitas ou ilícitas. Não possui história familiar significativa. Ao exame físico, PA:\n110x70mmHg, FC: 68bpm, Tax: 36,5ºC. Apresenta sufusões nos membros superiores, inferiores e\ntronco. Sem outras anormalidades quaisquer (incluindo linfonodomegalias ou visceromegalias\nabdominais). Exames de laboratório: Hemoglobina: 15,3g/dL (VR 12-16g/dL); Leucócitos:\n5.840/mm³ (4000-11.000/mm³); neutrófilos: 2.580/mm³ (1500-7000/mm³); linfócitos: 1.250/mm³\n(1.000-4.000/mm³); plaquetas: 9.000/mm³ (150.000-450.000/mm³); hematoscopia do sangue\nperiférico: presença de macroplaquetas, sem outras anormalidades; creatinina: 0,7mg/dL; bilirrubina\ntotal: 0,4mg/dL (<1,2mg/dL); PCR: 1,2mg/L (<5mg/L); TSH: 1,560mUI/L (0,5-5,0mUI/L); RNI 1,1;\n\nPTTa 25/25; exame de urina sem alterações. Assinale a alternativa que apresenta um exame\ndiagnóstico CORRETAMENTE indicado na propedêutica desse caso.","options":{"A":"Mielograma.","B":"Fibrinogênio.","C":"Anticorpos anti-HIV.","D":"TC de pescoço, tórax e abdome total."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-330317","number":"330317","sourceNumber":"330317","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Em pediatria, são causas de anemia com plaquetopenia, EXCETO:","options":{"A":"Deficiência de folatos e vitamina B12.","B":"Leucemia linfocítica aguda.","C":"Leishmaniose visceral.","D":"Púrpura trombocitopênica autoimune (P.T.I) e púrpura de Henoch- Schonlein."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-330322","number":"330322","sourceNumber":"330322","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre a trombocitopenia imune primária, é CORRETO afirmar que:","options":{"A":"A deficiência de vitamina D é um diagnóstico diferencial.","B":"A PTI não tem relação com infecções virais agudas em crianças.","C":"É caracterizada com plaquetopenia abaixo de 100.000/mm³.","D":"Os pacientes geralmente apresentam anemia e hepatoesplenomegalia."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-301037","number":"301037","sourceNumber":"301037","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Uma criança de sete anos de idade é levada ao pronto atendimento devido ao\nsurgimento de petéquias e equimoses por todo\ncorpo. O pai, que acompanhava a criança, nega\ntraumas físicos e relata um quadro gripal há sete dias. Nega ingestão de medicamentos e, até o\npresente momento, a criança era hígida, sem história pregressa de doenças do sangue. Ao exame\nfísico, a criança estava eupneica, sem alterações cardíacas, sem viceromegalias ou\nlinfadenomegalias e com petéquias e equimoses em face, tronco e membros. Diante disso, foi\nsolicitado um hemograma, cujos resultados são: Hb = 12.5g/dl; Ht = 38%; VCM = 78; leucócitos =\n\n9.000 (N60% L30% M8% E2%); plaquetas = 80.000/mm3. Sobre esse quadro clínico, assinale a\nalternativa CORRETA.","options":{"A":"Trata-se de uma leucemia aguda, e a criança deverá ser internada em um hospital de referência\nem oncologia pediátrica para estender a\npropedêutica.","B":"Deve-se informar o pai que se trata de uma púrpura de Henoch-Schönlein, e a criança poderá\nreceber alta e ser conduzida\nambulatorialmente pelo pediatra.","C":"O quadro clínico e o exame laboratorial são condizentes com trombocitopenia imune, e o\npaciente pode ser internado para estender a propedêutica diagnóstica.","D":"Trata-se de um quadro de púrpura trombocitopênica imune, e o paciente deverá receber\ntransfusão de plaquetas com urgência como primeira conduta."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-260559","number":"260559","sourceNumber":"260559","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Pré-escolar apresenta há 2 dias sangramento gengival. Nega febre. Em seu exame\napresenta-se em bom estado geral, sem\nlinfadenomegalia ou hepatoesplenomegalia e notam-se\npetéquias e hematomas pelo corpo. Seu hemograma apresenta hemoglobina 12,5 g/dl, hematócrito\n\n= 36%, leucócitos 8.000/mm³ com contagem diferencial sem anormalidade para idade e plaquetas\n6.000/mm³. O diagnóstico mais provável é:","options":{"A":"Aplasia de medula.","B":"Linfoma.","C":"Púrpura trombocitopênica idiopática.","D":"Leucemia linfocítica aguda."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-260273","number":"260273","sourceNumber":"260273","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de seis anos de idade, com quadro de equimoses em tronco e membros\ninferiores há sete dias, sem história de\ntrauma, com bom estado geral, sem hepatoesplenomegalia\ne sem febre. Realizado hemograma: Hb: 12,5 g/dL, Ht 37%, leucócitos globais: 13.800/mm³,\nsegmentados: 40%, linfócitos: 50%, monócitos 10%, plaquetas 90.000/mm³. Assinale a alternativa\ncorreta com relação ao caso clínico apresentado.","options":{"A":"O início de uso de antibiótico de amplo espectro está indicado nesse caso devido à leucocitose\nevidenciada no hemograma.","B":"O agente etiológico mais provável é o vírus da dengue, e a conduta mais correta é a hidratação\noral domiciliar.","C":"O uso de corticoide é uma opção terapêutica nessa situação, visto que o caso do paciente é\nsugestivo de trombocitopenia imune.","D":"Esse paciente corre risco iminente de sangramento pela plaquetopenia e está indicada a\ntransfusão de plaquetas."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-253903","number":"253903","sourceNumber":"253903","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Dentre as medicações abaixo, a que potencializa o efeito da warfarina:","options":{"A":"Barbitúricos","B":"Ribavirina","C":"Piroxicam","D":"Colestiramina"},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-239872","number":"239872","sourceNumber":"239872","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Relacione as alterações laboratoriais nos distúrbios de coagulação com o diagnóstico\nmais provável:\n\nCOLUNA I - Alterações dos exames:\n\n1. Plaquetopenia;\n\n2. Tempo de tromboplastina parcial ativado prolongado;\n\n3. Tempo de protrombina prolongado;\n\n4. Dímero D aumentado.\n\nCOLUNA II - Diagnóstico:\n\n( ) Hemofilia;\n\n( ) Deficiência de vitamina K;\n( ) Leucemia;\n\n( ) Coagulação intravascular disseminada.\n\nAssinale a alternativa que apresenta a sequência CORRETA.","options":{"A":"1 3 2 4.","B":"2 1 4 3.","C":"2 3 1 4.","D":"2 1 4 3."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-219427","number":"219427","sourceNumber":"219427","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente sexo masculino, 72 anos, com diagnóstico de IAMSST. Está em tratamento\nhospitalar. Está recebendo heparina\nnão-fracionada e monitorado para possíveis sinais e sintomas.\nQual o episódio está mais relacionado a uma reação?","options":{"A":"Epistaxe","B":"Sincope","C":"Trombose venosa","D":"Distúrbio visual"},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-203873","number":"203873","sourceNumber":"203873","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Uma criança de 3 anos é internada na enfermaria devido ao surgimento súbito de\npetéquias em abdome e membros inferiores associado à epistaxe volumosa. Foi avaliada pelo\notorrinolaringologista que realizou um tamponamento de emergência. Ao exame, a criança está\nhipocorada, hidratada, acianótica, anictérica, com petéquias e equimoses em todo corpo, abdome\nsem visceromegalias, ausência de linfadenomegalias, escala de coma de Glasgow 15; FC = 120\nbpm; FR = 28 irpm; PA = 95 x 50mmHg. Na história pregressa, o teste do pezinho foi normal e\napresentou um quadro viral há 14 dias. O pediatra que fez o primeiro atendimento solicitou um\nhemograma que estava praticamente normal, com exceção do número de plaquetas que era de\n5.000/mm³. Assinale a alternativa que apresenta a hipótese diagnóstica e a conduta MAIS\nadequada para o caso descrito.","options":{"A":"Púrpura trombocitopênica idiopática e imunoglobulina intravenosa.","B":"Púrpura de Henoch-Schöenlein e anti-inflamatório venoso.","C":"Leucemia linfoblástica aguda e metilprednisolona venosa.","D":"Leishmaniose visceral e anfotericina B lipossomal intravenosa."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-217160","number":"217160","sourceNumber":"217160","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 82 anos da entrada no setor de emergência com fratura de colo de fêmur.\nÉ portador de coronariopatia, cardiopatia,\nnefropatia, e usuário de AAS, Clopidogrel, carvedilol,\naldactone e sinvastatina. O ortopedista está preocupado e pede sua opinião para prevenir\nsangramento intra-operatório. Qual opção correta:","options":{"A":"Uso de plasma fresco congelado 15 ml/kg com cuidado para evitar hipervolemia, no\npré-operatório.","B":"Uso de complexo protrombínico (fatores de coagulação II, VII, IX, X), de preferência com fator\nVII\nativado, no pré-operatório.","C":"Administração de plaquetas, ocasionalmente DDAVP, ou auxílio do tromboelastograma como\nguia em caso de sangramento.","D":"Suspender AAS e clopidogrel e operar após 10 dias."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-200513","number":"200513","sourceNumber":"200513","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Uma paciente de 2 anos de idade, apresenta exantema. Ela estava bem até duas\nsemanas atrás, quando iniciou febre e sintomas\nde ITRS (Infecção do Trato Respiratório) que\nresolveram sem tratamento. Ao exame físico, ela apresenta petéquias nas extremidades superiores\ne inferiores e no tronco. Sua contagem plaquetária é 25.000/mm³. A contagem de leucócitos é\n9.000/mm³ e o nível de hemoglobina é 11mg/dL. Em relação ao quadro clínico descrito acima,\nassinale qual o melhor próximo passo na conduta:","options":{"A":"Solicitar hemocultura e iniciar terapia antimicrobiana empírica.","B":"Administrar imunoglobulina intravenosa.","C":"Prescrever uma transfusão de plaquetas.","D":"Solicitar uma revisão do esfregaço do sangue periférico."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-184599","number":"184599","sourceNumber":"184599","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Em relação a reação transfusional a concentrado de hemácias, quais sinais/sintomas\nsão de maior gravidade?","options":{"A":"Crepitações bibasais.","B":"Aumento frequência respiratória.","C":"Aumento rápido na temperatura corporal.","D":"Prurido generalizado severo."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-181210","number":"181210","sourceNumber":"181210","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Em relação à avaliação de uma criança com Plaquetopenia, assinale a alternativa\nINCORRETA:","options":{"A":"A Púrpura Trombocitopênica Idiopática (PTI) recentemente diagnosticada é geralmente\nprecedida por infecções virais.","B":"Exames complementares tais como dosagem de anticorpo contra plaquetas podem auxiliar na\nconfirmação diagnostica em alguns casos, mas podem ser falsamente negativos em uma parcela\ndos pacientes pediátricos.","C":"História clínica, exame físico e exame de hemograma interpretado corretamente permitem\nrealizar o diagnótico diferencial das plaquetopenias da infância na maior parte dos casos.","D":"Assim que diagnosticado a PTI deve-se iniciar transfusão de plaquetas a cada 4 horas."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-181211","number":"181211","sourceNumber":"181211","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"São causas de Trombocitopenia no período neonatal, EXCETO:","options":{"A":"Sepse","B":"Leucemia Congênita","C":"Enterocolite Necrotizante","D":"Plaquetopenia Aloimune"},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-181212","number":"181212","sourceNumber":"181212","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Na Púrpura Trombocitopênica Idiopática (PTI) é frequente a presença de:","options":{"A":"Eosinofilia","B":"Anemia Macrocítica","C":"Macroplaquetas","D":"Neutropenia"},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-181028","number":"181028","sourceNumber":"181028","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Com relação à Trombocitopenia Imune Primária (PTI) marque a alternativa CORRETA:","options":{"A":"Além do hemograma, o aspirado de medula óssea (mielograma) deve ser realizado em todos os\npacientes com PTI para excluir outros diagnósticos.","B":"A presença de sintomas sistêmicos, como anorexia, dores articulares ou perda de peso é\ncomum na PTI.","C":"A trombocitopenia na PTI geralmente se segue a uma doença viral aguda em crianças\npreviamente hígidas.","D":"Todas as crianças com contagem de plaquetas < 30.000/mm3 mesmo que sem sangramento\ndevem receber transfusão de plaquetas pelo\nrisco aumentado de hemorragia grave."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-159448","number":"159448","sourceNumber":"159448","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Com relação às reações transfusionais, assinale a alternativa CORRETA:","options":{"A":"A sepse ocasionada pela contaminação bacteriana tem como etiologia bacteriana mais\nfrequente os germes de pele, como o S. aureus e S. epidermidis.","B":"As reações transfusionais podem ser classificadas como agudas, quando ocorrem no período de\naté 2 horas da transfusão, ou crônicas, quando ocorrem após 48 horas da transfusão.","C":"A TRALI apresenta início insidioso de hipoxemia e insuficiência respiratória durante ou até 48\nhoras após a transfusão.","D":"A reação febril não hemolítica ocorre com a frequência de 1 a 10 eventos a cada 50 transfusões,\nsendo mais frequente com o uso de\nconcentrado de hemácias."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-160177","number":"160177","sourceNumber":"160177","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Mulher, 27 anos, refere anorexia, prostração e emagrecimento de 8kg em 1 ano. Há 8\nmeses apresenta náuseas, vômitos, tonturas\nposturais e dor abdominal. Amenorreica há 6 meses.\nAo exame, está emagrecida e com nítida hipotensão postural. Há hiperpigmentação generalizada e\nredução de pelos axilares e pubianos. Que conjunto de manifestações laboratoriais espera-se\nencontrar nesta paciente?","options":{"A":"Hiponatremia ? hipocalemia ? hiperglicemia.","B":"Hiponatremia ? hipercalemia ? hiperglicemia.","C":"Hiponatremia ? hipercalemia ? hipoglicemia.","D":"Hipernatermia ? hipocalcemia ? anemia normo-normo."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-157958","number":"157958","sourceNumber":"157958","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Em relação aos antiagregantes plaquetários, como a aspirina e o clopidogrel, é correto\nafirmar que:","options":{"A":"São úteis na prevenção de trombose arterial e venosa profunda.","B":"São úteis apenas na trombose venosa profunda.","C":"São úteis apenas na trombose arterial.","D":"Podem ser utilizados com segurança em associação com dicumarínicos."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-158255","number":"158255","sourceNumber":"158255","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente que será submetido a cirurgia eletiva informa que é portador de doença\nhematológica que faz com que seu sangue coagule muito, tendo diversas internações por\nTrombose Venosa Profunda (TVP). Dentre as opções abaixo, qual é a causa mais comum de\nTrombose Venosa Profunda nos pacientes a serem submetidos a cirurgia?","options":{"A":"Fator V de Leiden.","B":"Síndrome do Anticorpo antifosfolípideo e deficiência de antitrombina III.","C":"Deficiência de proteína C.","D":"Deficiência de proteína S."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-158232","number":"158232","sourceNumber":"158232","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Uma senhora de 65 anos comparece ao pronto atendimento por causa de sufusões nos\nmembros superiores não relacionadas a trauma. Sem quaisquer outras queixas atuais ou prévias. É\nhipertensa e faz uso regular de anlodipino 10 mg ao dia há 5 anos, estando bem controlada; sem\noutras comorbidades conhecidas. Ao exame, PA era de 126/74 mmHg e não havia outra alteração\nalém das lesões cutâneas relatadas. O hemograma revelou Hg 14 g/dL, leucócitos 7450/?L com\ndiferencial normal e plaquetas 6680/?L. Os testes sorológicos para HIV, vírus das hepatites B e C\nresultaram negativos. O exame do sangue periférico por hematoscopia não revelou anormalidades.\nConsiderando o caso descrito, assinale a alternativa que apresenta a conduta MAIS adequada\nnesse caso.","options":{"A":"Deve-se iniciar tratamento com glicocorticoide.","B":"Deve-se realizar transfusão de plaquetas.","C":"Deve-se utilizar a imunoglobulina intravenosa como primeira escolha.","D":"Em caso de refratariedade, o rituximabe seria o tratamento de segunda linha mais indicado\nnesse caso."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-158041","number":"158041","sourceNumber":"158041","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Pré-escolar, 4 anos de idade, apresentou resfriado comum há 08 dias. Há 24 horas o\npai notou \"manchas vermelhas pequenas\" no\ntronco e na face. A diurese está normal. Não há\nhistória de uso de drogas, imunizações recentes ou distúrbios hematológicos na família. No exame\na criança está ativa, eupneica, hidratada, sem sangramento nas mucosas, hepatoesplenomegalia\nou linfoadenopatia. O único dado positivo é a presença de petéquias no tronco e na face. Solicitado\nhemograma que envidenciou: HB = 12,0 g/dl (11,0 a 14,5); HT = 34 ml eritro/dl (33,0 a 43,0);\nleucograma = 8.000 (diferencial normal); plaquetas = 80.000/mm³ (150.000 a 450.000). Qual a\nprincipal hipótese diagnóstica?","options":{"A":"Doença de von Willebrand.","B":"Púrpura trombocitopênica imunológica.","C":"Púrpura de Henoch-Schönlein.","D":"Leucemia linfoide aguda."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-137491","number":"137491","sourceNumber":"137491","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"No adulto clinicamente estável com potássio sérico de 2,5 mEq/L, qual é a velocidade\nmáxima de infusão de potássio (mEq/h) recomendada? Considerando paciente adulto com\nmonitorização eletrocardiográfica contínua.","options":{"A":"10.","B":"20.","C":"30.","D":"40."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-105955","number":"105955","sourceNumber":"105955","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Criança de 7 anos, sexo masculino, é internada com vômitos persistentes. A palpação\nabdominal identifica uma estrutura ovalada (?oliva?) em abdome superior a direita. O cirurgião\npediátrico tem a hipótese diagnóstica de estenose hipertrófica de piloro. Caso esteja correto, a\nalteração eletrolítica / gasométrica que espera encontrar é:","options":{"A":"alcalose metabólica + hipopotassemia","B":"acidose metabólica + hiperpotassemia","C":"alcalose respiratória + hiperpotassemia","D":"acidose respiratória + hipercloremia"},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-103748","number":"103748","sourceNumber":"103748","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre distúrbios eletrolíticos e acidobásicos marque a alternativa CORRETA:","options":{"A":"Achados neurológicos não são vistos na hipocalcemia.","B":"Total de água em homens acima de 60 anos é de 30%.","C":"Na hipocalemia refratária deve-se considerar hiponatremia associada.","D":"Hiponatremia é frequentemente vista em pacientes infectados pelo HIV."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-103059","number":"103059","sourceNumber":"103059","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 50 anos, sexo masculino, admitido devido à diarreia aguda, volumosa, sem\nsangue, pus, ou febre, de 6 a 8 episódios diários, acompanhados de vômitos há 4 dias, evoluindo\ncom desidratação sintomática. Admitido em uma unidade de pronto atendimento, com PA de 80 x\n40 mmHg e FC de 140 bpm, com melhora após 1.500 ml endovenoso de solução de cloreto de\nsódio a 0,9%. Exames laboratoriais na admissão: hemoglobina = 12,4 mg/dl; leucócitos =\n11.200/mm³; neutrófilos = 85%; bastonetes = 4%; plaquetas = 145.000; creatinina = 1,6 mg/dl; ureia\n\n= 104 mg/dl; K = 1,9 mEq/L; pH = 7,32; HCO3 = 15,6 mmol/L; Na = 152 mEq/L. Após as medidas\niniciais de hidratação, foi realizado\neletrocardiograma no paciente, que revelou: ritmo de bradicardia\nsinusal com onda P de 3 mm de amplitude, intervalo PR de 240ms, QRS de 170ms de duração,\nextrassístoles ventriculares, depressão do segmento ST, seguido de inversão de onda T e\npresença de onda U. Assinale a conduta inicial mais adequada:","options":{"A":"Providenciar um acesso venoso central imediatamente.","B":"Administrar gluconato de cálcio venoso, imediatamente, para estabilização da membrana da\ncélula cardíaca.","C":"Solicitar vaga em unidade de terapia intensiva com urgência.","D":"Iniciar infusão de potássio em dois acessos venosos periféricos."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-103101","number":"103101","sourceNumber":"103101","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 36 anos, sexo masculino, iniciou há 2 dias com quadro de dor epigástrica\nacompanhado de vômitos e diarreia. Procurou Pronto Atendimento (PA) relatando 10 episódios de\ndiarreia aquosa e 8 episódios de vômitos nas últimas 24 horas. Apresentava-se bastante\ndesidratado, taquicárdico, um pouco agitado, com tremores de extremidade. Pressão arterial de 140\nx 80 mmHg e frequência respiratória de 24 irpm. Negava comorbidades e uso de medicamentos.\n\nTabagista e etilista diário. Iniciou-se hidratação intravenosa, prescrito sintomáticos, colhidos\nexames laboratoriais e apesar da hidratação,\nevoluiu com piora da taquicardia, piora da agitação,\nficou sudorético, confuso e com alucinações táteis. Ao exame clínico, não apresentava nenhuma\nalteração neurológica além do quadro confusional. Manteve estabilidade hemodinâmica em todo o\nperíodo. Evoluiu com crise convulsiva tônico-clônica generalizada de 30s de duração. Exames\nlaboratoriais mostravam: Na = 150 mEq/L (VR = 135-145); K = 3,4 mEq/L; Mg = 2,2 mEq/L; ureia =\n60 mg/dl; creatinina = 1,8 mEq/L; hemoglobina = 18 g/L; leucócitos = 6.500/mm³; bastonetes = 1%;\nproteína C-reativa = 23 mg/L (VR < 10). Sobre o caso clínico descrito, assinale a alternativa\nCORRETA:","options":{"A":"O paciente deve receber hidratação com cloreto de sódio a 0,9%, administração de tiamina,\ncontenção química, monitorização da diurese e prescrição de loperamida.","B":"O paciente deve receber, na abordagem da crise convulsiva, fenitoína na dose 15 mg/kg para\ntratamento de recorrência de novas crises.","C":"O paciente deve receber haloperidol para contenção química, visto seu poder tranquilizante com\npouco efeito depressor do sistema\nrespiratório ser adequado.","D":"O paciente deve fazer punção liquórica, caso evolua com piora da confusão com presença de\nalucinações visuais, dos sintomas adrenérgicos e ainda apareça febre, pois a principal hipótese se\ntornaria infecção do sistema nervoso central."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-106008","number":"106008","sourceNumber":"106008","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre o tratamento no pronto atendimento de um paciente com potássio sérico de 6,7\nmmol\\l e sem alterações eletrocardiográficas, é correto afirmar:","options":{"A":"O gluconato de cálcio atua na remoção do potássio por facilitar eliminação renal.","B":"O uso de Gluconato de cálcio EV deve ser usado como profilaxia de arritmias nesse caso","C":"Está indicado nesse caso a solução de glicoinsulina ( glicose + insulina), nebulização com\nFenoterol e furosemida EV.","D":"O poliestirenossulfonato de cálcio atua na estabilização da membrana celular."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-109895","number":"109895","sourceNumber":"109895","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 63 anos é submetido a colectomia total por abdome agudo obstrutivo sob\nanestesia geral. A cirurgia transcorre sem intercorrências e o paciente mantém estabilidade\nhemodinâmica e débito urinário adequado. A cirurgia tem duração de 6 horas. A reposição volêmica\né feita com soro fisiológico 4 L, solução de hidroxietilamido 2 L e 2 unidades de concentrado de\nhemácias. No período pós-operatório imediato, evolui com acidose metabólica (pH 7,17; PaO2 135\nmmHg; PaCO2 44 mmHg; HCO3-1 12 mEq.L-1; BE -11; SaO2 97%), náuseas e vômitos (Na+ 145\nmEq.L-1; K+ 5,6 mEq.L-1), distúrbio da coagulação e sangramento, oligúria e elevação da dosagem\nde creatinina plasmática. A explicação provável para a complicação é:","options":{"A":"Sepse.","B":"Hipovolemia.","C":"Hipercloremia.","D":"Falência cardíaca."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-120723","number":"120723","sourceNumber":"120723","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 37 anos de idade com insuficiência renal crônica em programa de\nhemodiálise 3 vezes por semana. Sua adesão\nao tratamento dialítico é ruim e perdeu sua última\nsessão de diálise, sendo atendido em caráter de urgência por causa de fraqueza e náuseas, com\nos seguintes exames laboratoriais: Na+ - 128 mEq/L; K+ - 7,2 mEq/L; Cl - 95 mEq/L; bicarbonato\nsérico: 15 mEq/L. Um ECG mostra bloqueio cardíaco de primeiro grau, ondas T pontiagudas e\ncomplexos QRS alargados. Enquanto aguarda pela diálise recebe infusão de gluconato de cálcio,\nbicarbonato de sódio, glicose com insulina, fenoterol inalatório e sulfonato poliestireno de cálcio\noral. Qual destas medicações é menos provável de reduzir sua concentração sérica de potássio?","options":{"A":"fenoterol.","B":"bicarbonato de sódio.","C":"glicose e insulina.","D":"gluconato de cálcio.","E":"sulfato poliestireno de cálcio."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-120766","number":"120766","sourceNumber":"120766","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Mulher com 63 anos de idade, com história de cirurgia de Heller para megaesôfago\nchagásico há 8 anos, é internada com\nsemiologia pulmonar compatível com o diagnóstico de\npneumonia à direita e os seguintes achados adicionais: febril (temperatura axilar=38,5oC),\nemagrecida (peso=36kg; altura 160cm), prega cutânea tricipital de 5mm. Apresenta discreto edema\npré-tibial (+/6+) e os seguintes exames laboratoriais, realizados à internação:\nleucócitos=12.000/mm3 (diferencial: 7-83-0-0-7-3), hemoglobina = 7,8g/dl, e níveis séricos de\nalbumina = 2,4g/dl, proteína C reativa = 32mg/dl, ferritina= 723 g/dl e ferro = 14 g/dl. eletrólitos\nséricos (sódio-122mEq/l; potássio=2,8mEq/l). Em relação à hidratação dessa paciente,\n\nassinale a alternativa correta:","options":{"A":"A hidratação deve ser feita por via venosa","B":"Deve-se repor albumina intravenosa para otimizar a diurese","C":"A reposição de albumina deve ser seguida de\nfurosemida intravenosa","D":"É necessário reposição de sódio, visando\nnormalização dos níveis séricos","E":"A restrição hídrica constitui melhor opção no tratamento da hiponatemia"},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-81125","number":"81125","sourceNumber":"81125","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre a hipocalemia, assinale a alternativa INCORRETA:","options":{"A":"Manifestações eletrocardiográficas típicas são: depressão do segmento ST e presença de onda\nU.","B":"Tratamento de hipovitaminose B12, anfotericina B e acetazolamida podem causar redução do\npotássio sérico.","C":"Clinicamente, em casos moderados e graves, cursa com rigidez muscular.","D":"O uso de digitálicos predispõe arritmia na vigência de hipocalemia."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-86011","number":"86011","sourceNumber":"86011","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Lactente de seis meses, portador de doença pulmonar crônica, é internado em unidade\nde terapia intensiva em decorrência de\ninsuficiência respiratória secundária à infecção respiratória\naguda. Sua gasometria (FIO2 de 0,4) no momento da internação mostra pH: 7,21; pO2: 63 mmHg;\npCO2: 60 mmHg; bicarbonato: 24 mEq/L. Em relação ao distúrbio do equilíbrio acidobasico\nencontrado, pode se afirmar que se trata de:","options":{"A":"Acidose mista.","B":"Alcalose mista.","C":"Acidose respiratória.","D":"Acidose respiratória associada à alcalose metabólica."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-58941","number":"58941","sourceNumber":"58941","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Alcalose hipocalêmica está associada a:","options":{"A":"Insuficiência renal pós-operatória.","B":"Gastrectomia.","C":"Trauma grave.","D":"Transfusão de grande quantidade de sangue."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-58980","number":"58980","sourceNumber":"58980","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Marque a alternativa INCORRETA sobre as hiponatremias.","options":{"A":"As hiponatremias isotônicas causadas por hipertrigliceridemia ou paraproteinemias são\npseudo-hiponatremias que não requerem tratamento.","B":"As causas mais comuns de hiponatremia são as hipotônicas, e o próximo passo diagnóstico é\ndeterminar a volemia do paciente.","C":"A causa mais comum de hiponatremia hipotônica hipovolêmica é a Síndrome de Secreção\nInapropriada do Hormônio Antidiurético (SSIADH).","D":"Nas hiponatremias hipotônicas hipervolêmicas, o tratamento inicial é a restrição hídrica,\npodendo-se associar diurético de alça."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-51446","number":"51446","sourceNumber":"51446","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Um paciente apresenta uma gasometria arterial com Ph = 7,30 ; PO2 = 140 mmHg ;\nPCO2 = 28 ; HCO3 = 10. O diagnóstico do distúrbio acido-básico é:","options":{"A":"Acidose metabólica.","B":"Acidose respiratória.","C":"Acidose mista.","D":"Acidose metabólica com alcalose respiratória."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-33844","number":"33844","sourceNumber":"33844","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Marque a alternativa CORRETA. Paciente submetido à laparotomia exploradora devido\nà obstrução do jejuno proximal por aderências de\ncirurgia prévia. Foi realizada a lise das aderências\ne a Sonda Nasogástrica (SNG), passada no pré-operatório, foi mantida. Nos dois primeiros dias\n\npós-operatórios, a SNG drenou 2500 ml/24h de secreção gástrica e a reposição hidroeletrolítica foi\nnegligenciada. A gasometria arterial esperada para este paciente é:","options":{"A":"pH = 7,3; pO2 = 140; pCO2 = 50; BE = -6; HCO3 = 24; SatO2 = 99%.","B":"pH = 7,5; pO2 = 50; pCO2 = 23; BE = +5; HCO3 = 22; SatO2 = 87%.","C":"pH = 7,3; pO2 = 89; pCO2 = 38; BE = -7; HCO3 = 15; SatO2 = 97%.","D":"pH = 7,5; pO2 = 93; pCO2 = 43; BE = +3; HCO3 = 31; SatO2 = 96%."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-9628","number":"9628","sourceNumber":"9628","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Mãe leva Tiago, de 4 semanas de vida, ao pediatra com relato de que o mesmo vem\napresentando vômitos amarelados constantes cada vez mais frequentes e que os últimos vômitos\ntêm apresentado sangramento. Observou diminuição do volume de fezes. Ao exame, criança com\nbaixo peso, desidratada e prostrada. À palpação abdominal, observa-se massa semelhante a uma\nazeitona no quadrante superior esquerdo. Qual o distúrbio metabólico mais comumente pode ser\nencontrado nesta situação?","options":{"A":"Alcalose metabólica hipocalêmica e hiperclorêmica.","B":"Acidose metabólica hipercalêmica e hipoclorêmica.","C":"Alcalose metabólica hipocalêmica e hipoclorêmica.","D":"Acidose metabólica hipocalêmica e hipoclorêmica."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-347375","number":"347375","sourceNumber":"347375","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Uma paciente com 30 anos, branca, procura serviço de emergência devido a\nsangramento gengival e ao aparecimento de pontos\navermelhados nos membros inferiores há 15\ndias, com piora progressiva das lesões e fadiga. Nega febre, uso de medicamentos e ingesta de\nbebidas à base de quinino. Foram solicitados exames que mostraram: Ao exame físico, notou-se a\npresença de lesões na pele, com petéquias no dorso do pé e no tornozelo (sola dos pés sem\nlesões) e hemorragia bolhosa na mucosa bucal. Com base nas informações descritas, a principal\nhipótese diagnóstica é","options":{"A":"síndrome hemolítico-urêmica (SHU).","B":"púrpura trombocitopênica trombótica.","C":"trombocitopenia induzida por fármaco.","D":"púrpura trombocitopênica imunológica grave."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-347380","number":"347380","sourceNumber":"347380","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Uma paciente com 40 anos, branca, encaminhada da unidade básica de saúde, é\natendida para investigação de trombose venosa profunda (TVP). Conta que apresentou um\nsegundo episódio de TVP do membro inferior esquerdo há 30 dias. Informa que faz uso de\nanticoncepcional oral desde os 18 anos e que a primeira TVP ocorreu aos 36 anos, quando foi\ntratada com varfarina por 6 meses, sem intercorrências. Conta que teve 3 gestações, a primeira\ndelas, aos 22 anos, resultou em um aborto espontâneo, as outras 2 foram a termo. Ela informa\nainda que sua mãe também já apresentou TVP. Relata também que atualmente vem fazendo uso\nde rivaroxabana. Para investigação de TVP na paciente nesse momento, deve-se solicitar","options":{"A":"anticorpos anti-beta-2 glicoproteína 1 IgG e IgM.","B":"anticorpos anticardiolipina IgG e IgM.","C":"proteína C e proteína S livre.","D":"PCR para fator V Leiden."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-318525","number":"318525","sourceNumber":"318525","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Um menino com 5 anos de idade, acompanhado da mãe, é atendido em unidade de\nsaúde. A mãe relata o aparecimento\nabrupto de manchas arroxeadas indolores nos membros\ninferiores da criança há 2 dias, sem outras queixas. Há 1 mês, conta que o filho apresentou quadro\nde resfriado comum, para o qual fez uso somente de soro fisiológico para lavagem nasal. Nega uso\nrecente de medicamentos ou antecedentes familiares relevantes. Ao exame clínico, o menino\napresenta regular estado geral, corado, hidratado, anictérico, acianótico, afebril e eupneico; baço\npalpável ao nível de rebordo costal esquerdo, presença de petéquias e equimoses indolores em\nmembros inferiores. Exame de Fundo de Olho sem sinais de sangramento. Sem evidências de\noutros sangramentos ou outros achados clínicos relevantes. Os exames laboratoriais iniciais\nevidenciaram hemoglobina de 12,3 g/dL (valor de referência [VR]: 12,6 g/dL); hematócrito de 38%\n(VR: 37%); contagem de 5.700 leucócitos/mm³ (VR: 5.000-15.000/mm³), com 37% de\nsegmentados, 44% de linfócitos, 1% de monócitos e contagem de plaquetas de 64.000/mm³ (VR:\n150.000-450.000/mm³). Coagulograma com um tempo de tromboplastina de 12,5 segundos (VR:\n10-14 segundos), 100% de atividade de protrombina e um tempo de tromboplastina ativada de 31\nsegundos (VR: 25-36 segundos). Considerando a principal hipótese diagnóstica para esse caso,\nqual deve ser a conduta terapêutica inicial?","options":{"A":"Terapia com corticosteroide.","B":"Internação para esplenectomia.","C":"Observação clínica ambulatorial.","D":"Administração de imunoglobulina."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-343679","number":"343679","sourceNumber":"343679","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Um senhor aposentado de 68 anos de idade chega a um pronto-socorro com dor na\nperna esquerda, de quatro dias de duração. Ele\ntambém se queixa de edema no tornozelo\nesquerdo, que tem dificultado a deambulação. É fumante ativo e tem história clínica de doença do\nrefluxo gastroesofágico. O exame físico revela edema ++ no tornozelo esquerdo. São fatores de\nrisco para o desenvolvimento de Trombose Venosa Profunda (TVP), EXCETO:","options":{"A":"Mutação Protrombina.","B":"Deficiência de Antitrombina.","C":"Mutação do Fator V Leiden.","D":"Deficiência de Proteína C e S.","E":"Trombastenia de Glanzmann."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-343692","number":"343692","sourceNumber":"343692","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"A terapia transfusional requer indicações e cuidados específicos, inclusive com riscos e\ncomplicações quando indicada. Nesse sentido, é correto afirmar sobre a TRALI (Transfusion\nRelated Acute Lung Injury):","options":{"A":"TRALI severa é distinguível da Síndrome do Desconforto Respiratório Agudo (SDRA) através da\nradiografia de tórax.","B":"o edema pulmonar é unilateral e distinguível pela radiografia de tórax do edema pulmonar\ncardiogênico.","C":"geralmente ocorre após 5 a 7 dias da transfusão de concentrado de hemácias.","D":"hipotensão e hipoxemia de início abrupto são marcadores que excluem o diagnóstico.","E":"fatores de risco para SDRA, quando previamente presentes, impedem o diagnóstico de TRALI,\ndenominando-se ?possível TRALI?."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-331190","number":"331190","sourceNumber":"331190","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre púrpura trombocitopênica imune, é correto afirmar:","options":{"A":"A presença de febre baixa e infarto ganglionar é comum, devendo ser excluídas doenças\ninfecciosas.","B":"É caracterizada pela presença de trombocitopenia ou bicitopenia sem outras alterações\nsistêmicas.","C":"A transfusão de plaquetas é medida paliativa, estando indicada a contagem de plaquetas menor\nque 20 mil","D":"Corticoterapia está indicada para todos os pacientes, independentemente da contagem de\nplaquetas, pois diminui o risco de complicações.","E":"É caracterizada pela presença de trombocitopenia isolada, sem outras manifestações\nsistêmicas."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-311406","number":"311406","sourceNumber":"311406","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre a indicação de transfusão de hemocomponentes, é INCORRETO afirmar que:","options":{"A":"em geral, a transfusão de uma unidade de concentrado de hemácias aumenta a dosagem de\nhemoglobina em 1 mg/dL, caso não haja sangramento ativo.","B":"não havendo contraindicações, e na inexistência de sangramento ativo, a transfusão de\nplaquetas está indicada, profilaticamente, em\nvalores < 60.000/L, segundo o Ministério da Saúde.","C":"em trombocitopenias induzidas por heparina, as transfusões de plaquetas aumentam\nconsideravelmente o risco de trombose.","D":"em neurocirurgias e cirurgias oftalmológicas, é recomendado que a contagem de plaquetas\nesteja em torno de 100.000/L, imediatamente\nantes do procedimento.","E":"hospitais que atendam pacientes vítimas de trauma devem ter protocolo de transfusão maciça\nvigente."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-311439","number":"311439","sourceNumber":"311439","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Mulher, 36 anos, em pós-operatório imediato de cirurgia bariátrica, recebe dose 3x\nmaior que o preconizado de enoxaparina, e\nevolui com sangramento profuso pela ferida operatória,\nmas ainda mantém estabilidade hemodinâmica. A droga de escolha que pode ser usada como\nantidoto é:","options":{"A":"Vitamina K.","B":"Protamina.","C":"Crioprecipitado.","D":"Concentrado de plaquetas.","E":"Plasma fresco congelado."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-277728","number":"277728","sourceNumber":"277728","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Homem de 20 anos vai à consulta médica com hemograma e coagulograma solicitados\npreviamente para realizar a excisão cirúrgica de um lipoma de 5 cm no dorso. O paciente é\ncompletamente assintomático e seus exames estão normais, exceto pela presença de plaquetas de\n5 mil/mm³ (referência 140 mil a 450 mil/mm³). A conduta deve ser:","options":{"A":"Transfundir plaquetas.","B":"Realizar mielograma.","C":"Repetir hemograma.","D":"Realizar tomografia de abdome.","E":"Pesquisar protrombina mutante."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-254732","number":"254732","sourceNumber":"254732","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente, 66 anos, sexo feminino, hipertensa sem tratamento prévio, deu entrada no\nsetor de urgência, com dispneia intensa,\nfrequência cardíaca de 110 BPM, pressão arterial de\n180/100 mmHg, frequência respiratória de 36 IRPM, saturação de oxigênio em ar ambiente de 82%,\nescala de coma de Glasgow 7 (O2V1M4), temperatura axilar 36,5oC, anasarcada e ausculta\npulmonar com estertores crepitantes difusos bilaterais. Aos exames: pH 7.3, HCO3 15 mmol/L,\npCO2 30 mmHg, pO2 40 mmHg, SatO2 80%, creatinina 4 mg/dl (creatinina de doze meses atrás\nigual a 3,5 mg/dl), potássio 7 mEq/L, hemoglobina 8g/dl, leucócitos 7000, plaquetas 200.000. Sobre\no distúrbio do potássio apresentado pela paciente, assinale a alternativa que apresenta medidas\nque podem compor o seu tratamento.","options":{"A":"Sulfato de magnésio, ipratrópio e hemodiálise.","B":"Gluconato de cálcio, espironolactona e furosemida.","C":"Gluconato de cálcio, poliestirenossulfonato de cálcio e hemodiálise.","D":"Sulfato de magnésio, beta-2 agonista inalatório e flumazenil.","E":"Gluconato de cálcio, corticoide inalatório e hemodiálise."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-216158","number":"216158","sourceNumber":"216158","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre as anemias hemolíticas microangiopáticas é correto afirmar que:","options":{"A":"os critérios primários para diagnóstico de Púrpura Trombocitopênica Trombótica (PTT) são\nanemia hemolítica microangiopática, trombocitose,\nastenia, febre, alterações renais e neurológicas.","B":"a síndrome hemolítico-urêmica (SHU) caracteriza-se por anemia hemolítica microangiopática,\ninsuficiência hepática aguda e trombocitopenia.\nMais comum em crianças após uma diarreia por\nClostridium.","C":"a Síndrome HELLP á caracterizada por hemólise, elevação de escorias nitrogenadas e\ntrombocitopenia e se caracteriza por náuseas, hipertensão e reflexos tendinosos rápidos.","D":"a causa mais frequente de Púrpura Trombocitopênica Trombótica (PTT) adquirida são\nanticorpos que se dirigem contra a ADAMTS-13,\ncom forte redução da atividade desta protease na\nclivagem do fator de von Willebrand.","E":"os principais fatores de risco para Púrpura Trombocitopênica Trombótica (PTT) são etnia branca,\nsexo masculino, obesidade e idade entre 30 e 60\nanos."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-216097","number":"216097","sourceNumber":"216097","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre os distúrbios plaquetários, a alternativa que corresponde àquela em que há\ndeficiência da glicoproteína do complexo GpIb/V/IX é:","options":{"A":"Von Willebrand.","B":"Trombastenia de Glanzmann.","C":"Bernard-Soulier.","D":"Síndrome de Diamond-Blackfan.","E":"Síndrome de Evans."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-181954","number":"181954","sourceNumber":"181954","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"No caso de Trombocitopenia <100.000, o exame indicado para avaliação diagnóstica é:","options":{"A":"Mielograma","B":"Dosagem B12","C":"Esfregaço sangue periférico","D":"Dosagem de trombopoietina","E":"Biópsia de medula óssea"},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-181779","number":"181779","sourceNumber":"181779","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Criança de 4 anos de idade, previamente hígida, é levada ao pronto atendimento\ndevido aparecimento de equimoses e petéquias pelo\ncorpo há 2 dias. Mãe nega sintomas\nconstitucionais e relata quadro de infecção de vias aéreas superiores há uma semana. Ao exame\nfísico, criança estrófica, em bom estado geral, ausência de hepatoesplenomegalia ou\nadenomegalia. Solicitado hemograma que demonstrou plaquetas de 25.000, sem outras alterações.\nEsfregaço sanguíneo com aumento de volume de algumas plaquetas, sem outras alterações. Sobre\no caso descrito, é CORRETO afirmar que:","options":{"A":"Trata-se de um caso de trombocitopenia imune primária, estando indicado mielograma para\nconfirmação diagnóstica.","B":"Está indicada transfusão de plaquetas para o paciente, tendo em vista o alto risco de\nsangramento secundário à plaquetopenia.","C":"Trata-se de um caso de trombocitopenia imune primária, sendo indicada internação hospitalar e\npulsoterapia com metilprednisolona.","D":"O paciente apresenta sinal de alerta para doença neoplásica, sendo obrigatória a realização de\nmielograma e sorologias para afastar infecção.","E":"Trata-se de um caso de trombocitopenia imune primária, podendo ser acompanhado\nambulatorialmente em serviço de hematologia."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-159907","number":"159907","sourceNumber":"159907","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente do sexo masculino dá entrada no hospital com quadro de crise convulsiva e\nconfusão mental. Ao exame clínico, o paciente apresentava-se hipocorado, com petéquias,\nequimoses e hemorragia conjuntival, sem outras alterações. Quanto ao exame neurológico,\nevidenciado alteração do nível de consciência e ausência de sinais neurológicos focais. Tomografia\ncomputadorizada de crânio normal e Eletroencefalograma (EEG) normal. Na análise laboratorial,\nforam encontrados anemia, plaquetopenia, aumento de Desidrogenase Láctica (DHL) e presença\nde esquizócitos. O diagnóstico etiológico, nesse caso, é:","options":{"A":"Epilepsia.","B":"Acidente vascular cerebral isquêmico.","C":"Neoplasia hematológica com metástase cerebral.","D":"Púrpura trombocitopênica trombótica.","E":"Anemia falciforme."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-139517","number":"139517","sourceNumber":"139517","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"A acidose metabólica pode ser inicialmente causada por:","options":{"A":"Doença pulmonar obstrutiva crônica.","B":"Ansiedade excessiva.","C":"Hiiperaldosteronismo.","D":"Intoxicação por acido salicílico.","E":"Uso abusivo ou prolongado de diuréticos."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-134634","number":"134634","sourceNumber":"134634","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"O principal teste laboratorial para diagnóstico da principal coagulopatia hereditária\nligada ao cromossomo X é:","options":{"A":"TS.","B":"TC.","C":"TAP.","D":"TTPa.","E":"TT."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-104669","number":"104669","sourceNumber":"104669","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente do sexo masculino, 68 anos, chegou ao pronto-socorro com quadro de choque\nhipovolêmico (torpor, pressão arterial: 70 x 50 mmHg, enchimento capilar retardado, pele fria e\noligúria) após 3 dias de diarreia intensa. Durante avaliação no pronto-socorro, enquanto recebia\nressuscitação volêmica com cristaloides e aguardava o resultado dos exames laboratoriais, foi\nrealizado um eletrocardiograma que evidenciou a seguinte alteração: (VER IMAGEM)\nConsiderando o exposto acima, o resultado de exame laboratorial compatível com o quadro clínico\nE responsável pela alteração eletrocardiográfica evidenciada é:","options":{"A":"pH: 7,22 / Bicarbonato: 12.","B":"Potássio: 2,7.","C":"Potássio: 6,8.","D":"Magnésio: 1,4.","E":"Creatinina: 3,4."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-19/104669.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-88087","number":"88087","sourceNumber":"88087","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 21 anos estava numa festa e chega ao serviço com rebaixamento do nível\nde consciência. Amigos informam que o quadro foi precedido por náusea, vômitos e fortes dores\nabdominais. No exame físico destaca-se taquipneia severa. FC: 120 bpm; TA: 80 x 40 mmHg;\nagitação psicomotora. Exame laboratorial: Gasimetria arterial: pH: 7,10 PO2: 70 mmHg PCO2: 15\nmmHg. Na: 140: K : 5,5; Cl: 100; HCO3: 10. Com relação à acidose metabólica, é INCORRETO\nafirmar:","options":{"A":"O cálculo do AG para este caso será necessário para definir o tipo de acidose metabólica e a\nmelhor forma de tratamento.","B":"Trata-se de acidose metabólica normoclorêmica, uma vez que apresenta AG normal.","C":"Trata-se de acidose metabólica normoclorêmica, uma vez que apresenta AG elevado.","D":"Trata-se de acidose metabólica normoclorêmica, que tem como causa o excesso de ácidos\norgânicos, tais como láctico, cetoacidose, uremia.","E":"O uso de bicarbonato de sódio poderia piorar a acidose metabólica, já que há possibilidade de\nacidose láctica."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-88085","number":"88085","sourceNumber":"88085","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 43 anos, 60 kg, internada por alteração de consciência, em regular estado\ngeral, abertura ocular a estímulo doloroso,\nresposta verbal ausente, resposta motora de localizar a\ndor, euvolêmica, PA: 120 x 80 mmHg; Glicemia capilar 110 mg/dl; Laboratório mostrando Na: 110\nmEq/L; Ao repor o sódio com 300 ml de Cloreto de sódio a 3%, o sódio sérico variará,\naproximadamente, em:","options":{"A":"10 mEq/L.","B":"8 mEq/L.","C":"6 mEq/L.","D":"4 mEq/L.","E":"2 mEq/L."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-64175","number":"64175","sourceNumber":"64175","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"A hiponatremia hipertônica resulta do desvio de água das células para o meio\nextracelular, devido ao confinamento de solutos\nnesse compartimento. A causa mais comum dessa\nalteração é a:","options":{"A":"hipercalemia.","B":"hiperglicemia","C":"hiperlipidemia.","D":"hiperproteinemia.","E":"hipertrigliceridemia."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-68459","number":"68459","sourceNumber":"68459","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Não constituem fator determinante de alterações hidroeletrolíticas no pós-operatório as\nperdas:","options":{"A":"renais.","B":"cardiológicas.","C":"digestivas.","D":"insensíveis.","E":"ocultas e sequestro."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-68506","number":"68506","sourceNumber":"68506","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"A respeito da hiponatremia, é CORRETO afirmar:","options":{"A":"É um distúrbio eletrolítico pouco observado em idosos hospitalizados.","B":"A paroxetina causa hiponatremia mediada por secreção inapropriada de hormônio antidiurético.","C":"Os achados de hiponatremia não têm relação com a gravidade da doença crônica de base.","D":"Quando decorre de hiperproteinemia ou hiperlipidemia graves, encontra-se osmolaridade sérica\naumentada.","E":"Os tiazídicos são os diuréticos menos frequentemente associados à hiponatremia."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-64204","number":"64204","sourceNumber":"64204","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Os distúrbios hidroeletrolíticos são frequentes em crianças devido a várias causas,\ncomo vômitos, diarreia e febre. Na hiponatremia,\nocorre excesso de água em relação ao sódio no\ncompartimento extracelular, aumento da oferta ou redução de excreção de água livre. A natremia\nvaria de 135 a 145 mEq/L e a hiponatremia é considerada grave quando é menor que:","options":{"A":"115 mEq/L.","B":"125 mEq/L.","C":"135 mEq/L.","D":"120 mEq/L.","E":"130 mEq/L."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-50135","number":"50135","sourceNumber":"50135","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Dentre os distúrbios hidroeletrolíticos e acidobásicos abaixo referidos, qual deles pode\nexigir o uso de gluconato de cálcio endovenoso para o seu manejo?","options":{"A":"Hipercalemia.","B":"Hiponatremia.","C":"Hipernatremia.","D":"Acidose metabólica.","E":"Hipocalemia."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-50612","number":"50612","sourceNumber":"50612","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Uma mulher com 33 anos de idade tem uma história de litíase renal recorrente com\ncálculos contendo cálcio ao longo dos últimos\nseis anos. Uma avaliação prévia incluiu uma\nconcentração de cálcio normal e uma taxa de excreção de cálcio urinário de 24 horas normal. Ela é\nvista hoje por causa de outro episódio de dor no flanco direito. Uma radiografia de abdome e da\npelve mostra um cálculo renal radiopaco na junção ureteropélvica direita. Exames laboratoriais:\nureia sérica: 56 mg/dl; creatinina sérica: 1,0 mg/dl; sódio sérico: 138 mEq/L; potássio sérico: 3,3\nmEq/L; cloro sérico: 110 mEq/L e bicarbonato sérico: 18 mEq/L. Qual das seguintes avaliações\nurinárias seria mais provável de sugerir a causa correta do distúrbio?","options":{"A":"Razão cálcio/creatinina e citratúria em amostras de 24 horas.","B":"Gradiente transtubular de potássio e excreção fracional de ácido úrico.","C":"Obter uma amostra de urina de 24 horas para sódio, potássio e uma excreção de aldosterona na\nvigência de sobrecarga oral de sal.","D":"pH."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-50600","number":"50600","sourceNumber":"50600","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 27 anos, do sexo masculino, com quadro de vômitos frequentes e\n\npós-prandiais, com início há seis meses, associado a emagrecimento e tosse. Informa ulcerorrafia\npéptica há dois anos. Qual alteração\nmetabólica que se espera encontrar neste doente?","options":{"A":"Acidose metabólica hiperpotassêmica.","B":"Alcalose metabólica hipoclorêmica.","C":"Alcalose respiratória hiperclorêmica.","D":"Acidose respiratória hiperpotassêmica."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-352652","number":"352652","sourceNumber":"352652","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Criança com 2 anos de idade, levada ao pronto-socorro com quadro de manchas roxas\nno corpo, especialmente em membros\ninferiores, além de epistaxe; sem febre, adinamia ou dores\nósseas. Antecedente recente de infecção viral em vias aéreas superiores. Ao exame com bom\nestado geral, petéquias em todo corpo, hematomas em coxas e pernas, restante exame físico\nnormal. Exames laboratoriais: Hb 11g/dL, Ht 33%, reticulócitos 1%, leucócitos 6900/mm3 (basófilos\n1%, eosinófilos 1%, segmentados 31%, linfócitos típicos 57% e atípicos 5%, monócitos 5%);\nplaquetas 8.000/mm3; morfologia de hemácias e plaquetas normais; DHL e função renal normais.\nQual o diagnóstico mais provável neste caso?","options":{"A":"Púrpura trombocitopênica trombótica.","B":"Púrpura trombocitopênica imunológica.","C":"Leucemia aguda.","D":"Hemofilia A.","E":"Hemofilia B."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-344826","number":"344826","sourceNumber":"344826","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"A classe de anticoagulantes é parte fundamental do tratamento agudo de eventos\ntrombóticos arteriais e venosos, representando uma opção para o tratamento em longo prazo e\npara a prevenção de eventos tromboembólicos venosos e intracavitários. Sobre as indicações\nclínicas dos anticoagulantes orais, observe as afirmativas a seguir.","options":{"A":"A introdução de anticoagulantes orais de ação direta (DOACs) demonstrou maior segurança e\npossibilitou a substituição dos antagonistas da vitamina K (AVKs) em muitos cenários clínicos.\nEntretando, existe situações clínicas não bem estabelecidas com os DOACs, como a FA valvar\n(estenose mitral moderada/importante ou prótese valvar mecânica), CICr <15mL/min e na presença\nde gestação.","B":"A concomitância de dois grupos de doenças trombóticas (FA e doença arterial coronariana\naguda recente), apresenta indicação de\nanticoagulantes orais e também de antiagregação\nplaquetária após 1 ano pós-síndrome coronariana aguda, sem implicar no aumento do risco de\nsangramento.","C":"A anticoagulação oral (ACO) é recomendada para prevenção de AVC em pacientes com FA com\npontuação CHA2DS2-VASc?2 em mulheres ou ?3 em homens, e deve ser considerada em\npacientes com pontuação CHA2DS2-VASc de 1 em mulheres ou 2 em homens, com tratamento\nindividualizado com base no benefício clínico.","D":"De acordo com as recomendações atuais, o uso de Dabigatrana 150mg, 2x/dia e Apixabana\n5mg, 2x/dia, podem prescindir a terapia\nparenteral inicial, no tratamento de TEV.","E":"Há recomendação formal de DOACs na rotina pós-síndrome coronária aguda, FA não valvar de\nalto risco, trombose venosa profunda e profilaxia de TEV em paciente submetido à artroplastia de\nquadril."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-341101","number":"341101","sourceNumber":"341101","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre hemofilia, assinale alternativa correta:","options":{"A":"A hemofilia é um distúrbio genético recessivo ligado ao sexo, que se caracteriza pela ausência\nou deficiência do fator VII (hemofilia A ou\nhemofilia clássica) ou do fator IX (hemofilia B ou doença\nde Christmas)","B":"Quando ocorre sangramento para dentro do músculo iliopsoas, o quadril é mantido em flexão por\ncausa da dor, resultando em contratura em flexão dessa articulação. A rotação do quadril é\npreservada, o que diferencia esse problema da hemartrose ou de outras causas de sinovite do\nquadril.","C":"A hemartrose mesmo recorrente não resulta em artrite crônica. As articulações afetadas\ncontinuam tumefatas, e surgem deformidades em\nflexão. O movimento articular pode estar restrito,\ne a função, fracamente limitada.","D":"A hemartrose surge antes de 1 ano de idade, quando a criança começa a andar e a correr. Em\nordem de frequência, as articulações afetadas mais comumente são joelhos, tornozelos, cotovelos,\nombros e quadris. As pequenas articulações das mãos e dos pés são acometidas ocasionalmente.","E":"A hemofilia A constitui cerca de 15% dos casos. A hemartrose espontânea é um problema\ncomum em ambos os tipos de hemofilia e pode dar origem a uma artrite deformante crônica."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-343056","number":"343056","sourceNumber":"343056","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Pré-escolar com 3 anos de idade, masculino, comparece ao PA por manchas roxas no\ncorpo há 7 dias e nas últimas 24 horas apresentou uma mancha na boca. A mãe relata que a\ncriança não apresentou mais nenhum outro sinal ou sintoma e que tem histórico de rinite alérgica.\nNa avaliação o médico identificou criança com bom estado geral, sem palidez de pele e mucosas,\nhidratado, eupneico, ausência de icterícia, ativo e reativo. Ausência de linfoadenomegalia e\nabdome sem visceromegalias. Na pele havia petéquias, púrpuras e equimoses em membros\ninferiores, abdome e tronco, além de presença de petéquias em palato e pequeno coágulo na\ngengiva. Solicitou um hemograma e o resultado apresentou os seguintes achados laboratoriais:\nHemácias 4.2x 10?; Hemoglobina 12.1 g/dl; Hematócrito 36%; leucócitos totais: 8.000/mm³, com\nsegmentados 40%; eosinófilos 10%; basófilos 0%; linfócitos típicos 46%, linfócitos atípicos 0%;\nmonócitos 4%; plaquetas: 18.000/mm³ ao analisar o quadro clínico e os achados laboratoriais,\nconsiderando a hipótese diagnóstica mais plausível, qual a conduta MAIS RECOMENDADA a ser\nseguida nesse contexto:","options":{"A":"A conduta seria solicitar mielograma para afastar leucemia e após, iniciar tratamento com\npulsoterapia com dexametasona.","B":"A conduta seria prednisona oral na dose de 1 a 3 mg/kg/dia, e acompanhar ambulatorialmente.","C":"A conduta seria pulsoterapia com metilprednisolona associada a transfusão de concentrado de\nplaquetas.","D":"prednisona oral na dose de 1 a 3 mg/kg/dia, associada a transfusão de plaquetas.","E":"A conduta seria expectante, sem medicamento e se apresentar sangramento, fazer transfusão\nde plaquetas."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-225849","number":"225849","sourceNumber":"225849","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre as indicações clínicas para o uso de componentes sanguíneos, marque a\nalternativa incorreta:","options":{"A":"Está indicado transfusão de hemácias em pacientes com hemoglobina < 8 g/dL ou perda aguda\nde sangue em paciente saudável, com sinais ou\nsintomas de diminuição de oferta de oxigênio.","B":"Está indicado transfusão de hemácias em pacientes com hemoglobina < 10 g/dL em pacientes\nque sabidamente tem risco aumentado de doença\narterial coronariana que tiveram ou esperam que\nvenham a ter hemorragia significativa.","C":"Transfusão de hemácias em pacientes assintomáticos, estáveis, com hemoglobina entre 7 g/dL\ne 10 g/dL, apresenta indicação questionável\nou sem fundamento.","D":"Deveremos usar transfusão de plaquetas (para profilaxia) em pacientes com contagem recente\n(menos de 24 horas) < 50.000/mm³.","E":"Transfusão de plasma não é justificada para reposição de volume, suplementação nutricional e\nhipoalbuminemia."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-254132","number":"254132","sourceNumber":"254132","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente jovem, 32 anos, admitido com febre, fraqueza, confusão mental e dispneia de\nevolução há 1 semana. Apresenta-se no momento sonolento, taquidispneico (24 irpm) e\ntaquicárdico (115 bpm). PA 120/70 mmHg, com laboratório evidenciando hematúria e leucocitúria,\nanemia (HB 5,7 g/dl) e plaquetopenia grave (20.000/mm3). Contagem de reticulócitos aumentada\n(15%) com lâmina de sangue periférico demonstrando esquizócitos. Coombs direto negativo, DHL\naumentada 4.500 UI/L). Aguardando painel sorológico e autoanticorpos, incluindo atividade\nADAMTS13 e anticorpos ADAMTS13. Qual sua conduta?","options":{"A":"Transfusão de plaquetas baseada no nível sérico reduzido que apresenta.","B":"Realizar plasmaférese imediata.","C":"Iniciar metotrexato associado a corticoterapia e cobertura antibiótica ampla.","D":"Pulsoterapia com metilprednisolona deve ser a primeira medida adotada.","E":"Gamaglobulina humana deverá ser utilizada apenas em caso de falha as medidas acima\ndescritas."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-240990","number":"240990","sourceNumber":"240990","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Escolar de 6 anos admitido em emergência pediátrica com relato de equimoses em\npernas e abdome há uma semana e epistaxe\nvolumosa hoje pela manhã. A mãe nega outras\nqueixas atuais e conta que há duas semanas teve quadro de febre e coriza nasal com resolução\nespontânea só com uso de sintomáticos. Exame físico normal exceto pelas sufusões hemorrágicas.\nO hemograma realizado na emergência mostra apenas plaquetopenia 35000 e hemoglobina\n10,5g/dl. O diagnóstico mais provável é:","options":{"A":"Púrpura de Henoch-Schonlein.","B":"Leucemia Linfoide Aguda.","C":"Leishmaniose Visceral.","D":"Púrpura Trombocitopênica Autoimune.","E":"Hemoglobinúria paroxística noturna."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-212525","number":"212525","sourceNumber":"212525","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Mulher, 41 anos, com quadro há 1 semana de febre, mal-estar, palidez\n\ncutâneo-mucosa e episódios de desorientação. Laboratório evidenciou: Hb = 6,5 g/dl (normocítica e\nnormocrômica), leucócitos = 8.500/mm³, sem alterações significativas na contagem diferencial,\nplaquetas = 54.000/mm³, DHL = 1.230 UI/L, reticulócitos = 16%, creatinina = 1,6 mg/dl.\n\nHematoscopia evidenciou presença de esquizócitos em abundância. Tempo de protrombina e TTPa\ninalterados. Em relação ao caso, assinale a alternativa CORRETA.","options":{"A":"A melhor opção terapêutica para o caso é pulsoterapia com metilprednisolona.","B":"O quadro tende a ser autolimitado e de baixa letalidade, sendo a conduta expectante a mais\nadequada.","C":"A hemólise evidenciada neste caso é predominantemente intravascular, cursando com aumento\nda haptoglobina, hemoglobinúria e\nhemossiderinúria.","D":"O diagnóstico mais apropriado neste caso é CIVD associado à sepse, devendo-se tratar a\ninfecção de base.","E":"A paciente deverá ser encaminhada para realização de plasmaférese."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-177192","number":"177192","sourceNumber":"177192","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre a fisiologia e distúrbios plaquetários, assinale a resposta ERRADA:","options":{"A":"A trombina é um fator de crescimento presente no plasma, produzido no fígado, rins e medula\nóssea, sendo o principal hormônio envolvido na megacariopoese, regulando a produção de\nplaquetas.","B":"Algumas situações clínicas como a PTI, trombocitopenia induzida por drogas, diabetes e doença\ncoronariana, podem favorecer uma diminuição na sobrevida das plaquetas.","C":"O baço funciona como uma reserva fisiológica das plaquetas, e a esplenectomia prolonga a vida\ndas mesmas com consequente trombocitose.","D":"A Púrpura Trombocitopênica Imune (PTI) pode ser associada a doenças como lúpus eritematoso\nsistêmico, doenças autoimunes da tireoide, doença linfoproliferativa, infecções pelo HIV, ou por\nHelicobacter pylori.","E":"Pacientes com PTI com contagem de plaquetas abaixo de 50.000 devem receber transfusões de\nconcentrados de plaquetas lavadas com a finalidade de prevenir sangramentos, mesmo estando\nassintomáticos, como também evitar imunizações com reações transfusionais futuras."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-185336","number":"185336","sourceNumber":"185336","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"A púrpura de Bernard-Soulier é uma doença genética da hemostasia primária que é\ncausada por uma deficiência do receptor\nplaquetário (1) , o qual tem afinidade pelo (2)\n\n. Os termos que completam adequadamente as lacunas (1) e (2) são\nrespectivamente: Marque a alternativa que completa\nCORRETAMENTE, os espaços em branco.","options":{"A":"PAR; trombina.","B":"GP Ib; fator de von Willebrand.","C":"GP IIb/IIIa; fator de von Willebrand.","D":"GP IIb/IIIa; fibrinogênio.","E":"P2Y12; ADP."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-160646","number":"160646","sourceNumber":"160646","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"A fisiopatologia da púrpura trombocitopênica trombótica está centralmente descrita na\nseguinte assertiva:","options":{"A":"Acúmulo de multímeros do fator de von Willebrand por inibição da ADAMTS13.","B":"Ativação plaquetária patológica pela presença de anticorpos anti-PF4.","C":"Liberação endotelial excessiva do Inibidor do Ativador do Plasminogênio - PAI.","D":"Liberação endotelial excessiva do fator tecidual.","E":"Degradação nas células endoteliais dos corpúsculos de Weibel-Palade por serinoproteases."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-138539","number":"138539","sourceNumber":"138539","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Homem, 44 anos, no segundo dia de internação por acidente crotálico, evoluindo com\noligoanúria, urina vinhosa e surgimento de palpitações. Última creatinina de 4,8 mg/dl. O serviço\nnão estava dosando eletrólitos e o médico plantonista, suspeitando de distúrbio hidroeletrolítico\nespecífico, decidiu fazer um ECG, o qual está representado na figura abaixo. (VER IMAGEM)\nDiante desta situação, a conduta terapêutica indicada é:","options":{"A":"Iniciar reposição de potássio.","B":"Administrar gluconato de cálcio.","C":"Cardioversão elétrica.","D":"Colocação de marca-passo venoso.","E":"Administrar bicarbonato de sódio."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-19/138539.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-134916","number":"134916","sourceNumber":"134916","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Na anticoagulação de pacientes com tromboses de repetição, qual grupo de\nmedicações pode interferir com o uso de cumarínicos?","options":{"A":"Isoniazida, fenitoína, azatioprina, espironolactona.","B":"Ciclosporina, cloroquina, omeprazol, aspirina.","C":"Ciclofosfamida, amiodarona, clopidogrel, losartana.","D":"Propranolol, alopurinol, ranitidina, levotiroxina.","E":"Fluconazol, fenobarbital, tiazídicos, diclofenaco."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-139009","number":"139009","sourceNumber":"139009","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Diante de paciente euvolêmico com osmolaridade sérica reduzida, qual a causa de\nhiponatremia mais provável?","options":{"A":"Síndrome de secreção inapropriada do ADH.","B":"Síndrome nefrótica.","C":"Diarreia.","D":"Hiperglicemia.","E":"Insuficiência renal crônica."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-139045","number":"139045","sourceNumber":"139045","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Analise a seguinte gasometria arterial: pH 7,3; HCO3-: 34 mEq/l; PCO2: 55 mmHg; BE:\n\n+20; AG 5. Qual a PROVÁVEL doença de base dentre as opções abaixo?","options":{"A":"Parada cardiorrespiratória.","B":"Doença pulmonar obstrutiva crônica descompensada.","C":"Hiperventilação.","D":"Paciente sob ventilação mecânica invasiva.","E":"Nenhuma das anteriores."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-109057","number":"109057","sourceNumber":"109057","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Com relação à reposição de potássio por via venosa, um dos aspectos que devem ser\nrespeitados é a concentração de potássio na solução que será infundida. Esta NÃO poderá\nultrapassar, em infusão por via periférica, a concentração máxima de:","options":{"A":"80-100 mEq/L.","B":"100-150 mEq/L.","C":"40-60 mEq/L.","D":"20-30 mEq/L.","E":"10-20 mEq/L."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-109055","number":"109055","sourceNumber":"109055","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Na presença de hiponatremia hipotônica grave e sintomática em adultos, a medida\nterapêutica recomendada, conforme o Consenso Europeu para Manejo da Hiponatremia de 2013,\né:","options":{"A":"Infundir 50 mL de SF 3% em 20 min.","B":"Infundir 100 mL de SF 3% em 20 min.","C":"Infundir 150 mL de SF 3% em 20 min.","D":"Infundir 200 mL de SF 3% em 20 min.","E":"Infundir 250 mL de SF 3% em 20 min."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-85838","number":"85838","sourceNumber":"85838","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Hiponatremia é definida como uma concentração de sódio sérico abaixo de:","options":{"A":"135 mEq/L.","B":"140 mEq/L.","C":"145 mEq/L.","D":"150 mEq/L.","E":"155 mEq/L."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-85861","number":"85861","sourceNumber":"85861","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Assinale a alternativa que contém o diagnóstico mais provavelmente associado aos\nseguintes dados obtidos a partir da gasometria arterial, perfil eletrolítico sérico e urinário de um\ndeterminado paciente: Gasometria arterial: pH = 7,20; HCO3- = 14 mEq/L; pCO2 = 29 mmHg; pO2\n\n= 98 mmHg; BE = -8 mEq/L. Ionograma sérico: sódio = 140 mEq/L; potássio = 4,0 mEq/L; cloreto =\n125 mEq/L. Ionograma urinário: sódio = 22\nmEq/L; potássio = 2,0 mEq/L; cloreto = 44 mEq/L.","options":{"A":"Insuficiência respiratória crônica agudizada.","B":"Intoxicação por metanol.","C":"Vômitos de repetição.","D":"Uso de acetazolamida.","E":"Diarreia severa."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-85867","number":"85867","sourceNumber":"85867","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Homem de 70 anos, acamado há três anos após Acidente Vascular Isquêmico,\ndependendo de terceiros para alimentar-se e\nrealizar a própria higiene, é trazido para o setor de\nemergência do Hospital Universitário Alcides Carneiro com quadro há dois dias de mudança do\nestado mental, caracterizado por surtos de agressividade, agitação psicomotora e discurso\ndesconexo, com alheamento ao ambiente e ao examinador. Exames realizados no setor de\nemergência evidenciaram sódio sérico de 160 mEq/L. Conforme a fórmula de Adrogué,\nconsiderando o índice de água corporal de 0,50 e peso corporal de 78 kg a quantidade de SG 5%\nque deverá ser infundida em 24 horas, com o objetivo de diminuir o sódio sérico em 10 mEq/L, é\nde:","options":{"A":"2.500 ml.","B":"2.400 ml.","C":"2.300 ml.","D":"2.200 ml.","E":"2.100 ml."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-68135","number":"68135","sourceNumber":"68135","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Qual das seguintes condições clínicas causaria tipicamente uma acidose metabólica\ncom anion gap ou hiato aniônico aumentado?","options":{"A":"Choque cardiogênico","B":"Abuso de heroína","C":"Miastenia gravis","D":"Gestação normal","E":"Uso de diuréticos"},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-68115","number":"68115","sourceNumber":"68115","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre a hipercalemia encontrada em pacientes submetidos à cirurgia digestiva de\ngrande porte, marque a alternativa INCORRETA:","options":{"A":"A hipercalemia na faixa de 6 a 7 mmol/L pode estar associada a ondas T elevadas.","B":"Ondas T apiculadas e simétricas indicam hipercalemia perigosa.","C":"Quando excede 7 mmol/L, as amplitudes da onda P aumentam, os segmentos PR aumentam e\no complexo QRS fica alargado.","D":"A disfunção ou insuficiência renal de início agudo é a causa mais comum de hipercalemia de\ninício rápido.","E":"O tratamento com bicarbonato é mais efetivo em pacientes hipercalcêmicos com acidose\nmetabólica."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-36682","number":"36682","sourceNumber":"36682","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Qual das causas de hiponatremia citadas abaixo é a mais provável para um paciente\nque se encontre euvolêmico e com a\nosmolalidade sanguínea baixa?","options":{"A":"Síndrome da secreção inapropriada do ADH.","B":"Síndrome nefrótica.","C":"Diarreia.","D":"Hiperglicemia.","E":"Insuficiência renal crônica."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-351042","number":"351042","sourceNumber":"351042","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Pré escolar de 3 anos desenvolve após semanas de uma exposição viral início súbito\nde petéquias generalizadas e púrpura, epistaxe\nde pequeno volume. Restante do exame físico sem\nalterações. Hemograma com série vermelha e leucócitos normais, contagem de plaquetas de\n10.000/ mm3. Sobre esta situação analise as afirmativas abaixo. I ? A presença de hemorragia\ngrave é comum e deve ser tratada com transfusão de plaquetas. II ? O uso de um tratamento\nprecoce com corticoides aumenta a chance de remissão completa da doença. III ? A análise da\nmedula óssea mostra as séries granulocíticas e eritrocitárias normais e contagem de\nmegacariócitos diminuída. Sobre esta situação selecione a opção correta.","options":{"A":"As afirmativas I e II são verdadeiras. A afirmativa III é falsa.","B":"As afirmativas I e III são verdadeiras. A afirmativa II é falsa.","C":"As afirmativas II e III são verdadeiras. A afirmativa I é falsa.","D":"As afirmativas I, II e III são verdadeiras.","E":"As afirmativas I, II e III são falsas."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-232657","number":"232657","sourceNumber":"232657","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Menina de 4 anos com episódio de queda há 3 dias com trauma contuso em lábio\ninferior que permaneceu com sangramento ativo\npor dois dias. Relata episódio de sangramento\nanterior por dois dias há 2 anos na queda de um dente. Ao exame, hematomas difusos em\nmembros inferiores. Exames mostram hemograma normal, plaquetas de 190.000, tempo de\nprotrombina de 13 segundos, tempo de tromboplastina parcial ativada de 50 segundos, fibrinogênio\nde 200 mg/dl. O diagnóstico mais provável para esta paciente é:","options":{"A":"Hemofilia A.","B":"Hemofilia B.","C":"Afibrinogenemia.","D":"Doença de von Willebrand.","E":"Síndrome de Bernard-Soulier."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-232725","number":"232725","sourceNumber":"232725","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Analise os casos a seguir: I. Paciente com sepse de foco pulmonar, apresentando Hb =\n8 g/dl. II. Paciente com neutropenia\nfebril, pós-quimioterapia, apresentando 4.800 plaquetas/µl. III.\nPaciente com fratura do colo do fêmur, apresentando 65.000 plaquetas/µl. IV. Paciente em uso de\nwarfarina, com sangramento gastrointestinal maciço. Apresentam indicação de transfusão de\nhemocomponente apenas:","options":{"A":"Pacientes I e II.","B":"Pacientes I e III.","C":"Pacientes II e III.","D":"Pacientes II e IV.","E":"Pacientes III e IV."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-174248","number":"174248","sourceNumber":"174248","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Qual a conduta atualmente recomendada para um lactente de onze meses com\ntrombocitopenia imune primária e com número de plaquetas de 10.000 e sem sangramento ativo?\npg. 1621 (SBP); pg. 1714 (Nelson)","options":{"A":"expectante.","B":"corticoterapia.","C":"imunoglobulina.","D":"transfusão de plaquetas.","E":"corticoterapia + imunoglobulina."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-148939","number":"148939","sourceNumber":"148939","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Assinale VERDADEIRO ou FALSO sobre hemocomponentes e seu uso clínico: I.\n\nDeve-se transfundir concentrados de hemácias em pacientes com hemoglobina menor que 10 g/dl,\nmesmo em pacientes estáveis e sem sangramento agudo; II. O crioprecipitado é proveniente da\ncentrifugação do plasma fresco congelado, sendo rico em fibrinogênio, fator VIII e fator de von\nWillebrand; III. Quando existe indicação de transfusão de plaquetas, deve-se transfundir uma bolsa\nde plaquetas de doador randômico para cada 10 kg de peso corporal do receptor; IV. Espera-se\nque uma unidade de concentrado de hemácias gere um incremento de 6% no hematócrito do\npaciente transfundido; V. O plasma fresco congelado pode ser utilizado para reversão do efeito\nanticoagulante da heparina em pacientes com sangramentos.","options":{"A":"V - F - F - V - V.","B":"F - V - V - F - V.","C":"F - V - V - F - F.","D":"F - V - V - V - F.","E":"V - F - F - V - F."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-78503","number":"78503","sourceNumber":"78503","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente masculino, 50 anos, no 4º pós-operatório de colectomia esquerda eletiva por\ndoença diverticular, ainda em jejum por vômitos persistentes, apresenta quadro de fraqueza, fadiga\ne persistência do íleo paralítico. Exames laboratoriais incluem: hemograma, creatinina e sódio\nnormais com nível sérico de potássio diminuído. Possível causa desta alteração:","options":{"A":"Idade avançada.","B":"Doença diverticular.","C":"Jejum e vômitos persistentes.","D":"Ressecção do segmento colônico.","E":"Anestesia geral com agentes inalatórios."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-58486","number":"58486","sourceNumber":"58486","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente torporoso, taquicárdico, hipotenso, com sódio sérico de 122 mmol/L e sódio\nurinário de 10 mmol/L. Qual das etiologias não é compatível com o caso?","options":{"A":"Vômito.","B":"Diarreia.","C":"Pancreatite aguda.","D":"Queimadura extensa.","E":"Deficiência de mineralocorticoides."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-58500","number":"58500","sourceNumber":"58500","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Os distúrbios no balanço ou na distribuição do sódio e da água, acompanhados por\nalterações no volume ou na composição dos\nsolutos dos fluidos distribuídos nos compartimentos do\ncorpo, estão entre as mais frequentes anomalias encontradas e ocorrem em uma grande variedade\nde quadros clínicos e estados patológicos. A respeito dos processos patogênicos que levam a\ndistúrbios na homeostase corpórea de sódio e água, analise as duas colunas: ( ) Normonatremia\nhipervolêmica. ( ) Hiponatremia hipervolêmica. ( ) Hipernatremia hipervolêmica. ( ) Normonatremia\nhipovolêmica. A. Ganho hipertônico de sódio e água. B. Ganho isotônico de sódio e água. C.\nGanho hipotônico de sódio e água. D. Perda isotônica de sódio e água. Assinale a coluna da direita\nde acordo com sua correspondência com a da esquerda.","options":{"A":"B, C, A, D.","B":"C, B, D, A.","C":"A, D, B, C.","D":"D, A, C, B.","E":"B, A, C, D."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-35027","number":"35027","sourceNumber":"35027","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"A causa MAIS COMUM de hiponatremia hipovolêmica em crianças é:","options":{"A":"Diabetes insipidus.","B":"Síndrome de secreção inadequada de ADH.","C":"Gastroenterite aguda.","D":"Insuficiência cardíaca congestiva.","E":"Síndrome nefrótica."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-35054","number":"35054","sourceNumber":"35054","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Quanto aos distúrbios da homeostase do sódio e da água, assinale a alternativa\nERRADA:","options":{"A":"Distúrbios da água são distúrbios de osmolaridade, manifestados por alterações no sódio\nplasmático ? detectado pela dosagem de sódio no plasma.","B":"Distúrbios do balanço de sódio são distúrbios de volume do espaço extracelular ? detectado pelo\nsimples exame físico: edema ou desidratação.","C":"Hiponatremia ou excesso de água: estado hiposmolar e hipotônico em que o sódio plasmático\nestá abaixo de 135 mEq/L, com edema celular\nneuronal.","D":"Na correção da hiponatremia sintomática do adulto poderemos usar solução salina hipertônica a\n3% - 1-2 ml/kg/hora, mas temos que ter a cautela de não ocasionar a síndrome de desmielinização\nosmótica, quando a correção é muito rápida.","E":"A síndrome do \"bebedor de cerveja\" consiste em hipernatremia hipervolêmica."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-358581","number":"358581","sourceNumber":"358581","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Criança com 2 anos de vida, histórico prévio de diarreia autolimitada há 15 dias, evoluiu\ncom quadro súbito de petéquias no tronco e membros, bom estado geral e sem outros achados no\nexame físico. Hemograma com alteração apenas na contagem de plaquetas - 4.000/mm3 e\npresença de macroplaquetas no esfregaço do sangue periférico. Qual o diagnóstico mais provável?","options":{"A":"Púrpura de Henoch-Schoenlein.","B":"Púrpura amegacariocítica.","C":"Síndrome de Wiskott-Aldrich.","D":"Hemofilia.","E":"Púrpura trombocitopênica imunológica."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-355922","number":"355922","sourceNumber":"355922","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Os anticoagulantes orais com ação direta sobre um fator específico da coagulação\n(DOACs) tiveram sua introdução recente na\nprática clínica sendo os principais representantes: os\ninibidores do fator X ativado (Xa) rivaroxabana, apizaban, edoxabana e o inibidor de trombina\n(dabigatrana). Sobre essas medicações, assinale a alternativa INCORRETA:","options":{"A":"O efeito dos anti-Xa pode ser avaliado através de um exame complementar que é a ?Atividade\nanti-Xa?, porém o método ainda não está prontamente disponível na maioria dos serviços.","B":"Para sangramentos como hematomas de partes moles, gengivorragia ou epistaxe deve-se\nconsiderar a descontinuação da anticoagulação e sua reversão.","C":"A meia vida dos agentes deve sempre ser considerada: 5-9h para rivaroxabana, 8-15h para\napixabana e 6-11h para edoxabana.","D":"Nos sangramentos, agentes antifibrinolíticos como o Ácido tranexâmico devem ser\nconsiderados."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-360966","number":"360966","sourceNumber":"360966","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Em qual das condições abaixo está atualmente contraindicada a utilização de\nanticoagulantes orais diretos (não antagonistas da vitamina K)?","options":{"A":"Fibrilação atrial e insuficiência valvar mitral.","B":"Fibrilação atrial e prótese biológica valvar.","C":"Fibrilação atrial e prótese valvar mecânica.","D":"Fibrilação atrial e insuficiência cardíaca.","E":"Fibrilação atrial e estenose valvar aórtica."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-358516","number":"358516","sourceNumber":"358516","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Durante seu plantão na UTI, você está atendendo um paciente chamado L.F.P, de 62\nanos, portador de Insuficiência Cardíaca com\nfração de ejeção reduzida, internado devido a choque\nséptico de foco pulmonar, em uso de piperacilina- tazobactam 4,5 gramas de 6/6 horas. No\nmomento de sua avaliação, o paciente encontra-se intubado em ventilação mecânica, sob\nmodalidade assistido-controlada, modo VCV, com volume corrente (VC): 360 ml, frequência\nrespiratória (FR): 16 irpm, PEEP: 5 cmH2O, FiO2: 30%, monitorizado hemodinamicamente com\npressão arterial invasiva e pressão venosa central, que estão respectivamente em 112/64 mmHg e\nem 3 cmH?O.Ao checar os exames laboratoriais, você percebe um Hb: 5,6 g/dl, e opta então por\nindicar transfusão de concentrado de hemácias, e solicita três bolsas. Após cerca de 2 horas,\ndurante a infusão da segunda bolsa, você é chamado pela enfermagem, pois o paciente está\ndessaturando. Ao avaliar o paciente, você observa que a SaO? está em 84% e decide então\naumentar a PEEP para 10 cmH?O e a FiO?: 60%, com pouca resposta. Após a sua intervenção,\nvocê avalia os demais parâmetros do paciente e vê que a PA está em 134/88 mmHg e a PVC está\nem 16 cmH?O. Você decide então por realizar um POCUS e vê que ambos os pulmões\napresentam-se com padrão B, com diâmetro de veia cava inferior de 29 mm, sem variabilidade\nrespiratória. Qual o possível diagnóstico e a melhor conduta a ser tomada?","options":{"A":"Provavelmente trata-se de TRALI (Transfusion related acute lung injury), devendo-se parar\nimediatamente a transfusão e notificar o banco de sangue, sendo a terapia de suporte a única\nindicada para este caso.","B":"Deve tratar-se de um quadro de TACO (Transfusion associated circulatory overload), não\nhavendo necessidade de comunicação ao banco de\nsangue por não se tratar de reação\ntransfusional, sendo necessário investigação do paciente com marcadores de necrose miocárdica e\npossível cateterismo cardíaco.","C":"Provavelmente trata-se de TRALI (Transfusion related acute lung injury), devendo-se parar\nimediatamente a transfusão e notificar o banco de sangue, devendo-se iniciar terapia com\ncorticoide, tendo em vista que seu uso de rotina para esses casos associa-se a melhores\n\ndesfechos.","D":"Provavelmente o quadro é de choque cardiogênico, devendo-se iniciar dobutamina a 5\nmcg/kg/min e manter a transfusão do\nconcentrado de hemácias, visto não haver relação do quadro\natual com a transfusão.","E":"Deve tratar-se de um quadro de TACO (Transfusion associated circulatory overload),\ndevendo-se parar a transfusão e ser notificado o\nbanco de sangue, e iniciado estratégia de\ndiureticoterapia com furosemida endovenosa."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-326792","number":"326792","sourceNumber":"326792","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Menino, 3 anos de vida com histórico prévio de IVAS há 15 dias, evoluiu com quadro\nsúbito de petéquias. Hemograma: contagem de\nplaquetas 6.000/mm³ sem outras alterações. Qual o\ndiagnóstico mais provável?","options":{"A":"Púrpura de Henoch-Schoenlein.","B":"Púrpura amegacariocítica.","C":"Púrpura trombocitopênica imunológica.","D":"Leucemia linfoide aguda.","E":"Leucemia mieloide aguda."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-312037","number":"312037","sourceNumber":"312037","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"A varfarina é um anticoagulante oral prescrito para anticoagulação ambulatorial dos\npacientes que possuem diversas doenças como trombose venosa profunda e fibrilação atrial. É\numa medicação barata, amplamente utilizada no SUS, mas que pode sofrer influência de diversos\nfatores como interação com outras medicações e elementos da dieta, requerendo monitorização\nfrequente. Esta monitorização é feita com:","options":{"A":"Um exame que avalie a via extrínseca da coagulação.","B":"Um exame que avalie o número de plaquetas.","C":"Um exame que avalie a via intrínseca da coagulação.","D":"Um exame que avalie a dosagem sérica da vitamina K.","E":"Um exame que avalie a dosagem sérica do fator de von Willebrand."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-304652","number":"304652","sourceNumber":"304652","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre a utilização de sangue e seus componentes na prática médica é incorreto afirmar\nque:","options":{"A":"O sangue total é raramente utilizado","B":"O uso de concentrado de hemácias está indicado no tratamento de ?déficits? sintomáticos da\ncapacidade de transporte de oxigênio e não está indicado na correção da anemia de pacientes\nsintomáticos que não necessitam de aporte imediato de oxigênio.","C":"A transfusão de plaquetas é indicada nos casos de sangramentos que não estejam relacionados\na plaquetopenia/plaquetopatia e em casos em que há\ndestruição plaquetária.","D":"O plasma fresco congelado não deve ser utilizado para expansão volêmica ou suplemento\nnutricional.","E":"Pacientes com anemias carenciais ferropriva ou por deficiências de folatos ou vitamina B12\ncostumam responder muito bem e rapidamente à administração destes medicamentos evitando o\nuso de transfusões."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-314820","number":"314820","sourceNumber":"314820","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Um homem com 37 anos tem trombose venosa profunda sem qualquer fator de risco.\nSeu irmão teve embolia pulmonar com 45 anos,\ne sua mãe teve ?coágulo na perna? aos 30 anos.\nQual das seguintes é a provável doença hereditária desse paciente?","options":{"A":"Deficiência de proteína S.","B":"Mutação do fator V de Leiden.","C":"Síndrome de anticorpo antifosfolípide.","D":"Deficiência de antitrombina III."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-292345","number":"292345","sourceNumber":"292345","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Um paciente adulto em uso de warfarina realizou dosagem de Tempo de Atividade de\nProtrombina (TAP) que apresentou resultado de Relação Normatizada Internacional (RNI) igual a 8.\nO paciente não apresenta sangramento, equimoses ou hematomas. Nesse caso, a conduta\nCORRETA a ser adotada é:","options":{"A":"Suspender a warfarina, administrar vitamina K intramuscular e reintroduzir warfarina quando o\nRNI estiver abaixo de 2.","B":"Reduzir a dose de warfarina em 50% e reavaliar o paciente ambulatorialmente em uma semana\ncom novo TAP/RNI.","C":"Suspender a warfarina, administrar plasma fresco e reintroduzir warfarina com dose ajustada no\ndia seguinte.","D":"Reduzir a dose de warfarina em 25%, administrar vitamina K via oral e reavaliar o paciente em\numa semana com novo TAP/RNI.","E":"Suspender a warfarina e monitorar o TAP/RNI, reintroduzindo a warfarina em dose reduzida,\nassim que o RNI voltar à faixa terapêutica\nindicada."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-313003","number":"313003","sourceNumber":"313003","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"O uso de anticoagulantes orais diretos (DOACs) tem sem ampliado nos últimos anos\npela sua facilidade posológica, segurança e eficácia em uso profilático e terapêutico. Sobre os\nDOACs assinale a alternativa incorreta.","options":{"A":"Agem em sítio específico da coagulação como o fator Xa (rivaroxabana, apixabana, edoxabana)\nou lla (dabigatrana).","B":"A indisponibilidade de antídotos em nosso meio pode ser considerada um fator limitante ao seu\nuso.","C":"Alteração na função renal limita o seu uso, sendo a apixabana o de menor excreção por essa\nvia.","D":"Em caso de sangramento esse pode ser facilmente revertido com uso de derivados de plasma.","E":"Seu uso vem sendo cada vez mais ampliado, sendo utilizadas em profilaxia e tratamento de\ntromboembolismo venoso, prevenção de embolias em pacientes com Fibrilação Atrial, entre outros."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-292348","number":"292348","sourceNumber":"292348","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 72 anos, sexo masculino, foi internado por anemia sintomática, com\ndosagem de hemoglobina sérica de 6 g/dl. O\nmédico plantonista solicitou a transfusão de 3\nunidades de Concentrado de Hemácias (CH) na tarde de hoje. Você é acionado(a) para reavaliar o\npaciente logo no início da transfusão da terceira unidade de CH, por ele apresentar quadro de\ndispneia, iniciada durante a transfusão da segunda unidade de CH, com necessidade de oxigênio\nsuplementar, associada a taquicardia e elevação da pressão arterial, sem febre ou outras queixas.\nAlém da avaliação radiológica complementar, frente ao quadro clínico apresentado, o diagnóstico\nprovável e a conduta CORRETA são, respectivamente:","options":{"A":"Reação transfusional hemolítica ? suspensão da transfusão e administração de\nmetilprednisolona.","B":"Lesão pulmonar aguda associada à transfusão (TRALI) ? suspensão da transfusão e\nadministração de metilprednisolona.","C":"Congestão pulmonar associada à transfusão (TACO) ? suspensão da transfusão e\nadministração de diurético.","D":"Lesão pulmonar aguda associada à transfusão (TRALI) ? administração de metilprednisolona e\ncontinuidade da transfusão.","E":"Congestão pulmonar associada à transfusão (TACO) ? administração de diurético e continuidade\nda transfusão."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-314844","number":"314844","sourceNumber":"314844","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Criança de 5 anos é levada à emergência por apresentar episódios repetidos de\nsangramento nasal espontâneo na última\nsemana. Mãe refere que paciente apresentou quadro\ngripal leve há 15 dias com total recuperação. Ao exame físico, paciente está em bom estado geral,\nafebril, anictérica e acianótica. Bulhas rítmicas, normofonéticas e sem sopros cardíacos. Ausculta\npulmonar sem alterações. Fígado palpável no rebordo costal direito, baço não palpável, ruídos\nhidroaéreos abdominais presentes e normais. Petéquias em tronco, membros e face em moderada\nquantidade. Com base nos dados anteriores, assinale a alternativa que melhor se aplica:","options":{"A":"Como a criança está em bom estado geral, dispenso a criança para casa orientando retorno\ncaso o sangramento se torne importante.","B":"Solicito hemograma para confirmar Púrpura Trombocitopênica Idiopática (PTI), que seria a\nprincipal hipótese diagnóstica.","C":"Solicito hemograma, eletrólitos e gasometria arterial, visto ser a principal hipótese\nmeningococcemia grave.","D":"Como o fígado é palpável no rebordo costal direito, a principal hipótese é leucemia aguda e\nsolicito mielograma imediatamente."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-304684","number":"304684","sourceNumber":"304684","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente masculino, 17 anos, pardo, estudante, procura atendimento em UPA com\nquadro de sangramento gengival ao escovar\nos dentes iniciado há 3 dias. Há 8 dias vinha\npercebendo equimoses frequentes nas pernas mas atribuiu aos treinos intensos para prova de\ntriathlon Ironman. Há 1 dia vem observando urina avermelhada mas sem alteração de volume nem\nodor. Há 3 semanas apresentou quadro respiratório agudo, no segundo dia de sintomas coletou\nswab nasofaríngeo para PCR de vírus respiratórios que resultou negativo para coronavírus mas\npositivo para rinovírus. Traz um hemograma solicitado na UBS que mostrava:Hb 12,9; VG 37,2;\nVCM 90,6; HCM 29,5; leucócitos 4500, diferencial normal, plaquetas 35.000. Sobre o caso acima,\nassinale a alternativa correta sobre o provável diagnóstico e abordagem inicial:","options":{"A":"Leucemia mieloide aguda, indicado mielograma e imunofenotipagem para confirmação e\nprogramação terapêutica","B":"Púrpura trombocitopênica idiopática, iniciar prednisona oral de 0,5 a 2 mg/kg/dia até que as\nplaquetas aumentem para ? 30?50 x 109 /l, por 2\na 4 semanas e pesquisar hipertensão portal,\ndoenças autoimunes, medicamentos em uso, infecções monolike a fim de excluir causa subjacente.","C":"Anemia falciforme em crise de falcização, indicado pulso de ciclofosfamida","D":"Trombocitopenia COVID-LIKE, indicado repetir RT-PCR para diagnóstico da COVID","E":"Mioglobinúria secundária a rabdomiólise por exercício extenuante, internar para hidratação\nvenosa potente e monitoramento da função renal."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-299263","number":"299263","sourceNumber":"299263","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Seguindo as normas do uso racional de hemoderivados, qual dos pacientes a seguir\nteria indicação para receber transfusão de plaquetas segundo o guia para uso de\nhemocomponentes do Ministério da Saúde?","options":{"A":"Paciente em quimioterapia que será submetido a punção lombar para coleta de líquor com\nplaquetas de 22000/?L.","B":"Paciente com quadro de plaquetopenia de 18000 /?L após quimioterapia por neoplasia pulmonar\ne quadro de neu- tropenia febril.","C":"Paciente com quadro de Dengue e plaquetopenia de 12000/ ?L, porém ainda sem sangramentos\nativos.","D":"Paciente com quadro de coagulação intravascular disseminada e plaquetas 25000 ?L, com\nsangramentos ativos.","E":"Paciente com quadro de trombocitopenia induzia por heparina e 8000 plaquetas/ ?L, com\nsangramento leve de mucosas."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-269551","number":"269551","sourceNumber":"269551","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 70 anos é admitido em enfermaria com diagnósticos prévios de\nhipertensão, diabetes e insuficiência cardíaca\ncongestiva. No momento da admissão, apresenta\nquadro de anemia sintomática, com hemoglobina de 6,8 g/dL, de etiologia ainda a esclarecer. Em\nrelação ao tratamento inicial da anemia, qual é a proposta terapêutica indicada?","options":{"A":"Reposição parenteral de sulfato ferroso, vitamina B12 e ácido fólico, sem indicação de\ntransfusão de hemocomponente neste momento.","B":"Transfusão de 01 unidade de concentrado de hemácias e reavaliação clínica ao fim da\ntransfusão.","C":"Transfusão de 01 unidade de sangue total e reavaliação clínica ao fim da transfusão.","D":"Transfusão de 03 unidades de concentrado de hemácias, com o objetivo de atingir hemoglobina\nem torno de 10 g/dL.","E":"Transfusão de 02 unidades de concentrado de hemácias lavado, irradiado e filtrado, pelo alto\nrisco de reação transfusional na população de idosos, diabéticos e hipertensos, de forma\nindependente ou não."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-269552","number":"269552","sourceNumber":"269552","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 30 anos, previamente hígida, nota aparecimento de petéquias em\nmembros inferiores nas últimas duas semanas, sem\nqualquer outra queixa. O exame físico é\nnormal e o hemograma mostra apenas plaquetopenia, com 30 mil plaquetas/mm³, sem alterações\nna série vermelha ou nos leucócitos. Sobre esse quadro clínico, é CORRETO afirmar:","options":{"A":"Diante do alto risco de sangramento grave, a paciente tem indicação de internamento para\ntransfusão de concentrado de plaquetas.","B":"A principal hipótese diagnóstica é de Púrpura Trombocitopênica Imune (PTI), sendo corroborada\npor achado de esplenomegalia e biópsia de medula\nóssea mostrando baixa contagem de\nmegacariócitos.","C":"O tratamento da plaquetopenia dessa paciente envolve a reposição de folato e vitamina B12.","D":"Frente à hipótese diagnóstica de Púrpura Trombocitopênica Imune (PTI), está indicada a\npesquisa de infecção pelo HIV, por ser potencial causa de plaquetopenia.","E":"Está indicada a internação hospitalar para transfusão de concentrado de hemácias e\nesplenectomia no mesmo internamento, já que,\nnessa condição, a destruição das plaquetas ocorre\nno baço."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-265446","number":"265446","sourceNumber":"265446","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Para tratamento das tromboses venosas profundas, utilizamos os chamados\nanticoagulantes, medicamentos que atuam na cascata de\ncoagulação e degradação do trombo\nintravascular. Em caso de sangramentos com necessidade de reversão da ação desses\nmedicamentos, dos anticoagulantes listados abaixo, qual é praticamente 100% revertido pela ação\nda protamina?","options":{"A":"Heparina não fracionada.","B":"Variaria.","C":"Dabigatrana.","D":"Heparina de baixo peso molecular.","E":"Rivaroxabana."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-262811","number":"262811","sourceNumber":"262811","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre o uso racional de hemoderivados, qual dos pacientes abaixo apresenta indicação\npara transfusão de pool plaquetário?","options":{"A":"Paciente com quadro clínico de leucemia mieloide aguda e com 33mil plaquetas, em tratamento\npara aspergilose invasiva.","B":"Paciente com quadro de purpura trombocitpenica trombótica com 20 mil plaquetas e\ngengivorragia.","C":"Paciente com anemia aplásica com 55 mil plaquetas e epistaxe.","D":"Paciente com Leucemia Linfocitica aguda e quadro de neutropenia febril (temperatura de 38,3º)\ne com 15 mil plaquetas, mas sem sangramento\nativo."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-238918","number":"238918","sourceNumber":"238918","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Em relação à Púrpura Trombocitopênica Trombótica (PTT) é correto afirmar:","options":{"A":"O tratamento com a plasmaférese deve ser mais intenso e agressivo, sendo o único tratamento\nindicado.","B":"Tem predominância maior em mulheres entre a segunda e quarta década de vida,\nprincipalmente em caucasianas.","C":"Exames laboratoriais mostram trombocitopenia, presença de esquizócitos e diminuição na\nenzima lactato-desidrogenase.","D":"As principais características são anemia hemolítica microangiopática, trombocitopenia,\nalterações neurológicas, insuficiência renal e febre."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-231203","number":"231203","sourceNumber":"231203","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"?Vitamina cuja deficiência provoca fenômenos hemorrágicos espontâneos ou\nprovocados. Pode ocorrer quando há restrição\ndietética da vitamina, modificação da microbiota\nintestinal, má absorção de lipídeos e doenças hepáticas avançadas?. Essa descrição corresponde\nà","options":{"A":"Vitamina A.","B":"Vitamina C.","C":"Vitamina D.","D":"Vitamina E.","E":"Vitamina K."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-228120","number":"228120","sourceNumber":"228120","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente masculino de 76 anos procura a emergência devido à preocupação com\nresultado de exame laboratorial alterado. Nega sintomas. Apresenta história de fibrilação atrial,\ndislipidemia, diabetes e hipertensão arterial. Faz uso de rosuvastatina 20 mg ao dia, metformina\n850 mg duas vezes ao dia e enalapril 20 mg ao dia. Apresenta FC 68/min, PA 134/80 mmHg, FR\n12/min, temperatura 36,7 °C, e SpO? 99% em ar ambiente. Ao exame físico, não se constata\nequimose, hematoma ou sangramentos. Revisão de sistemas é negativa. Exame laboratorial\ntrazido demonstra tempo de protrombina/INR = 8,5. Qual é a conduta correta para esse caso,\nsegundo guidelines recentes?","options":{"A":"Omitir varfarina até nível terapêutico e, então, reiniciar varfarina com redução de 10-15% na\ndose semanal.","B":"Administrar vitamina K oral e omitir varfarina até nível terapêutico e, então, reiniciar\nvarfarina\ncom redução de 10-15% na dose semanal.","C":"Administrar vitamina K parenteral e omitir varfarina até nível terapêutico e, então, reiniciar\nvarfarina com redução de 10-15% na dose semanal.","D":"Administrar plasma fresco congelado e omitir varfarina até nível terapêutico e, então, reiniciar\nvarfarina com redução de 10-15% na dose semanal.","E":"Administrar concentrado de complexo protrombínico e omitir varfarina até nível terapêutico e,\nentão, reiniciar varfarina com redução de 10-15% na dose semanal."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-253665","number":"253665","sourceNumber":"253665","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre a púrpura trombocitopênica imunológica (PTI), assinale a alternativa\nINCORRETA:","options":{"A":"A esplenectomia é a melhor opção de tratamento em pacientes que não responderam ao\ncorticóide ou que apresentaram recaída após sua suspensão.","B":"Em mulheres gestantes com PTI, a via de parto preferencial é a cesariana pelo risco de\nsangramento de sistema nervoso central no feto.","C":"Devido aos riscos decorrentes ao uso de corticóide em gestantes com PTI, o tratamento de\nescolha deve ser a imunoglobulina humana.","D":"Em crianças com PTI e quadro clínico mais grave, o tratamento com corticóide poderá ser\ninstituído após a realização do mielograma para descartar leucemia aguda.","E":"A imunoglobulina induz boa resposta no paciente com PTI mas é temporária."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-199398","number":"199398","sourceNumber":"199398","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Na suspeita de pseudotrombocitopenia, recomenda-se a confirmação laboratorial por\nmeio de uma técnica específica. Assinale a alternativa que apresenta essa técnica.","options":{"A":"Contagem de plaquetas em tubo com EDTA.","B":"Dosagem de fibrinogênio.","C":"Contagem de plaquetas em tubo com citrato.","D":"Contagem de plaquetas em tubo com fluoreto.","E":"Contagem de reticulócitos."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-217101","number":"217101","sourceNumber":"217101","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente em enfermaria hospitalar recebendo transfusão de concentrado de hemácias\nevolui com quadro febril acompanhado de calafrios sem instabilidade hemodinâmica. Escolha a\nmelhor alternativa:","options":{"A":"Reação febril não hemolítica é complicação rara da transfusão de hemoderivados.","B":"Após a administração de anti-histamínico e antipirético a infusão do mesmo concentrado de\nhemácias pode ser reiniciado.","C":"O quadro acima representa claramente uma contaminação bacteriana levando a bacteremia\ndurante a transfusão.","D":"A presença de anticorpos contra antígenos específicos de Antígeno Leucocitário Humano - HLA\ne linfócitos em receptores previamente\naloimunizados está relacionada à fisiopatologia da reação\nfebril não hemolítica."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-199429","number":"199429","sourceNumber":"199429","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Qual é a causa mais comum de trombofilia hereditária em descendentes de europeus?","options":{"A":"Fator V de Leiden.","B":"Deficiência de proteína S.","C":"Deficiência de proteína C.","D":"Hiper-homocisteinemia.","E":"Níveis aumentados de Fator VIII."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-219288","number":"219288","sourceNumber":"219288","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"A reação febril não hemolítica é complicação comum da transfusão de hemoderivados.\nAssinale a melhor alternativa:","options":{"A":"Contaminações bacterianas são a principal fisiopatologia.","B":"Após a administração de antihistaminico e antipirético a infusão do mesmo concentrado de\nhemácias pode ser reiniciado.","C":"O hemoderivado que causou a reação deve ser analisado e descartado, não podendo ser\nreinfundido.","D":"A reação mais comum em pacientes submetidos a primeira transfusão.","E":"A reação ocorre apenas na transfusão de plasma fresco congelado."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-210683","number":"210683","sourceNumber":"210683","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 10 anos foi internado para realização de cirurgia ortopédica (correção de\nfratura). Porém, no intraoperatório,\napresentou sangramento moderado e necessitou receber\nconcentrado de hemácias ainda no centro cirúrgico. Cerca de 2 horas depois, já na enfermaria,\ncomeçou a apresentar taquidispneia e febre. Foi ofertado oxigênio, porém evoluiu com piora\nprogressiva, com queda da saturação. Manteve-se estável hemodinamicamente. A radiografia de\ntórax realizada sugeriu edema pulmonar bilateral. Qual é a hipótese diagnóstica mais provável para\nesse caso?","options":{"A":"Pneumonia associada à ventilação mecânica (PAV).","B":"Síndrome de trali.","C":"Choque séptico.","D":"Hipovolemia pós-cirúrgica."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-183416","number":"183416","sourceNumber":"183416","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Mulher de 58 anos de idade, admitido no Pronto Socorro com hematoma em membro\nsuperior esquerdo há 3 dias, hematúria há 2\ndias e copiosa hematêmese há 8 horas, acompanhada\nde tontura, fraqueza e sudorese. Faz uso de Warfarina 5 mg ao dia há cerca de 8meses por\napresentar fibrilação atrial. Usa, tembém, captopril e sinvastatina. Qual o teste de escolha para\navaliação da paciente na emergência?","options":{"A":"KPTT","B":"TAP","C":"TS","D":"TC"},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-172563","number":"172563","sourceNumber":"172563","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Com relação aos anticoagulantes orais e seus respectivos mecanismos de ação,\nnumere a coluna da direita de acordo com\nsua correspondência com a coluna da esquerda. 1.\nInibidor direto da trombina. 2. Inibidor direto do fator Xa. 3. Antagonista da vitamina K. ( )\nWarfarin. (\n\n) Rivaroxabana. ( ) Dabigatrana. ( ) Apixabana. Assinale a alternativa que apresenta a numeração\nCORRETA da coluna da direita, de cima para\nbaixo.","options":{"A":"1 ? 3 ? 2 ? 1.","B":"3 ? 2 ? 2 ? 1.","C":"1 ? 3 ? 3 ? 2.","D":"3 ? 2 ? 1 ? 2.","E":"2 ? 1 ? 1 ? 3."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-184218","number":"184218","sourceNumber":"184218","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Maria Efigênia, feminina, 65 anos, previamente hipertensa, interna com astenia,\nlipotimia e hipotensão. Refere há cerca de 1 mês episódio isolado de metrorragia. Exames\nlaboratoriais mostram uma hemoglobina de 6g/dL. A respeito do caso assinale a afirmativa\nverdadeira:","options":{"A":"Estaria indicada a transfusão de hemácias inicialmente para a estabilização do quadro.","B":"Volume Corpuscular Médio normal afasta o diagnóstico de ferropenia neste caso.","C":"Se comprovada a ferropenia, deve se indicar a reposição de ferro oral ou parenteral, além de\nencaminhamento ambulatorial para a ginecologista sem necessidade de investigação de perdas\ngastrointestinais.","D":"Sendo a causa mais comum de anemia nessa faixa etária, deve-se tratar empiricamente a\nferropenia e, caso não haja resposta, prosseguir a investigação para outras etiologias."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-173226","number":"173226","sourceNumber":"173226","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Correlacione as drogas com as respectivas classes, e assinale a alternativa que contém\na sequência CORRETA.\n\n(1) Aspirina.\n\n(2) Ticagrelor.\n\n(3) Apixabana.\n\n(4) Dabigatrana.\n\n(5) Varfarina.\n\n( ) Antagonista da vitamina K.\n( ) Inibidor do fator Xa.\n\n( ) Inibidor do receptor P2Y12.\n( ) Inibidor direto da Trombina.\n( ) Inibidor da Cox plaquetária.","options":{"A":"3,5,2,4,1.","B":"5,3,4,2,1.","C":"5,3,2,4,1.","D":"5,4,2,3,1.","E":"5,4,1,3,2."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-172610","number":"172610","sourceNumber":"172610","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Menino de três anos de idade é admitido no pronto atendimento com queixa de\nepistaxe espontânea há algumas horas, de volume\npequeno. A mãe do paciente relata história de\ninfecção viral do trato gastrointestinal (diarreia aguda) há 2 semanas, com resolução completa. Ao\nexame: bom estado geral, corado, hidratado. Ausculta cardíaca e pulmonar sem alterações. Baço,\nfígado e linfonodos não palpáveis. Equimoses e petéquias evidentes em membros inferiores, sem\noutras alterações. Hemograma evidenciando: hemoglobina 13,0 g/dl; VCM 80 fl; leucócitos\n9.700/mm³, com contagem diferencial normal; plaquetas 15.000/mm³; 1% de reticulócitos. O\ndiagnóstico mais provável é:","options":{"A":"Leucemia aguda.","B":"Síndrome hemolítico-urêmica.","C":"Púrpura trombocitopênica trombótica.","D":"Púrpura trombocitopênica idiopática.","E":"Doença de Gaucher."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-173218","number":"173218","sourceNumber":"173218","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Pré-escolar de cinco anos inicia subitamente quadro de manchas roxas no corpo e\nsangramento gengival. Ao exame: bom estado geral, com petéquias em conjuntiva e palato,\npetéquias e equimoses disseminadas pelo corpo e ausência de hepatoesplenomegalia.\n\nHemograma: hematócrito = 36%, hemoglobina = 12g/dl, leucócitos = 8.000/mm³ (B=0; E=3;\nM=0;M=0; B=5; S=67; L=20; M=5), plaquetas = 3.000/mm³. Qual é a hipótese mais provável?","options":{"A":"Leucemia linfoblástica aguda.","B":"Púrpura trombocitopênica idiopática.","C":"Leucemia mieloide crônica.","D":"Anemia aplástica.","E":"Púrpura de Henoch-Schöenlein."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-178989","number":"178989","sourceNumber":"178989","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Qual a alternativa CORRETA a respeito de púrpura trombocitopênica imune? ( Kasper,\nFauci , Hauser, Longa, Jamuson and Loscalzo - Hill harrison's principles of internal medicine 19th\nedition ? Mcgraw Hill)","options":{"A":"Esplenomegalia é um achado comum.","B":"Sua forma aguda é comum na infância e tende a ser auto-limitada","C":"O tratamento de escolha é a esplenectomia","D":"O hemograma freqüentemente apresenta anemia e leucocitose com linfocitose","E":"Devemos usar transfusão de plaquetas sempre que a contagem de plaquetas for menor que\n20.000."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-151241","number":"151241","sourceNumber":"151241","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Todas as condições patológicas abaixo são causas de anemia hemolítica\nmicroangiopática, EXCETO a (o):","options":{"A":"Cirrose hepática.","B":"Uso de quimioterapia.","C":"Coagulação intravascular disseminada.","D":"Eclâmpsia.","E":"Hipertensão maligna."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-154878","number":"154878","sourceNumber":"154878","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"São complicações relacionadas à utilização de hemoderivados, EXCETO: (CARVALHO\nWB, SOUZA RL, SOUZA N. Emergência e Terapia\nIntensiva Pediátrica 3ª Ed. Werther. p.493)","options":{"A":"Lesão pulmonar aguda.","B":"Sobrecarga circulatória.","C":"Reação hemolítica aguda.","D":"Reação febril não hemolítica.","E":"Trombocitose."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-150037","number":"150037","sourceNumber":"150037","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Criança do sexo masculino, com 6 meses de idade, apresentou aumento de volume na\nnádega após realização de vacina\nintramuscular. Após 3 dias da vacina, evoluiu com hematoma da\nnádega até região do joelho. Sem febre ou outras alterações. Sem história anterior de\nsangramentos. Sem história familiar de hemorragias. Coletado hemograma, com resultado normal,\nTempo de Protrombina (TAP) e Tempo de Trombina (TT) normais e Tempo de Tromboplastina\nParcial Ativado (TTPA) alargado. Qual é a principal hipótese diagnóstica e qual exame é necessário\npara sua confirmação?","options":{"A":"Disfunção do fibrinogênio ? dosagem de fibrinogênio.","B":"Doença de von Willebrand ? dosagem de fator IX.","C":"Trombastenia de Glanzmann ? teste de agregação plaquetária.","D":"Hemofilia ? dosagem de fatores VIII e IX.","E":"Deficiência de vitamina K ? dosagem de fatores V, VII, X, XII."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-153679","number":"153679","sourceNumber":"153679","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Das condições abaixo, assinale qual NÃO está relacionada ao maior risco de trombose\nvenosa profunda.","options":{"A":"Deficiência de proteína C.","B":"Presença do fator V de LEIDEN.","C":"Neoplasia maligna ativa.","D":"Doença de VON WILLEBRAND.","E":"Uso de anticoncepcionais hormonais com estrogênio."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-153690","number":"153690","sourceNumber":"153690","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Sobre os distúrbios da coagulação, relacione as colunas a seguir:\n\n(A) Uso terapêutico de heparina.\n\n(B) Uso terapêutico de cumarínico.\n\n(C) Prolongamento do TP e TTPa.\n\n(D) Prolongamento do TTPa.\n\n(E) Anormalidade isolada do TP.\n\n( ) Deficiência do fator VII.\n\n( ) Hemofilias ou deficiência do fator XI.\n\n( ) Deficiência de fatores V, X, II, ou fibrinogênio.\n( ) Alargamento do TP.\n\n( ) Alargamento do TTPa.","options":{"A":"E - D - C - B - A.","B":"E - B - C - A - D.","C":"D - E - C - A - B.","D":"C - E - D - A - B.","E":"D - C - E - B - A."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-154013","number":"154013","sourceNumber":"154013","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Para testar o conhecimento de seus residentes DR. Beltrano apresentou arteriais de 4\npacientes internados na UTI e de um interno que \"voluntariamente? permitiu que fosse colhido a\nsua gasometria arterial. Foram ocultados os nomes dos laudos das gasometrias. Os residentes\ndeveriam acertar a qual paciente pertencia casa gasometria. Pacientes: Leito1- Paciente em sepse\ngrave em choque; Leito 2- doença pulmonar obstrutiva crônica com pneumonia com máscara de\nventuri à 40%; Leito 3 - Paciente em pós operatório abdominal com sonda nasogástrica em\ndrenagem aberta com debito elevado; Leito 4- Paciente em ventilação mecânica, que\ninadvertidamente a frequência respiratória estava em 30 rpm (respiração por minuto). Gasometrias:\nGasometria (a) pH 7,16 pCO2 29 mmHg pO2 70mmHg Bicarbonato10mEq/L; Gasometria (b) pH\n7,40 pCO2 38 mmHg pO2 90mmHg Bicarbonato23mEq/L; Gasometria (c) pH 7,51 pCO2 26 mmHg\npO2 108mmHg Bicarbonato20mEq/L; Gasometria (d) pH 7,53 pCO2 40 mmHg pO2 90mmHg\nBicarbonato33mEq/L; Gasometria (e) pH 7,34 pCO2 73 mmHg pO2 60mmHg Bicarbonato\n38mEq/L; Qual a alternativa correlaciona o paciente à sua gasometria (onde L é o Leito e Gaso e a\nGasometria)","options":{"A":"L 1 - Gaso (a); L 2 - Gaso (b); L 3 - Gaso (c); L 4 - Gaso (d); Interno - Gaso (e)","B":"L 1 - Gaso (a); L 2 - Gaso (e); L 3 - Gaso (d); L 4 - Gaso (c); Interno - Gaso (b)","C":"L 1 - Gaso (b); L 2 - Gaso (a); L 3 - Gaso (e); L 4 - Gaso (d); Interno - Gaso (d)","D":"L 1 - Gaso (e); L 2 - Gaso (a); L 3 - Gaso (c); L 4 - Gaso (d); Interno - Gaso (b)","E":"L 1 - Gaso (b); L 2 - Gaso (e); L 3 - Gaso (d); L 4 - Gaso (a); Interno - Gaso (c)"},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-154865","number":"154865","sourceNumber":"154865","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Com relação ao manejo de hemorragias e distúrbios de coagulação, assinale a\nINCORRETA: (CHAMONE DAF, CAVALHEIRO FILHO C, RACHED RA. Coagulação em cirurgia.\n\nEm: GAMA-RODRIGUES JJ et al. Clínica Cirúrgica. Editora Manole. 2008.)","options":{"A":"Plaquetopenia pode estar relacionado a púrpuras, coagulopatia de consumo e hiperesplenismo.","B":"Plaquetose ou trombocitose pode estar relacionado a perda maciça de sangue, pacientes\neplenectomizados, tumores hepáticos ou doenças mieloproliferativas.","C":"A função das plaquetas (e não só o seu número) tem importância na prevenção de\nsangramentos, e ela pode estar alterada em\npacientes em uso de AAS, antiinflamatórios e alguns\nantibióticos.","D":"Pacientes com hemofilia A e doença de von Willebrand tem indicação de administração de\nconcentrado de plaquetas.","E":"Pacientes em uso de anticoagulantes orais inibidores da vitamina K que serão submetidos a\ncirurgia de emergência tem indicação de transfusão de plasma fresco congelado."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-153198","number":"153198","sourceNumber":"153198","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"A \"púrpura trombocitopênica idiopática\" é um distúrbio imunomediado caracterizado\npelo aumento da taxa de destruição plaquetária no\nsistema retículo endotelial, especialmente no\nbaço. Quanto ao diagnóstico, é CORRETO afirmar que:","options":{"A":"O quadro clínico característico é o de uma criança doente, com febre vespertina, perda de\napetite e peso, sem vontade de brincar.","B":"A história positiva para quadro viral prévio ao aparecimento da PTI e de contagem baixa de\nplaquetas ao diagnóstico (< 10.000 mm³) é considerado fator preditivo de boa evolução da doença.","C":"O hemograma característico da PTI mostra além de uma contagem plaquetária diminuída,\nalterações da série vermelha, como diminuição da concentração da hemoglobina e alterações\nleucocitárias.","D":"Nestes pacientes, além das manifestações hemorrágicas, é possível, ao exame físico, palpar o\nbaço em cerca de 50% dos casos.","E":"A hemorragia grave é comum como manifestação inicial, principalmente no período de quatro\nsemanas que se segue ao início do tratamento."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-131213","number":"131213","sourceNumber":"131213","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente com demência avançada, acamado, proveniente de instituição de longa\npermanência com sinais de cuidados\ninadequados. Ao exame físico apresenta-se emagrecido,\nhipocorado, com sinais de depleção espaço extracelular. Laboratório mostra dosagem sérica de Na:\n155 mmol/L.","options":{"A":"Paciente apresenta hipernatremia provavelmente secundária a baixa ingesta hídrica.","B":"A sobrecarga de sódio na dieta é responsável pela hipernatremia.","C":"Trata-se de hiponatremia pelo baixo aporte dietético de sódio.","D":"Trata-se de hiponatremia secundária a depleção volêmica.","E":"A hipernatremia é provavelmente secundária a diabetes insipidus."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-126454","number":"126454","sourceNumber":"126454","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"São alterações eletrocardiográficas que podem aparecer na hiperpotassemia:","options":{"A":"Alargamento de QRS e desaparecimento da onda P.","B":"Infradesnível do segmento ST nas derivações precordiais.","C":"Onda T negativa e assimétrica.","D":"Onda P apiculada e estreita.","E":"Onda T achatada e aparecimento da onda U."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-126428","number":"126428","sourceNumber":"126428","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"A queixa de \"meu filho sangra\" é comum no ambulatório e no pronto atendimento. A\nhistória é fundamental para a avaliação da gravidade do sangramento, podendo através dela definir\nse o sangramento é da hemostasia primária ou secundária. Quais exames de triagem em conjunto\nsão utilizados para orientar a investigação?","options":{"A":"Tempo de sangramento e hemograma.","B":"Citometria de fluxo e hemograma com plaquetas.","C":"TAP, TTPA, tempo de trombina e hemograma com plaquetas.","D":"Dosagem da atividade do fator VIII, TAP e TTPA.","E":"Tempo de sangramento, tempo de trombina e hemograma com plaquetas."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-101064","number":"101064","sourceNumber":"101064","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 82 anos, portador de transtorno do humor e hipertensão arterial essencial,\nem uso de fluoxetina e hidroclorotiaziada,\ndesenvolve quadro de diminuição do nível de consciência\nno pós-operatório de cirurgia abdominal. Considerando que a função renal está normal, qual é o\ndistúrbio metabólico mais provável responsável pela alteração neurológica nesse paciente?","options":{"A":"Hipermagnesemia.","B":"Hiponatremia.","C":"Hipocalcemia.","D":"Hiperpotassemia.","E":"Hipopotassemia."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-102851","number":"102851","sourceNumber":"102851","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Homem, 55 anos, hipertenso, morador de rua, deu entrada no serviço de emergência\npor queixa de náuseas, vômitos, fraqueza e\ndispneia. Na admissão realizou o eletrocardiograma\nabaixo (VER IMAGEM). A alteração encontrada no eletrocardiograma é compatível com:","options":{"A":"Hipercalcemia.","B":"Hipercalemia.","C":"Hiponatremia.","D":"Hipocalemia.","E":"Hipotermia."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-19/102851.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-103618","number":"103618","sourceNumber":"103618","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"C.Q.D., 24 anos, foi admitida no hospital por quadro de fraqueza muscular, náuseas e\nconstipação. PA: 110 x 70 mmHg. Peso: 45 kg. Altura: 1,80 m. Resultados laboratoriais: Sódio\nsérico 140 mEq/L (normal 135- 145mEq/L): potássio, 2,6 mEq/L (3,5-4, 5 mEq/L): creatinina: 0, 7\nmg/dl: glicemia 86 mg/dl. Relata medo de ganhar peso, apesar de as amigas a considerarem \"muito\nmagra\". Por essa razão, iniciou uso de fórmula para emagrecer há cerca de dois meses. Sobre o\ncaso, marque a alternativa CORRETA.","options":{"A":"As alterações eletrocardiográficas relacionadas a esse distúrbio eletrolítico são depressão de\nsegmento ST, onda T apiculada e onda U.","B":"A hipocalemia pode levar a lesões vacuolares das células epiteliais do túbulo proximal e, menos\nfrequentemente, do distal. Além de, em casos mais prolongados, poder causar alterações renais\nseveras, incluindo nefrite intersticial, fibrose e atrofia tubular.","C":"Por ser um íon predominantemente extracelular, a hipocalemia reflete um grande déficit de\npotássio corporal.","D":"A hipocalemia é uma complicação pouco frequente na anorexia nervosa. Pode resultar do déficit\nna ingestão, uso abusivo de diuréticos ou\nlaxantes e vômitos repetidos.","E":"O tratamento da hipocalemia compreende a identificação e correção da causa (remoção de\nmedicamento, mudança de dieta, etc.) e a reposição eletrolítica, que deve ser feita\npreferencialmente por via endovenosa, sem a necessidade de monitoração cardíaca."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-100902","number":"100902","sourceNumber":"100902","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"São causas de alcalose metabólica todas as assertivas abaixo, exceto:","options":{"A":"Intoxicação por salicilatos.","B":"Ingestão de grande quantidade de bicarbonato.","C":"Estado pós-hipocapnia.","D":"Aldosteronismo primário.","E":"Administração de penicilina."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-100921","number":"100921","sourceNumber":"100921","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 52 anos é internada por cetoacidose diabética, estando com mal estado\ngeral e confusão mental. Na avaliação\nclínica inicial apresenta: PA = 100/60mmHg, Fc e pulso de\n164 spm - refere oligoanúria nas últimas 12 horas - Sinais de DEEC de 30%. Peso aproximado de\n65 kg. São exames laboratorias realizados na admissão: Na de 156 mEq/L, K : 3.8 mEq/L e\nGlicose plasmática de 350mg/dl. Pergunta-se: qual será o distúrbio da água e qual será a\ncorreção a ser feita para este distúrbio especifico?","options":{"A":"Hipernatremia e a correção seria a infusão de\n\n3.500 ml de soro glicosad para corrigir a\nhiperosmolaridade.","B":"Hiponatremia e a correção seria a administração de soro fisiológico hipertônico a 3%.","C":"Hipernatremia e a correção seria a infusão de\n\n3.500 ml de soro glicosado a 5% ou opcionalmente solução salina hipotônica a 0,45%.","D":"Não existe distúrbio da água e sim DEEC\ndecorrente do desvio iônico provocado pela\ncetoacidose.","E":"Trata-se de um distúrbio misto: distúrbio da\nágua ? hiponatremia e distúrbio do sódio ?\ndesidratação."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-100926","number":"100926","sourceNumber":"100926","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 18 anos interna no HCV (Hospital da Cruz Vermelha), gemente,\ndiaforética, cianose discreta de extremidades,\ncom familiares referindo exposição exagerada ao\nsol, abuso de álcool, libação alimentar e vômitos alimentares profusos. PA = 100/60 mmHg, FC e\npulso de 160 spm, afebril, olhos encovados. Jugulares colabadas; mucosas discretamente\númidas. Glicose plasmática de 55mg/dl e Na de 150 mEq/L. K plasmático de 3.8 mEq/L. Peso\naproximado de 50 kg. Calcule o plano de reposição parenteral levando em conta o básico, as\nperdas, distúrbio do metabolismo da água e a reposição de potássio e responda, com base nos\ndados aqui apresentados, a questão abaixo. Qual será o calculo final da reposição parental para\nesta paciente nas próximas 20 horas?","options":{"A":"Soro fisiológico 2.500ml + soro glicosado 3.000ml.","B":"Soro fisiológico 3.000ml + soro glicosado 2.000ml.","C":"Soro fisiológico 3.500ml + soro glicosado 3.500 ml.","D":"Soro fisiológico 4.500 ml + soro glicosado 3.000ml.","E":"Soro fisiológico 1.500m + sor glicosado 4.500 ml."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-100929","number":"100929","sourceNumber":"100929","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 18 anos, interna no HCV (Hospital da Cruz Vermelha), gemente,\ndiaforética, cianose discreta de extremidades,\ncom familiares referindo exposição exagerada ao\nsol, abuso de álcool, libação alimentar e vômitos alimentares profusos. PA = 100/60 mmHg, FC e\npulso de 160 spm, afebril, olhos encovados. Jugulares colabadas; mucosas discretamente úmidas.\nGlicose plasmática de 55 mg/dl e Na de 150 mEq/l. K plasmático de 3.8 mEq/L. Peso aproximado\nde 50 kg. Calcule o plano de reposição parenteral levando em conta o básico, as perdas, distúrbio\ndo metabolismo da água e a reposição de potássio e responda, com base nos dados aqui\napresentados, a questão abaixo. Como deverá ser a reposição do potássio na forma de KCL a\n19.1%:","options":{"A":"Adicionar 15 ml em cada frasco de soro glicosado: 60 ml.","B":"Adicionar 08 ml em cada frasco de soro\nglicosado: 32 ml.","C":"Adicionar 10 ml em cada frasco de soro glicosado: 40 ml.","D":"Adicionar 12 ml em cada frasco de soro\nglicosado: 48 ml.","E":"Adicionar 20 ml em cada frasco de soro\nglicosado: 60 ml."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-81359","number":"81359","sourceNumber":"81359","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Relacione as colunas e assinale a alternativa que contém a sequência CORRETA\nquanto à indicação de hemocomponentes\nsanguíneos: (1) Indicação para a prevenção de reações\nàs proteínas plasmáticas; (2) Indicação para a prevenção de reações a componentes leucocitários;\n\n(3) Indicação para a redução do risco de doença \"enxerto contra hospedeiro\"; (4) Indicação em\ncasos de coagulação intravascular\ndisseminada; (5) Contraindicação na síndrome \"hemólise,\nenzimas hepáticas elevadas, baixa contagem de plaquetas\". ( ) Concentrado de hemácias filtradas;\n( ) Plasma fresco; ( ) Concentrado de hemácias irradiadas; ( ) Concentrado de plaquetas; ( )\nConcentrado de hemácias lavadas.","options":{"A":"4 - 2 - 5 - 1 - 3.","B":"3 - 5 - 1 - 2 - 4.","C":"2 - 4 - 3 - 5 - 1.","D":"1 - 3 - 2 - 4 - 5.","E":"Todas as alternativas acima estão incorretas."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-77961","number":"77961","sourceNumber":"77961","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Uma mulher de 33 anos de idade está internada em uma clínica de cirurgia plástica, no\n2º dia de pós-operatório de lipoaspiração.\nQueixa-se de dor abdominal no local da cirurgia e\nnáuseas. Os dados vitais, exame físico segmentar e neurológico são normais. Foram colhidos os\nseguintes exames séricos: creatinina = 0,9 mg/dl; sódio = 122 mEq/L; potássio = 3,8 mEq/L. Qual a\nconduta terapêutica a ser tomada?","options":{"A":"Administração de solução salina hipertônica a 3%.","B":"Restrição da ingestão de água.","C":"Ultrafiltração do plasma com infusão de potássio.","D":"Administração de furosemida.","E":"Infusão de solução salina isotônica."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-87154","number":"87154","sourceNumber":"87154","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Seguem três gasometrias em ar ambiente, colhidas de pacientes com DPOC. Em todas\nhá hipercapnia. (VER IMAGEM) Baseando-se na\ngasometria, qual(is) deste(s) paciente(s) tinha(m)\nhipercapnia crônica?","options":{"A":"1 e 2.","B":"1 e 3.","C":"2 e 3.","D":"Todos.","E":"Apenas o 3."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-19/87154.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-78994","number":"78994","sourceNumber":"78994","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 70 anos apresenta quadro febril importante há pelo menos uma semana,\ncom inapetência e períodos de confusão mental. O\nexame físico revela: PA = 90/60 mmHg; FC =\n125 bpm; temperatura = 35,8ºC; emagrecimento importante (43 kg) e sinais ectoscópicos de\ndepleção. Os principais exames laboratoriais evidenciam: creatinina de 1,80 mg/dl; sódio sérico de\n123 mEq/L; potássio sérico de 3,89 mEq/L; gasometria arterial mostra pH = 7,12, pCO2 = 44\nmmHg; bicarbonato = 12 mEq/dl; BE = -13. Além de insuficiência renal aguda, este paciente\napresenta:","options":{"A":"Desidratação, depleção e acidose respiratória.","B":"Depleção, excesso de água e acidose metabólica.","C":"Falta de água, depleção e distúrbio acidobásico misto.","D":"Excesso de água, depleção e alcalose mista.","E":"Excesso de água, depleção e distúrbio acidobásico misto."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-64022","number":"64022","sourceNumber":"64022","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Com relação à composição corporal das pessoas e sua evolução ao longo do processo\nnormal de envelhecimento, quando se compara uma pessoa de mesmo sexo com 25 anos e com\n75 anos de idade, é CORRETO afirmar:","options":{"A":"A massa de gordura aumenta.","B":"A massa tecidual magra aumenta.","C":"A massa óssea aumenta.","D":"A água extracelular diminui.","E":"A água intracelular aumenta."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-66006","number":"66006","sourceNumber":"66006","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 70 anos, portador de hipertensão, dislipidemia e insuficiência renal crônica\nnão dialítica (creatinina basal: 2,4 mg/dl),\niniciou há 4 dias com diarreia líquida, várias vezes ao dia,\nsem sangue, muco ou pus. Admitia vômitos alimentares. Negava febre. Em seu exame físico\napresentava-se taquicárdico e desidratado. Em seus exames laboratoriais destacam-se: ?\ncreatinina: 3,8 mg/dl; ? ureia: 200 mg/dl; ? potássio: 6,8 mEq/L; ? sódio: 150 mEq/L. Dado este\nquadro clínico, leia as assertivas abaixo: I. Deve-se realizar um eletrocardiograma. II. O\ntratamento\nde sua hipercalcemia deve ser feito com furosemida e resina de troca intestinal. III. Hidratação e\nuso de solução polarizante (10 UI insulina regular em 50 g de glicose) podem ser considerados no\nseu tratamento. Está (ão) correta (s) APENAS:","options":{"A":"III.","B":"II e III.","C":"I e III.","D":"I e II.","E":"I."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-60677","number":"60677","sourceNumber":"60677","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente feminina, 74 anos, sequelada de AVC e com Doença de Alzheimer,\ninstitucionalizada há 3 meses. Desde então vem\nrecebendo medicação ansiolítica e antipsicótica.\nApresentou diminuição do apetite e vem alimentando-se com auxílio de mingau e alimentos\npastosos diariamente. Chega à emergência prostrada, oligoanúrica (10 ml/h), desidratada (2+/4).\nApresenta os seguintes exames: Ur(300) Cr(3,5) K(6,0), Gasometria (pH: 7,25, PCO2: 30,\nBicarbonato: 17). Qual conduta clínica a ser tomada e quais parâmetros devem ser relevantes?","options":{"A":"Iniciar hidratação vigorosa com soro fisiológico 0,9% (500 ml/h), manter débito urinário (20\nml/h),\nEncaminhar ao Nefrologista para iniciar Diálise.","B":"Iniciar Hidratação com Soro Fisiológico (1000 ml/h), Bicarbonato de Sódio, Manter Diurese (50\nml/h), Encaminhar ao Nefrologista para acompanhamento.","C":"Iniciar Hidratação com Soro Fisiológico (até 1000 ml/h), Iniciar Resina de Troca Iônica, Manter\nDébito Urinário (50 ml/h), Solicitar acompanhamento do Nefrologista.","D":"Iniciar Hidratação com Soro Fisiológico (até 1000 ml/h), Manter Débito urinário (20 ml/h),\nIniciar\nBicarbonato de Sódio e Furosemida. Encaminhar ao Nefrologista.","E":"Iniciar Hidratação com Soro Fisiológico (250 ml/h), Manter Débito urinário (50 ml/h), Uso de\nFurosemida e Bicarbonato de Sódio. Encaminhar ao Nefrologista."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-64052","number":"64052","sourceNumber":"64052","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Uma criança sofreu uma queda de uma árvore e começou a apresentar dificuldade para\nrespirar. Levada ao Pronto-Socorro, foi identificado um pneumotórax que restringiu a ventilação\ndeterminando um acúmulo de CO2. A alteração do equilíbrio acidobásico que ocorre nesse caso é:","options":{"A":"Acidose metabólica.","B":"Acidose mista.","C":"Alcalose metabólica.","D":"Acidose respiratória.","E":"Alcalose respiratória."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-58814","number":"58814","sourceNumber":"58814","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Qual a necessidade básica de água para uma criança com 10 kg de peso em repouso?","options":{"A":"10 ml/hora.","B":"20 ml/hora.","C":"30 ml/hora.","D":"40 ml/hora.","E":"50 ml/hora."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-64072","number":"64072","sourceNumber":"64072","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Uma criança sofreu uma queda de uma árvore e começou a apresentar dificuldade para\nrespirar. Levada ao pronto-socorro, foi identificado um pneumotórax que restringiu a ventilação\ndeterminando um acúmulo de CO2. A alteração do equilíbrio ácido-básico que ocorre nesse caso é:","options":{"A":"Acidose metabólica.","B":"Acidose mista.","C":"Alcalose metabólica.","D":"Acidose respiratória.","E":"Alcalose respiratória."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-64089","number":"64089","sourceNumber":"64089","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Pré-escolar de quatro anos apresenta quadro de tosse, febre, vômitos e dispneia há\nquatro dias. Exame físico: taquipneia,\ntiragem subcostal e cianose. Radiografia de tórax:\npneumonia extensa. A gasometria arterial, colhida antes da administração de oxigênio, revela: pH:\n7,26; pO2: 67 mmHg; pCO2:38 mmHg, bicarbonato: 14 mEq/l. Diante deste quadro, pode-se\nafirmar que o paciente apresenta:","options":{"A":"acidose mista","B":"alcalose mista","C":"apenas acidose metabólica","D":"apenas alcalose respiratória","E":"acidose metabólica e alcalose respiratória"},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-63041","number":"63041","sourceNumber":"63041","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"São elementos utilizados para o tratamento da hiperpotassemia na criança, exceto:","options":{"A":"Sulfato de magnésio","B":"Bicarbonato de sódio","C":"Solução de insulina e glicose","D":"Gluconato de cálcio","E":"Terbutalina"},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-43440","number":"43440","sourceNumber":"43440","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Um lactente de 8 meses, com história de diarreia, vômitos e poliúria há 3 dias, dá\nentrada no pronto atendimento com mucosas secas, olhos encovados, turgor frouxo de\nsubcutâneo, distensão abdominal e hipotonia generalizada. O eletrocardiograma evidencia\ndepressão de segmento ST e onda T invertida. Além da reposição de volume para correção da\ndesidratação, qual íon deverá ser reposto, além das necessidades básicas diárias?","options":{"A":"Potássio.","B":"Sódio.","C":"Cálcio.","D":"Fósforo.","E":"Magnésio."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-46033","number":"46033","sourceNumber":"46033","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"A alteração eletrolítica encontrada na acidose metabólica, decorrente de desidratação\nna criança, mais comumente é:","options":{"A":"Hipocalcemia","B":"Hipocalemia","C":"Hipercalemia","D":"Hipomagnesemia","E":"Hipercalcemia"},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-46332","number":"46332","sourceNumber":"46332","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Um homem de 64 anos, agricultor, dá entrada no PS com quadro de mal estar e\ndesconforto torácico. É diabético há 20 anos, em tratamento com metformina 850 mg 2 vezes ao\ndia e, há 5 anos iniciou tratamento de hipertensão com enalapril 20 mg ao dia. No mês anterior,\napresentou um eletrocardiograma (ECG) normal. O plantonista solicita um novo ECG onde\nobservou: Derivação DII: Os exames laboratoriais de entrada mostravam: creatinina 2,3 mg/dl,\nSódio: 141 mEq/L, Potássio 7,2 mEq/L. Glicemia 202 mg/dl e troponina negativa. Em relação ao\ndistúrbio clínico que coloca esse paciente em risco iminente de morte, qual a sequência mais\nadequada a ser tomada?","options":{"A":"Diálise, gluconato de cálcio, insulinoterapia, Inalação com B2 agonista.","B":"Gluconato de cálcio, inalação com B2 agonista, insulinoterapia, diálise.","C":"Inalação com B2 agonista, gluconato de cálcio,\ninsulinoterapia, diálise.","D":"Insulinoterapia, inalação com B2 agonista, gluconato de cálcio, diálise.","E":"Inalação com B2 agonista, insulinoterapia, gluconato de cálcio, diálise."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-46333","number":"46333","sourceNumber":"46333","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Um paciente de 22 anos, internado na UTI por sepse pulmonar e em ventilação\nmecânica, apresenta a seguinte gasometria: pH =\n7.20, HCO3 = 16, pCO2 = 20, pO2 = 100, FiO2 =\n95%. O distúrbio acidobase subjacente é:","options":{"A":"Acidose metabólica pura.","B":"Acidose metabólica e acidose respiratória.","C":"Acidose metabólica e alcalose respiratória.","D":"Acidose respiratória pura.","E":"Acidose respiratória e alcalose metabólica."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-46335","number":"46335","sourceNumber":"46335","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Um paciente de 25 anos é encontrado em coma e trazido ao hospital. Através dos\nexames complementares foi diagnosticada uma acidose\nmetabólica com as seguintes\ncaracterísticas: pH = 7,20, HCO3 = 16, pCO2 = 32. Entre outros exames solicitados, o paciente\napresentava: Sódio 134 mEq/L e Cloro 108 mEq/L. Com esses resultados fica improvável o\ndiagnóstico de:","options":{"A":"Hipoaldosteronismo primário.","B":"Cetoacidose diabética.","C":"Acidose tubular renal.","D":"Diarreia grave.","E":"Intoxicação por acetazolamida."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-32072","number":"32072","sourceNumber":"32072","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Levando-se em conta um adulto de 86 kg, quais seriam os volumes de seu espaço\nextracelular, do seu espaço intravascular, água corpórea total e espaço intersticial? Assinale a\ncorreta:","options":{"A":"17,2 litros; 34,4 litros ; 51,6 litros e 12,9 litros.","B":"34,2 litros; 17,2 litros; 51,6 litros e 12,9 litros.","C":"51,6 litros; 17,2 litros; 34,4 litros e 12,9 litros.","D":"12,9 litros; 51,6 litros; 12,9 litros e 17,2 litros.","E":"25,4 litros; 8,6 litros; 12,9 litros e 3,8 litros."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-32076","number":"32076","sourceNumber":"32076","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Quais são os fatores reguladores do balanço interno do potássio? Assinale a incorreta:","options":{"A":"Insulina, atividade beta-adrenérgica, balanço acidobase, osmolalidade.","B":"Insulina, hormônio tireoideano, potássio plasmático, magnésio.","C":"Hormônio tireoideano, ingesta de carnes, osmolalidade, aldosterona.","D":"Insulina, atividade beta-adrenérgica, magnésio.","E":"Hormônio tireoideano, magnésio, insulina e atividade beta-adrenérgica."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-32141","number":"32141","sourceNumber":"32141","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente feminina, 57 anos, com Ca Uterino com invasão de linfonodos, pelve, bexiga,\nureteres. Evoluiu com quadro de sonolência,\nconfusão mental, anúria. US demonstrou pelve\ncongelada e dilatação pielocalicial bilateral. Exames complementares. Ur (360); Cr (9,2); K (6,2);\nGasometria: pH (7,1); pCO2 (23); pO2 (70); Bic (14); BE (-15); Sat O2 (92). Diante desse caso, qual\na resposta correta:","options":{"A":"IRA pós-renal, com Acidose Metabólica, necessitando de uso de Bicarbonato de Sódio para\nreverter a acidose.","B":"IRA pós-renal, com Alcalose Metabólica, necessitando de Diálise.","C":"IRA pós-renal, com Acidose Metabólica, necessitando de Diálise e Derivação (Nefrostomia).","D":"IRA pós-renal, com Alcalose Metabólica, necessitando de Derivação (Nefrostomia).","E":"IRA pós-renal, com Alcalose Metabólica, necessitando de Bicarbonato de Sódio e Diálise."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-32204","number":"32204","sourceNumber":"32204","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Em relação ao metabolismo do potássio em crianças, considere as seguintes\nafirmativas: 1. A trombocitose aumenta os\nníveis séricos de potássio. 2. A insuficiência renal e\nadrenal são causas de hipercalemia. 3. O exercício exagerado não é causa de hipercalemia. 4. A\nalcalose metabólica promove desvio iônico de potássio para o espaço extracelular. 5. O principal\nachado eletrocardiográfico das alterações de potássio são alterações da onda T. Assinale\nalternativa correta.","options":{"A":"Somente as afirmativas 1, 2 e 5 são verdadeiras.","B":"Somente as afirmativas 1 e 4 são verdadeiras.","C":"Somente as afirmativas 1, 2, 3 e 5 são verdadeiras.","D":"Somente a afirmativa 5 é verdadeira.","E":"Somente as afirmativas 2, 3 e 5 são verdadeiras."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-34473","number":"34473","sourceNumber":"34473","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Um paciente de 14 anos de idade ingeriu grande quantidade de comprimidos de\naspirina. Qual é o distúrbio acidobásico esperado?","options":{"A":"Alcalose metabólica.","B":"Acidose metabólica hiperclorêmica pura ou associada à acidose respiratória.","C":"Alcalose respiratória pura ou associada à acidose\nmetabólica com ânion-gap aumentado.","D":"Alcalose respiratória associada à alcalose metabólica cloreto-responsiva.","E":"Acidose respiratória pura ou associada à alcalose metabólica hipoclorêmica."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-29543","number":"29543","sourceNumber":"29543","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Das gasometrias abaixo, a que será encontrada com maior probabilidade num paciente\nque está vomitando e no início de uma crise\nde broncoespasmo é a que apresenta pH, bicarbonato\n(em mEq/L) e pCO2 (em mmHg) de, respectivamente:","options":{"A":"7,59 - 30 - 48","B":"7,11 - 18 - 54","C":"7,40 - 15 - 26","D":"7,11 - 5,0 - 14","E":"7,59 - 28 - 30"},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-25592","number":"25592","sourceNumber":"25592","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"São sinais característicos da síndrome de secreção inapropriada de hormônio\nantidiurético a:","options":{"A":"Letargia, hiponatremia e hiperosmolaridade urinária.","B":"Confusão mental, hiperosmolaridade plasmática e oligúria.","C":"Coma, hipernatremia, sódio alto na urina.","D":"Poliúria, hiperosmolaridade plasmática e urinária.","E":"Alteração do estado mental, hiponatremia e osmolaridade plasmática baixa."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-25537","number":"25537","sourceNumber":"25537","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Em relação aos distúrbios hidro-eletrolíticos e ácido-básicos, pode-se afirmar que:","options":{"A":"Paciente com desidratação hipernatrêmica deve receber a reposição de água livre em menos de\n12 horas para evitar desmielinização pontina.","B":"Pacientes com hipercalemia e alargamento do complexo QRS só receberão tratamento de\nemergência se houver distúrbio neurológico presente.","C":"Pacientes com hipercalemia refratária a tratamento podem apresentar hipomagnesemia\nassociada.","D":"Choque refratário a volume e drogas costuma ser a primeira apresentação do excesso de cálcio.","E":"As causas mais comuns de hipocalemia são o uso de diuréticos espoliadores de potássio,\nvômito e diarreia."},"answer":"E","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-27874","number":"27874","sourceNumber":"27874","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente apresenta os seguintes exames: K= 8,3 e eletrocardiograma mostrando ondas\nT pontiagudas e simétricas em todas as\nderivações. A primeira medida terapêutica a ser adotada é:\nReferência: GOLDMAN, L.; AUSIELLO, D. Cecil - Tratado de Medicina Interna - 21ª Edição.","options":{"A":"Gluconato de cálcio.","B":"Furosemida.","C":"Solução polarizante.","D":"Resina trocadora de íons.","E":"Bicarbonato de sódio."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-22303","number":"22303","sourceNumber":"22303","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Indique a alternativa que NÃO é uma manifestação clínica observada em pacientes\npediátricos com quadro de hipernatremia aguda.","options":{"A":"Irritabilidade","B":"Hipotermia","C":"Hipertonia","D":"Convulsão","E":"Tremores de extremidades"},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-29629","number":"29629","sourceNumber":"29629","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"No quadro de desidratação aguda decorrente de vômitos incoercíveis,\nobservam-se distúrbios ácido-básico e eletrolítico\ncaracterizado, mais comumente, por:","options":{"A":"Acidose metabólica e hiponatremia.","B":"Alcalose metabólica e hipocloremia.","C":"Alcalose respiratória e hipopotassemia.","D":"Acidose metabólica e hiperpetassemia.","E":"Acidose respiratória e hipernatremia"},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-9848","number":"9848","sourceNumber":"9848","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Assinale a alternativa INCORRETA.","options":{"A":"A hiponatremia tem de ser corrigida com NaCl de 0,9% a 5%.","B":"Paciente com edema sistêmico não deve usar cloreto de sódio.","C":"À paciente com DEEC está indicado infundir solução NaCl a 0,9%.","D":"Em caso de hipernatremia está indicada infusão de soro glicosado 5%.","E":"Em caso de síndrome hiposmolar não deve ser infundida água livre."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-10981","number":"10981","sourceNumber":"10981","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"São causas de alcalose metabólica todas as assertivas abaixo, exceto:","options":{"A":"Intoxicação por salicilatos.","B":"Ingestão de grande quantidade de bicarbonato.","C":"Estado pós-hipocapnia.","D":"Aldosteronismo primário.","E":"Administração de penicilina"},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-327030","number":"327030","sourceNumber":"327030","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Um paciente portador de cirrose alcoólica foi admitido na UTI após apresentar\nhemorragia varicosa que se desenvolveu no terceiro\ndia de tratamento de peritonite bacteriana\nespontânea. Após estabilização hemodinâmica e realização de endoscopia, estava recebendo a\nsegunda unidade de concentrado de hemácias, quando passou a apresentar febre, calafrios e\ndispneia. Rapidamente evoluiu com grave insuficiência respiratória hipoxêmica e, durante a\nintubação orotraqueal, foi observada uma secreção rósea espumosa em vias aéreas. Sobre o\nquadro descrito, assinale a alternativa CORRETA.","options":{"A":"A causa provável da insuficiência respiratória é sepse de foco abdominal.","B":"Devem-se evitar novas hemotransfusões por um período de 120 dias em pacientes que\nsobrevivem a essa complicação.","C":"Antecedente de múltiplas transfusões é fator de risco para essa complicação.","D":"O banco de sangue deve ser notificado para que possa identificar o doador e impedi-lo de\nrealizar novas doações de sangue.","E":"Após a intubação orotraqueal, é possível dar prosseguimento àquela hemotransfusão, desde\nque seja descartada a hipótese de\nhipervolemia."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-277897","number":"277897","sourceNumber":"277897","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Na clínica cirúrgica, o tempo de protombina é utilizado com avaliação pré-operatória da\ncoagulação sanguínea. Em relação a esse teste, assinale a alternativa CORRETA.","options":{"A":"Avalia a via intrínseca da coagulação juntamente com a função plaquetária.","B":"Avalia os fatores VIIa, Xa, IIa e o efeito dos cumarínicos.","C":"Avalia a via extrínseca da coagulação juntamente com o tempo de sangramento.","D":"Também é utilizado no diagnóstico de coagulação intravascular disseminada.","E":"Avalia o efeito do clopidogrel, rivaroxabana e dabigatrana."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-210091","number":"210091","sourceNumber":"210091","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Paciente de 3 anos de idade internado em enfermaria de pediatria com diagnóstico de\ntrombocitopenia imune primária da infância, em repouso no leito, sem uso de medicações. Qual\nalternativa contém a situação clínica mais compatível com a conduta adotada acima?","options":{"A":"Plaquetopenia isolada com valor de 19 mil apresentando petéquias e equimoses sem\nsangramento mucoso.","B":"Plaquetopenia isolada de 9 mil com petéquias e equimoses com sangramento mucoso.","C":"Plaquetas normais com púrpura palpável em membros inferiores e dor abdominal leve.","D":"Plaquetas normais com púrpura palpável em áreas de pressão e sangramento gastrointestinal.","E":"Plaquetas de 13 mil com petéquias, hematomas e artrite em joelhos."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-87343","number":"87343","sourceNumber":"87343","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Um senhor de 60 anos, diabético há 15 anos, foi atendido na emergência com fadiga,\nedema dos membros inferiores, dispneia, palidez ++/4+; PA = 190 x 110 mmHg; FC = 82 bpm;\ncrepitantes bibasais; FR = 32 irpm. Os exames mostram: HT = 32%; glicemia = 182 mg/dl; ureia =\n102 mg/dl; creatinina = 3,0 mg/dl; sódio = 138 mmol/L; potássio = 6,5 mmol/L; cloro = 98 mmol/L;\ncálcio = 8,4 mg/dl; fósforo = 5,5 mg/dl; albumina = 4,1 g/dl; proteinúria de 24 horas de 2,3 g; pH =\n7,22; pO2 = 85 mmHg; pCO2 = 33 mmHg; HCO3 = 14 mEq/L. Qual é o distúrbio acidobásico\npresente no paciente?","options":{"A":"Acidose metabólica com ânion-gap normal.","B":"Acidose metabólica com alto ânion-gap normal.","C":"Acidose mista com alto ânion-gap normal.","D":"Acidose mista com alto ânion-gap.","E":"Acidose respiratória com ânion-gap normal."},"answer":"D","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-87376","number":"87376","sourceNumber":"87376","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Menor com dois meses, internado em insuficiência respiratória aguda devido à\nbronquiolite. Em uso de máscara de Venturi a\n40%. Colhido gasometria com o seguinte resultado:\npH = 7,25, PO2 = 92%, pCO2 = 60 mmHg, Bic = 16 mEq/l. Qual é a sua interpretação?","options":{"A":"Acidose metabólica pura","B":"Acidose mista","C":"Gasimetria arterial normal","D":"Acidose respiratória pura","E":"Alcalose respiratória"},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-88614","number":"88614","sourceNumber":"88614","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Um paciente de 60 anos, portador de carcinoma de pequenas células de pulmão foi\ntrazido para a emergência pelos familiares por conta de rebaixamento do nível de consciência há\nalgumas horas. Ao exame físico, mostrava-se torporoso, abrindo os olhos aos estímulos dolorosos\ne respondendo a comandos simples, mas sem resposta verbal. Realizou ressonância de crânio,\nque descartou metástases cerebrais. Exames laboratoriais revelaram sódio sérico de 118 mEq/L.\nPensando na possibilidade de síndrome de secreção inapropriada de ADH, assinale o achado que\nnão deverá estar presente nesse caso.","options":{"A":"Redução dos níveis séricos de ácido úrico.","B":"Sódio urinário abaixo de 20 mEq/L.","C":"Hiperosmolaridade urinária.","D":"Hipo-osmolaridade sérica.","E":"Redução dos níveis séricos de ureia."},"answer":"B","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-88616","number":"88616","sourceNumber":"88616","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"São causas de acidose metabólica com ânion-gap aumentado, EXCETO:","options":{"A":"acidose láctica.","B":"cetoacidose diabética.","C":"diarreia aguda grave.","D":"intoxicação por ácido acetilsalicílico.","E":"intoxicação por metanol."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-64821","number":"64821","sourceNumber":"64821","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"O supradesnivelamento do segmento ST no eletrocardiograma é encontrado em todas\nas situações abaixo, EXCETO em:","options":{"A":"Pericardite.","B":"Hipertrofia ventricular esquerda.","C":"Hipocalcemia.","D":"Aneurisma crônico de ventrículo esquerdo.","E":"Hiperpotassemia."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-64761","number":"64761","sourceNumber":"64761","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Todas as alternativas abaixo são causa de hipocalemia, EXCETO:","options":{"A":"uso de anfotericina B.","B":"acidose tubular renal tipo 1.","C":"uso da ciclosporina.","D":"hipomagnesemia.","E":"diarreia severa."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-70708","number":"70708","sourceNumber":"70708","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"Em relação ao manuseio hidroeletrolítico do paciente cirúrgico, é correto afirmar que:","options":{"A":"deve-se estimar a quantidade de água corporal total nos obesos, acrescentando 10% a 15% do\npeso corpóreo.","B":"a hipernatremia é diagnóstica de depleção do compartimento líquido extracelular.","C":"na sobrecarga de líquido extracelular, usualmente estão envolvidos tanto o volume intersticial\nquanto o volume plasmático.","D":"os recém-nascidos apresentam a maior proporção de água por peso corporal (cerca de 80%),\nporém essa proporção diminui para 65% por volta do 2º ano de vida, daí permanecendo mais ou\nmenos constante."},"answer":"C","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-19-46559","number":"46559","sourceNumber":"46559","collectionBlock":"med:med-clinica-medica-med-clm-19","collectionLabel":"MED · MED CLM 19","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 19","subtopic":"","stem":"São causas de acidose metabólica, EXCETO:","options":{"A":"Administração excessiva de acetato na nutrição parenteral.","B":"Ureterossigmoidostomia.","C":"Acetazolamida (inibidor da anidrase carbônica).","D":"Ingestão significativa de metanol."},"answer":"A","source":"Clinica médica/MED CLM 19/MED CLM 19.txt","sourceLabel":"MED · MED CLM 19","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 19","MED"],"answerSource":"explicit","commentDeferred":true}]};
